function InterfaceHeadroomGauge({ item }: { item?: InterfaceListItem }) {
  const usage = interfaceCombinedUsage(item);
  const headroom = usage !== undefined ? 1 - usage : undefined;
  return (
    <span className="interface-headroom">
      <SemiDonutGauge value={headroom} mode="headroom" size={54} />
      <span>
        <strong>{formatPercent(headroom)}</strong>
        <small>free</small>
      </span>
    </span>
  );
}

function SemiDonutGauge({ value, mode, size = 64 }: { value?: number; mode: "headroom" | "usage"; size?: number }) {
  const radius = 26;
  const circumference = Math.PI * radius;
  const clamped = value === undefined ? 0 : Math.max(0, Math.min(1, value));
  const dash = clamped * circumference;
  const hasVisibleValue = value !== undefined && clamped >= 0.01;
  return (
    <svg className={`semi-donut semi-donut-${mode} ${value === undefined ? "unknown" : ""}`} width={size} height={Math.round(size * 0.58)} viewBox="0 0 64 38" aria-hidden="true">
      <path className="semi-donut-track" d="M6 32a26 26 0 0 1 52 0" pathLength={circumference} />
      {hasVisibleValue && <path className="semi-donut-value" d="M6 32a26 26 0 0 1 52 0" pathLength={circumference} strokeDasharray={`${dash} ${circumference - dash}`} />}
    </svg>
  );
}

function StreamOverviewSummary({ streams }: { streams: StreamListItem[] }) {
  const entries = buildTopBitrateEntries(streams);
  const total = entries.reduce((sum, entry) => sum + entry.value, 0);
  const circumference = 2 * Math.PI * 18;
  let offset = 0;

  return (
    <section className="stream-overview-summary" aria-label="Bitrate share summary">
      <div className="bitrate-donut" aria-hidden="true">
        <svg viewBox="0 0 48 48">
          <circle className="bitrate-donut-track" cx="24" cy="24" r="18" />
          {total > 0 && entries.map((entry, index) => {
            const length = (entry.value / total) * circumference;
            const segment = (
              <circle
                key={entry.key}
                className="bitrate-donut-segment"
                cx="24"
                cy="24"
                r="18"
                stroke={DONUT_COLORS[index % DONUT_COLORS.length]}
                strokeDasharray={`${length} ${circumference - length}`}
                strokeDashoffset={-offset}
              />
            );
            offset += length;
            return segment;
          })}
        </svg>
      </div>
      <div className="bitrate-share-list">
        {entries.map((entry, index) => (
          <span key={entry.key}>
            <i style={{ background: DONUT_COLORS[index % DONUT_COLORS.length] }} />
            <strong>{entry.label}</strong>
            <small>{entry.percent}%</small>
          </span>
        ))}
      </div>
    </section>
  );
}

function BitrateShareBar({ value, max }: { value: number; max: number }) {
  const percent = Math.max(0, Math.min(100, (value / max) * 100));
  return (
    <span className="bitrate-share-bar" aria-label={`Bitrate share ${Math.round(percent)} percent`}>
      <span style={{ width: `${percent}%` }} />
    </span>
  );
}

function FlowRow({ streamKey, flow, selected, overviewMode, enableCharts, onSelect, onAddToDashboard }: { streamKey: string; flow: FlowListItem; selected: boolean; overviewMode: boolean; enableCharts: boolean; onSelect: () => void; onAddToDashboard?: (streamKey: string, flowKey?: string) => void }) {
  const flowBitrate = flow.bitrate.value ?? flow.bitrate.avg ?? 0;
  const color = flowLineColor(flow.role);
  return (
    <div
      role="button"
      tabIndex={0}
      className={`flow-list-row ${selected ? "selected" : ""}`}
      onClick={onSelect}
      onKeyDown={(event) => {
        if (event.target !== event.currentTarget || (event.key !== "Enter" && event.key !== " ")) return;
        event.preventDefault();
        onSelect();
      }}
    >
      <span className={`status-dot `} />
      <span className="flow-main"><span className="flow-title"><span>{flow.endpointSrc ?? "Unknown endpoint"} → {flow.endpointDst ?? "Unknown endpoint"}</span>{displayFlowRole(flow.role) && <span className="flow-role">{displayFlowRole(flow.role)}</span>}</span></span>
      <span className="row-right flow-row-right"><span className="stream-rate">{formatBitrate(flowBitrate)}</span>{enableCharts && <Sparkline values={flow.sparkline} width={150} height={24} color={color} strokeWidth={1.1} />}{overviewMode && enableCharts && <OverviewStats stats={flow.overview} />}</span>
      <RowActionMenu streamKey={streamKey} flowKey={flow.flowKey} onAddToDashboard={onAddToDashboard} />
    </div>
  );
}

function RowActionMenu({ streamKey, flowKey, onAddToDashboard }: { streamKey: string; flowKey?: string; onAddToDashboard?: (streamKey: string, flowKey?: string) => void }) {
  const [opened, setOpened] = useState(false);
  const menuRef = useRef<HTMLSpanElement>(null);
  const detailUrl = flowKey ? detailUrlForFlow(streamKey, flowKey) : detailUrlForStream(streamKey);
  const keyLabel = flowKey ? "Copy flow key" : "Copy stream key";
  const keyValue = flowKey ?? streamKey;

  useEffect(() => {
    if (!opened) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!menuRef.current?.contains(event.target as Node)) setOpened(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpened(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [opened]);

  return (
    <span
      ref={menuRef}
      className="row-action-menu"
      onClick={(event) => {
        event.stopPropagation();
      }}
    >
      <button type="button" className="row-action-trigger" aria-label="Open row actions" aria-expanded={opened} onClick={() => setOpened((current) => !current)}>
        <Icon name="more" size={17} />
      </button>
      {opened && <span className="row-action-popup" role="menu" aria-label="Row actions">
        <button type="button" role="menuitem" onClick={() => { setOpened(false); void copyText(detailUrl); }}>Copy detail URL</button>
        <button type="button" role="menuitem" onClick={() => { setOpened(false); void copyText(keyValue); }}>{keyLabel}</button>
        {onAddToDashboard && <button type="button" role="menuitem" onClick={() => { setOpened(false); onAddToDashboard(streamKey, flowKey); }}>Add Detail to Dashboard</button>}
      </span>}
    </span>
  );
}

