export type EventLogTab = "all" | "selected";

export function EventLog({
  events,
  eventsRange,
  onChangeEventsRange,
  selectedStreamKey,
  selectedFlowKey,
  selectedInterfaceId,
  initialQuery = "",
  query: controlledQuery,
  onChangeQuery,
  showSearch = true,
  tab: controlledTab,
  onChangeTab,
  showHeader = true,
  selectedTimeSec = null,
  onSelectTime,
  columnWidths: controlledColumnWidths,
