import { StatusBadge } from "./StatusBadge";
import { Icon, type IconName } from "./Icon";

type AppContextBarProps = {
  title?: string;
  icon?: IconName;
  updatedLabel: string;
  socketState: string;
  totalStreams?: number;
  liveLabel: string;
  liveTone: "success" | "warning";
  onToggleLive: () => void;
  onToggleTheme: () => void;
  theme: "light" | "dark";
  compact?: boolean;
};

export function AppContextBar({
  title = "Media Stream Monitor",
  icon,
  updatedLabel,
  socketState,
  totalStreams,
  liveLabel,
  liveTone,
  onToggleLive,
  onToggleTheme,
  theme,
  compact = false
}: AppContextBarProps) {
  return (
    <header className={`app-context-bar ${compact ? "app-context-bar-compact" : ""}`}>
      <div className="app-context-identity">
        {icon && <Icon className="app-context-icon" name={icon} size={14} />}
        <strong>{title}</strong>
        <span>{updatedLabel}</span>
      </div>
      <div className="app-context-status" aria-label="Application status">
        {totalStreams !== undefined && <StatusBadge>{totalStreams} streams</StatusBadge>}
        <StatusBadge>{socketState}</StatusBadge>
        <button type="button" className={`context-live-toggle is-${liveTone}`} onClick={onToggleLive} title="Toggle live updates">
          <span aria-hidden="true" />
          {liveLabel}
        </button>
        <button
          type="button"
          className="context-theme-toggle icon-only"
          onClick={onToggleTheme}
          title={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
          aria-label={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
        >
          <Icon name={theme === "light" ? "themeDark" : "themeLight"} size={16} />
        </button>
      </div>
    </header>
  );
}
import { Fragment, useEffect, useMemo, useRef, useState } from "react";
import type { NetworkScope, TimelineDataGap, TimelineRow } from "../types/api";
import { Icon } from "./ui/Icon";

type TimelinePaneProps = {
  rows: TimelineRow[];
  gaps?: TimelineDataGap[];
  nowSec: number;
  fadeSec: number;
  rangeStartSec: number;
  rangeEndSec: number;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  selectedTimeSec?: number | null;
  onSelectTime?: (timeSec: number) => void;
  interfaceNames?: ReadonlyMap<number, string>;
};

type TimelineStreamGroup = { stream: TimelineRow; flows: TimelineRow[] };
type TimelineScopeGroup = {
  key: string;
  label: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};
type TimelineProtoGroup = {
  key: string;
  proto: string;
  rows: TimelineStreamGroup[];
  segments: Array<{ start: number; end: number }>;
  active: boolean;
};

export function TimelinePane({ rows, gaps = [], nowSec, fadeSec, rangeStartSec, rangeEndSec, expandLevel = "stream", selectedTimeSec = null, onSelectTime, interfaceNames }: TimelinePaneProps) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [interfaceExpanded, setInterfaceExpanded] = useState<Record<string, boolean>>({});
  const [scopeExpanded, setScopeExpanded] = useState<Record<string, boolean>>({});
  const [protoExpanded, setProtoExpanded] = useState<Record<string, boolean>>({});
  const axisScaleRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<HTMLDivElement | null>(null);
  const [cursorSec, setCursorSec] = useState(nowSec);
  const [isHoveringCursor, setIsHoveringCursor] = useState(false);
  const [hoveredRowKey, setHoveredRowKey] = useState<string | null>(null);
  const [viewport, setViewport] = useState({ top: 0, height: 480 });
  const cursorRafRef = useRef<number | null>(null);
  const pendingCursorXRef = useRef<number | null>(null);
  const hasAppliedExpandLevel = useRef(false);
  const previousExpandLevel = useRef<typeof expandLevel>(expandLevel);

  useEffect(() => {
    if (!isHoveringCursor) {
      setCursorSec(Math.min(rangeEndSec, Math.max(rangeStartSec, nowSec)));
    }
  }, [isHoveringCursor, nowSec, rangeStartSec, rangeEndSec]);

  const updateCursor = (clientX: number) => {
    const el = axisScaleRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0) return;
    const x = Math.min(rect.right, Math.max(rect.left, clientX));
    const ratio = (x - rect.left) / Math.max(1, rect.width);
