    keyEvent.preventDefault();
    onMoveSelection(direction);
  };
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level}${primarySelected ? " event-primary-selected" : ""}${related ? " event-related" : ""}${measurementAnchor ? " event-measurement-anchor" : ""}${timeNeighbor ? " time-neighbor" : ""}`} onClick={onSelect} onKeyDown={onKeyDown} title={syncTimeOnSelect ? "Inspect this event and sync its timestamp. Shift+click to add it to time measurement. Use Up/Down to select adjacent events." : "Inspect this event. Shift+click to add it to time measurement. Use Up/Down to select adjacent events."} aria-current={primarySelected ? "true" : undefined} aria-keyshortcuts="ArrowUp ArrowDown">
