function EventRow({ event, primarySelected, related, measurementAnchorNumber, timeNeighbor, onSelect, onMoveSelection, eventRef, syncTimeOnSelect }: { event: EventLogItem; primarySelected: boolean; related: boolean; measurementAnchorNumber?: number; timeNeighbor: boolean; onSelect: (event: ReactMouseEvent<HTMLButtonElement>) => void; onMoveSelection: (direction: -1 | 1) => void; eventRef: (element: HTMLButtonElement | null) => void; syncTimeOnSelect: boolean }) {
  const timeLabel = formatEventTime(event.time);
  const targetLabel = event.targetLabel ?? event.proto ?? event.scope;
  const onKeyDown = (keyEvent: ReactKeyboardEvent<HTMLButtonElement>) => {
    const direction = keyEvent.key === "ArrowUp" ? -1 : keyEvent.key === "ArrowDown" ? 1 : null;
    if (direction === null) return;
    keyEvent.preventDefault();
    onMoveSelection(direction);
  };
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level}${primarySelected ? " event-primary-selected" : ""}${related ? " event-related" : ""}${measurementAnchorNumber !== undefined ? " event-measurement-anchor" : ""}${timeNeighbor ? " time-neighbor" : ""}`} onClick={onSelect} onKeyDown={onKeyDown} title={syncTimeOnSelect ? "Inspect this event and sync its timestamp. Shift+click to add it to time measurement. Use Up/Down to select adjacent events." : "Inspect this event. Shift+click to add it to time measurement. Use Up/Down to select adjacent events."} aria-current={primarySelected ? "true" : undefined} aria-keyshortcuts="ArrowUp ArrowDown">
      <span className="event-marker" aria-label={measurementAnchorNumber === undefined ? undefined : `Measurement anchor ${measurementAnchorNumber}`}>{measurementAnchorNumber === undefined ? "" : `#${measurementAnchorNumber}`}</span>
      <time className="event-time" dateTime={new Date(event.time * 1000).toISOString()} title={timeLabel}>{timeLabel}</time>
      <span className="event-level" title={event.level}>{event.level}</span>
      <span className="event-target" title={targetLabel}>{targetLabel}</span>
      <span className="event-message" title={event.message}>{event.message}</span>
    </button>
  );
}

function EventMeasurement({ anchors, onClear }: { anchors: MeasurementAnchor[]; onClear: () => void }) {
  const total = anchors.length > 1 ? anchors[anchors.length - 1].event.time - anchors[0].event.time : null;
  return <section className="event-measurement" aria-label="Event time measurement">
    <div className="event-measurement-summary">
      <strong>Measure</strong>
      {total === null ? <span>#{anchors[0].number} · Shift+click another event</span> : <span>#{anchors[0].number} → #{anchors[anchors.length - 1].number} · Δ {formatDuration(total)}</span>}
      <button type="button" onClick={onClear}>Clear</button>
    </div>
    {anchors.length > 1 && <ol className="event-measurement-segments">
      {anchors.slice(1).map((anchor, index) => {
        const previous = anchors[index];
        return <li key={anchor.event.id} title={`${formatEventTime(previous.event.time)} → ${formatEventTime(anchor.event.time)}`}>
          <span>#{previous.number} {formatEventAnchorLabel(previous.event)} → #{anchor.number} {formatEventAnchorLabel(anchor.event)}</span>
          <strong>Δ {formatDuration(anchor.event.time - previous.event.time)}</strong>
        </li>;
      })}
    </ol>}
  </section>;
}

function EventContext({ event, onClose, onSyncTime, relatedEvent, relatedOutsideRange = false, onSelectRelated, inline = false }: { event: EventLogItem; onClose: () => void; onSyncTime?: () => void; relatedEvent?: EventLogItem | null; relatedOutsideRange?: boolean; onSelectRelated?: () => void; inline?: boolean }) {
  return (
    <aside className={`event-context${inline ? " event-context-inline" : ""}`} aria-label="Selected event detail">
      <div className="event-context-header">
        <strong>Event detail</strong>
        <div className="event-context-actions">
          {onSyncTime && <button type="button" className="event-context-sync" onClick={onSyncTime} title="Set Dashboard time to this event">Sync time</button>}
          <button type="button" onClick={onClose} aria-label="Close event detail" title="Close event detail"><Icon name="close" size={16} /></button>
        </div>
      </div>
      <dl>
        <dt>Time</dt><dd>{formatEventTime(event.time)}</dd>
        <dt>Level</dt><dd>{event.level}</dd>
        <dt>Type</dt><dd>{event.type}</dd>
        <dt>Target</dt><dd>{event.targetLabel ?? event.proto ?? event.scope}</dd>
      </dl>
      {relatedEvent && onSelectRelated && <div className="event-context-related">
        <span>Go to related event</span>
        <button type="button" onClick={onSelectRelated} title="Go to related event" aria-label={`Go to related event: ${relatedEvent.message} · ${formatEventTime(relatedEvent.time)}`}><span className="event-context-related-message">{relatedEvent.message}</span><time className="event-context-related-time" dateTime={new Date(relatedEvent.time * 1000).toISOString()}>{formatEventTime(relatedEvent.time)}</time></button>
        {relatedOutsideRange && <small>Outside current range</small>}
      </div>}
      <p>{event.message}</p>
      {event.detail !== undefined && <pre>{JSON.stringify(event.detail, null, 2)}</pre>}
    </aside>
  );
}


function formatEventAnchorLabel(event: EventLogItem) {
  const time = formatEventTime(event.time).slice(11);
  const target = event.targetLabel ?? event.proto ?? event.scope;
  return `${time} · ${target}`;
}

function formatDuration(seconds: number) {
  if (seconds < 1) return `${(seconds * 1000).toFixed(1)} ms`;
  if (seconds < 60) return `${seconds.toFixed(3)} s`;
  const minutes = Math.floor(seconds / 60);
  const remaining = seconds - minutes * 60;
  if (minutes < 60) return `${minutes}m ${remaining.toFixed(3)}s`;
  const hours = Math.floor(minutes / 60);
  return `${hours}h ${minutes % 60}m ${remaining.toFixed(3)}s`;
}

function eventRelationFor(event: EventLogItem): EventRelation | null {
  const lifecycle = event.type.match(/^(stream|flow)_(detected|recovered|lost)$/);
  if (lifecycle) {
    const [, subject, action] = lifecycle;
    if (action === "lost") return { counterpartTypes: [`${subject}_detected`, `${subject}_recovered`], direction: "before" };
    return { counterpartTypes: [`${subject}_lost`], direction: "after" };
  }
  if (event.type.endsWith("_occurred")) return { counterpartTypes: [`${event.type.slice(0, -"occurred".length)}recovered`], direction: "after" };
  if (event.type.endsWith("_recovered")) return { counterpartTypes: [`${event.type.slice(0, -"recovered".length)}occurred`], direction: "before" };
  return null;
}
