  diagnosticLog: toBool(argv.diagnosticLog ?? process.env.STM_DIAGNOSTIC_LOG, false),
  dashboardLayoutEditMode: dashboardLayoutEditMode(process.env.DASHBOARD_LAYOUT_EDIT_MODE, toBool(process.env.DASHBOARD_PUSH_ON_EDIT, false)),
  streamsErrorCountMode: streamsErrorCountMode(process.env.STREAMS_ERROR_COUNT_MODE),
  historicalSparklines: toBool(process.env.HISTORICAL_SPARKLINES, false),
