int event_sink::emit(const event_record &e) {
	event_record decorated = e;
	if(decorated.source.is_object() && !decorated.source.contains("name")) {
		const auto stream_key = decorated.source.value("stream_key", std::string{});
		if(const auto it = m_stream_display_names.find(stream_key); it != m_stream_display_names.end()) {
