	int rc = 0;
	for(auto *consumer : m_consumers) {
		if(consumer == nullptr) {
			continue;
		}
		const int consumer_rc = consumer->handle_event(decorated);
		if(rc == 0 && consumer_rc != 0) {
			rc = consumer_rc;
		}
	}
	return rc;
