   292	void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
   293		if(!s.has_last_value) {
   294			s.has_last_value = true;
   295			s.last_value = value;
   296			return;
   297		}
   298	
   299		const double delta = value - s.last_value;
   300		s.last_value = value;
   301		if(compare(delta, r.op, r.delta_threshold)) {
   302			json detail{
   303				{"metric", r.metric},
   304				{"value", value},
   305				{"delta", delta},
   306				{"threshold", r.delta_threshold},
   307			};
   308			if(!s.active) {
   309				s.active = true;
   310				emit_alert(now, r, entry, is_interface, "detected", value, detail);
   311			}
   312			s.last_error_time = now;
   313			update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
   314			return;
   315		}
   316	
   317		if(s.active && (now - s.last_error_time) >= r.recover_after_sec) {
   318			s.active = false;
   319			emit_alert(now, r, entry, is_interface, "recovered", value, json{
   320				{"metric", r.metric},
   321				{"value", value},
   322				{"delta", delta},
   323				{"recover_after_sec", r.recover_after_sec},
   324			});
   325		}
   326	}
