   256	void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
   257		if(!s.active) {
   258			if(compare(value, r.op, r.error_threshold)) {
   259				s.active = true;
   260				s.last_error_time = now;
   261				json detail{
   262					{"metric", r.metric},
   263					{"value", value},
   264					{"threshold", r.error_threshold},
   265					{"operator", "error"},
   266				};
