   256	void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
   257		if(!s.active) {
   258			if(compare(value, r.op, r.error_threshold)) {
   259				s.active = true;
   260				s.last_error_time = now;
   261				json detail{
   262					{"metric", r.metric},
   263					{"value", value},
   264					{"threshold", r.error_threshold},
   265					{"operator", "error"},
   266				};
   267				update_active_state(now, r, entry, is_interface, s, value, detail);
   268				emit_alert(now, r, entry, is_interface, "detected", value, std::move(detail));
   269			}
   270			return;
   271		}
   272	
   273		if(!compare(value, r.op, r.recover_threshold)) {
   274			s.active = false;
   275			emit_alert(now, r, entry, is_interface, "recovered", value, json{
   276				{"metric", r.metric},
   277				{"value", value},
   278				{"threshold", r.recover_threshold},
   279				{"operator", "recover"},
   280			});
   281			return;
   282		}
   283	
   284		update_active_state(now, r, entry, is_interface, s, value, json{
   285			{"metric", r.metric},
   286			{"value", value},
   287			{"threshold", r.error_threshold},
   288			{"operator", "error"},
   289		});
   290	}
