   158			for(const auto &r : library) { if(!rules_by_id.emplace(r.id, r).second) { std::cerr << "alert_evaluator: duplicate rule id " << r.id << std::endl; return -1; } }
   159			std::map<std::string, std::vector<std::string>> profiles;
   160			for(const auto &profile : root["profiles"]) {
   161				if(!profile.is_object() || !profile.contains("id") || !profile["id"].is_string() || !profile.contains("rule_ids") || !profile["rule_ids"].is_array()) { std::cerr << "alert_evaluator: invalid profile" << std::endl; return -1; }
   162				const auto id = profile["id"].get<std::string>();
   163				if(id.empty() || profiles.contains(id)) { std::cerr << "alert_evaluator: duplicate or empty profile id" << std::endl; return -1; }
   164				auto &ids = profiles[id];
   165				for(const auto &rule_id : profile["rule_ids"]) { if(!rule_id.is_string() || !rules_by_id.contains(rule_id.get<std::string>())) { std::cerr << "alert_evaluator: unknown profile rule id" << std::endl; return -1; } ids.push_back(rule_id.get<std::string>()); }
   166			}
   167			m_rules.clear();
   168			std::set<std::string> assigned;
   169			for(const auto &assignment : root["assignments"]) {
   170				if(!assignment.is_object() || !assignment.contains("scope") || !assignment["scope"].is_object() || !assignment.contains("profile_ids") || !assignment["profile_ids"].is_array()) { std::cerr << "alert_evaluator: invalid assignment" << std::endl; return -1; }
   171				const auto &scope = assignment["scope"];
   172				if(!scope.contains("kind") || !scope["kind"].is_string()) { std::cerr << "alert_evaluator: assignment scope requires kind" << std::endl; return -1; }
   173				const auto kind = scope["kind"].get<std::string>();
   174				std::string target_id; int priority = 0; std::string scoped_proto; std::string scoped_target;
   175				if(kind == "protocol") { if(scope.contains("proto")) { if(!scope["proto"].is_string()) { std::cerr << "alert_evaluator: protocol scope proto must be string" << std::endl; return -1; } scoped_proto = scope["proto"].get<std::string>(); } if(scope.contains("target")) { if(!scope["target"].is_string()) { std::cerr << "alert_evaluator: protocol scope target must be string" << std::endl; return -1; } scoped_target = scope["target"].get<std::string>(); } }
   176				else if(kind == "managed_target") { if(!scope.contains("target_id") || !scope["target_id"].is_string() || scope["target_id"].get<std::string>().empty()) { std::cerr << "alert_evaluator: managed_target scope requires target_id" << std::endl; return -1; } target_id = scope["target_id"].get<std::string>(); priority = scope.contains("target_type") && scope["target_type"] == "group" ? 1 : 2; }
   177				else { std::cerr << "alert_evaluator: unknown assignment scope kind" << std::endl; return -1; }
   178				for(const auto &profile_id : assignment["profile_ids"]) {
   179					if(!profile_id.is_string() || !profiles.contains(profile_id.get<std::string>())) { std::cerr << "alert_evaluator: unknown assignment profile" << std::endl; return -1; }
   180					for(const auto &rule_id : profiles[profile_id.get<std::string>()]) {
   181						rule r = rules_by_id.at(rule_id); r.monitoring_target_id = target_id; r.scope_priority = priority; if(!scoped_proto.empty()) r.proto = scoped_proto; if(!scoped_target.empty()) r.target = scoped_target; if(!r.flow_roles.empty() && r.target != "flow") { std::cerr << "alert_evaluator: flow_roles requires flow target after assignment" << std::endl; return -1; }
