   183						const auto key = r.id + "|" + target_id + "|" + std::to_string(priority); if(!assigned.insert(key).second) { std::cerr << "alert_evaluator: conflicting assignment for " << r.id << std::endl; return -1; } m_rules.push_back(std::move(r));
