   192	void alert_evaluator::evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces) {
   193		auto evaluate_entries = [this, now](const json::array_t &entries, bool is_interface) {
   194			for(const auto &entry : entries) {
   195				if(!entry.is_object()) continue;
   225			entry["last_value"] = s.last_value;
   226			entry["last_error_time"] = s.last_error_time;
   227			entry["last_seen_time"] = s.last_seen_time;
   228			out.push_back(std::move(entry));
   229		}
   230		return out;
   231	}
   232	
   233	void alert_evaluator::evaluate_entry(double now, const rule &r, const json &entry, bool is_interface) {
   234		if(!matches_target(r, entry, is_interface)) {
   235			return;
   236		}
   237		auto value = metric_value(entry, r.metric);
   238		if(!value.has_value() || !std::isfinite(*value)) {
   239			return;
   240		}
   241	
   242		const auto state_key = make_state_key(r, entry, is_interface);
   243		auto &s = m_states[state_key];
   244		s.last_seen_time = now;
   245	
   246		switch(r.type) {
   247		case rule_type::threshold:
   248			evaluate_threshold(now, r, entry, is_interface, state_key, s, *value);
   249			break;
   250		case rule_type::counter_delta:
   251			evaluate_counter_delta(now, r, entry, is_interface, state_key, s, *value);
   252			break;
   253		}
   254	}
   255	
   256	void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
   257		if(!s.active) {
   258			if(compare(value, r.op, r.error_threshold)) {
   259				s.active = true;
   260				s.last_error_time = now;
   261				json detail{
   262					{"metric", r.metric},
   263					{"value", value},
   264					{"threshold", r.error_threshold},
   265					{"operator", "error"},
   266				};
   267				update_active_state(now, r, entry, is_interface, s, value, detail);
   268				emit_alert(now, r, entry, is_interface, "detected", value, std::move(detail));
   269			}
   270			return;
   271		}
   272	
   273		if(!compare(value, r.op, r.recover_threshold)) {
   274			s.active = false;
   275			emit_alert(now, r, entry, is_interface, "recovered", value, json{
   276				{"metric", r.metric},
   277				{"value", value},
   278				{"threshold", r.recover_threshold},
   279				{"operator", "recover"},
   280			});
   281			return;
   282		}
   283	
   284		update_active_state(now, r, entry, is_interface, s, value, json{
   285			{"metric", r.metric},
   286			{"value", value},
   287			{"threshold", r.error_threshold},
   288			{"operator", "error"},
   289		});
   290	}
   291	
   292	void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
   293		if(!s.has_last_value) {
   294			s.has_last_value = true;
   295			s.last_value = value;
   296			return;
   297		}
   298	
   299		const double delta = value - s.last_value;
   300		s.last_value = value;
   301		if(compare(delta, r.op, r.delta_threshold)) {
   302			json detail{
   303				{"metric", r.metric},
   304				{"value", value},
   305				{"delta", delta},
   306				{"threshold", r.delta_threshold},
   307			};
   308			if(!s.active) {
   309				s.active = true;
   310				emit_alert(now, r, entry, is_interface, "detected", value, detail);
   311			}
   312			s.last_error_time = now;
   313			update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
   314			return;
   315		}
   316	
   317		if(s.active && (now - s.last_error_time) >= r.recover_after_sec) {
   318			s.active = false;
   319			emit_alert(now, r, entry, is_interface, "recovered", value, json{
   320				{"metric", r.metric},
   321				{"value", value},
   322				{"delta", delta},
   323				{"recover_after_sec", r.recover_after_sec},
   324			});
   325		}
   326	}
   327	
   328	void alert_evaluator::emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail) {
   329		detail["alert_id"] = r.id;
   330		detail["state_key"] = make_state_key(r, entry, is_interface);
   331		detail["severity"] = r.severity;
   332		detail["indicator_category"] = r.indicator_category;
   333		detail["action"] = action;
   334		detail["value"] = value;
   335	
   336		m_events.emit(event_record{
   337			.time_epoch = now,
   338			.type = action == "detected" ? "alert_detected" : "alert_recovered",
   339			.source = make_target_source(r, entry, is_interface),
   340			.detail = std::move(detail),
   341		});
   342	}
   343	
   344	void alert_evaluator::update_active_state(double now, const rule &r, const json &entry, bool is_interface, state &s, double value, json detail) {
   345		detail["alert_id"] = r.id;
   346		detail["severity"] = r.severity;
   347		detail["indicator_category"] = r.indicator_category;
   348		detail["value"] = value;
   349		s.source = make_target_source(r, entry, is_interface);
