295	void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
296		if(!s.has_last_value) {
297			s.has_last_value = true;
298			s.last_value = value;
299			return;
300		}
301	
302		const double delta = value - s.last_value;
303		s.last_value = value;
304		if(compare(delta, r.op, r.delta_threshold)) {
305			json detail{
306				{"metric", r.metric},
307				{"value", value},
308				{"delta", delta},
309				{"threshold", r.delta_threshold},
310			};
311			if(!s.active) {
312				s.active = true;
313				emit_alert(now, r, entry, is_interface, "detected", value, detail);
314			}
315			s.last_error_time = now;
316			update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
317			return;
318		}
319	
320		if(s.active && (now - s.last_error_time) >= r.recover_after_sec) {
321			s.active = false;
322			emit_alert(now, r, entry, is_interface, "recovered", value, json{
323				{"metric", r.metric},
324				{"value", value},
325				{"delta", delta},
326				{"recover_after_sec", r.recover_after_sec},
327			});
328		}
