358	std::optional<double> alert_evaluator::metric_value(const json &entry, const std::string &path) {
359		const json *cur = &entry;
360		for(const auto &part : split_path(path)) {
361			if(!cur->is_object() || !cur->contains(part)) {
362				return std::nullopt;
363			}
364			cur = &(*cur)[part];
365		}
366		if(cur->is_number()) {
367			return cur->get<double>();
368		}
369		return std::nullopt;
370	}
