 42		}
 43		if(e.type.rfind("stream_", 0) == 0 || e.type.rfind("flow_", 0) == 0) {
 44			return false;
 45		}
 46		return ends_with(e.type, "_occurred") || ends_with(e.type, "_recovered");
 47	}
 48	
 49	std::string marker_action(const std::string &type) {
 50		if(ends_with(type, "_detected") || ends_with(type, "_occurred")) {
 51			return "detected";
 52		if(type == "alert_data_unavailable") return "unavailable";
 53		if(type == "alert_data_available") return "available";
 54		}
 55		if(ends_with(type, "_recovered")) {
 56			return "recovered";
 57		}
 58		return "event";
 59	}
