 61	json make_marker_subject(const event_record &e) {
 62		json subject = e.source.is_object() ? e.source : json::object();
 63		if(!subject.contains("type")) {
 64			if(subject.contains("target") && subject["target"].is_string()) {
 65				subject["type"] = subject["target"];
 66			}
 67			else if(subject.contains("flow_key")) {
 68				subject["type"] = "flow";
 69			}
 70			else if(subject.contains("stream_key")) {
 71				subject["type"] = "stream";
 72			}
 73			else if(subject.contains("interface_id") || subject.contains("name")) {
 74				subject["type"] = "interface";
 75			}
 76		}
 77		return subject;
 78	}
 79	
 80	json make_marker_detail(const event_record &e) {
 81		json detail = e.detail.is_object() ? e.detail : json::object();
 82		detail["event_type"] = e.type;
 83		detail["action"] = marker_action(e.type);
 84		if(e.source.is_object()) {
 85			for(const auto &key : {"alert_id", "severity", "target", "proto", "stream_key", "flow_key", "interface_id", "name"}) {
 86				if(e.source.contains(key) && !detail.contains(key)) {
 87					detail[key] = e.source[key];
 88				}
 89			}
 90		}
 91		if(!detail.contains("label")) {
 92			if(detail.contains("alert_id") && detail["alert_id"].is_string()) {
 93				detail["label"] = detail["alert_id"];
 94			}
 95			else if(detail.contains("metric") && detail["metric"].is_string()) {
 96				detail["label"] = detail["metric"];
 97			}
 98			else {
 99				detail["label"] = e.type;
100			}
101			detail["severity"] = (e.type == "alert_detected" || e.type == "alert_data_unavailable") ? "warning" : "info";
102		if(!detail.contains("severity")) {
103			detail["severity"] = e.type == "alert_detected" ? "warning" : "info";
104		}
105		return detail;
106	}
