 31	std::string json_string_or_empty(const json &j, const char *key) {
 32		if(!j.is_object() || !j.contains(key) || j[key].is_null()) {
 33			return {};
 34		}
 35		if(j[key].is_string()) {
 36			return j[key].get<std::string>();
 37		}
 38		if(j[key].is_number_integer()) {
 39			return std::to_string(j[key].get<long long>());
 40		}
 41		if(j[key].is_number_unsigned()) {
 42			return std::to_string(j[key].get<unsigned long long>());
 43		}
 44		if(j[key].is_number_float()) {
 45			return std::to_string(j[key].get<double>());
 46		}
 47		return {};
 48	}
