394	bool alert_evaluator::matches_target(const rule &r, const json &entry, bool is_interface) {
395		if(r.target == "interface") {
396			return is_interface;
397		}
398		if(is_interface) {
399			return r.target == "any";
400		}
401		if(r.target == "flow" && !entry.contains("flow_key")) {
402			return false;
403		}
404		if(r.target == "stream" && entry.contains("flow_key")) {
405			return false;
406		}
407		if(!r.proto.empty()) {
408			const auto proto = json_string_or_empty(entry, "proto");
409			if(proto != r.proto) {
410				return false;
411			}
412		}
413		if(!r.flow_roles.empty()) {
414			const auto role = json_string_or_empty(entry, "role");
415			if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role) == r.flow_roles.end()) {
416				return false;
417			}
418		}
419		return true;
420	}
