213		json::array_t out;
214		for(const auto &[state_key, s] : m_states) {
215			if(!s.active) {
216				continue;
217			}
218			json entry = s.source.is_object() ? s.source : json::object();
219			if(s.detail.is_object()) {
220				for(const auto &[key, value] : s.detail.items()) {
221					if(!entry.contains(key)) {
222						entry[key] = value;
223					}
224				}
225			}
226			entry["state_key"] = state_key;
227			entry["state"] = "active";
228			entry["last_value"] = s.last_value;
229			entry["last_error_time"] = s.last_error_time;
230			entry["last_seen_time"] = s.last_seen_time;
231			out.push_back(std::move(entry));
232		}
233		return out;
