318	void alert_evaluator::emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail) {
319		detail["alert_id"] = r.id;
320		detail["state_key"] = make_state_key(r, entry, is_interface);
321		detail["severity"] = r.severity;
322		detail["indicator_category"] = r.indicator_category;
323		detail["action"] = action;
324		detail["value"] = value;
325		detail["comparison_operator"] = compare_operator(r.op);
326		detail["error_threshold"] = r.error_threshold;
327		detail["recover_threshold"] = r.recover_threshold;
328		detail["trigger_after_sec"] = r.trigger_after_sec;
329		detail["recover_after_sec"] = r.recover_after_sec;
330		detail["missing_after_sec"] = r.missing_after_sec;
331		m_events.emit(event_record{.time_epoch = now, .type = action == "detected" ? "alert_detected" : "alert_recovered", .source = make_target_source(r, entry, is_interface), .detail = std::move(detail)});
332	}
