356	std::optional<double> alert_evaluator::metric_value(const json &entry, const std::string &path) {
357		const json *cur = &entry;
358		for(const auto &part : split_path(path)) {
359			if(!cur->is_object() || !cur->contains(part)) {
360				return std::nullopt;
361			}
362			cur = &(*cur)[part];
363		}
364		if(cur->is_number()) {
365			return cur->get<double>();
366		}
367		return std::nullopt;
368	}
