370	bool alert_evaluator::compare(double lhs, compare_op op, double rhs) {
371		switch(op) {
372		case compare_op::gt: return lhs > rhs;
373		case compare_op::ge: return lhs >= rhs;
374		case compare_op::lt: return lhs < rhs;
375		case compare_op::le: return lhs <= rhs;
376		case compare_op::eq: return lhs == rhs;
377		case compare_op::ne: return lhs != rhs;
378		}
379		return false;
380	}
381	
382	std::string alert_evaluator::compare_operator(compare_op op) {
383		switch(op) {
384		case compare_op::gt: return ">";
385		case compare_op::ge: return ">=";
386		case compare_op::lt: return "<";
387		case compare_op::le: return "<=";
388		case compare_op::eq: return "==";
389		case compare_op::ne: return "!=";
390		}
391		return "?";
392	}
