422	std::string alert_evaluator::make_state_key(const rule &r, const json &entry, bool is_interface) {
423		std::ostringstream ss;
424		ss << r.id;
425		if(is_interface) {
426			ss << "|interface=" << json_string_or_empty(entry, "interface_id")
427			   << "|name=" << json_string_or_empty(entry, "name");
428			return ss.str();
429		}
430		ss << "|proto=" << json_string_or_empty(entry, "proto")
431		   << "|stream=" << json_string_or_empty(entry, "stream_key");
432		const auto flow_key = json_string_or_empty(entry, "flow_key");
433		if(!flow_key.empty()) {
434			ss << "|flow=" << flow_key;
435		}
436		return ss.str();
437	}
