461	alert_evaluator::compare_op alert_evaluator::parse_compare_op(const std::string &value) {
462		if(value == ">") return compare_op::gt;
463		if(value == ">=") return compare_op::ge;
464		if(value == "<") return compare_op::lt;
465		if(value == "<=") return compare_op::le;
466		if(value == "==") return compare_op::eq;
467		if(value == "!=") return compare_op::ne;
468		throw std::runtime_error("unknown alert operator: " + value);
469	}

