 67	std::filesystem::path checkpoint_path(const std::filesystem::path &root, double time) {
 68		const auto seconds = static_cast<std::time_t>(std::floor(time));
 69		std::tm tm{};
 70		gmtime_r(&seconds, &tm);
 71		char day[16];
 72		char file[16];
 73		std::snprintf(day, sizeof(day), "%04d%02d%02d", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday);
 74		std::snprintf(file, sizeof(file), "%02d%02d.json", tm.tm_hour, tm.tm_min);
 75		return root / "checkpoint" / day / file;
 76	}
