 63	int alert_evaluator::load(const std::filesystem::path &path) {
 64		m_rules.clear();
 65		m_states.clear();
 66	
 67		if(path.empty()) {
 68			return 0;
 69		}
 70	
 71		std::ifstream in(path);
 72		if(!in) {
 73			std::cerr << "alert_evaluator: failed to open " << path << std::endl;
 74			return -1;
 75		}
 76	
 77		json root;
 78		try {
 79			in >> root;
 80		}
 81		catch(const std::exception &e) {
 82			std::cerr << "alert_evaluator: failed to parse " << path << ": " << e.what() << std::endl;
 83			return -1;
 84		}
 85	
 86		const json *rules_json = nullptr;
 87		const bool profile_format = root.is_object() && root.contains("rules");
 88		if(profile_format) {
 89			if(!root["rules"].is_array() || !root.contains("profiles") || !root["profiles"].is_array() || !root.contains("assignments") || !root["assignments"].is_array()) {
 90				std::cerr << "alert_evaluator: rules format requires rules, profiles, and assignments arrays" << std::endl; return -1;
 91			}
 92			rules_json = &root["rules"];
 93		}
 94		else if(root.is_object() && root.contains("alerts") && root["alerts"].is_array()) {
 95			rules_json = &root["alerts"];
 96		}
 97		else if(root.is_array()) {
 98			rules_json = &root;
 99		}
100		else {
101			std::cerr << "alert_evaluator: root.alerts must be an array" << std::endl;
102			return -1;
103		}
104	
105		for(const auto &entry : *rules_json) {
106			try {
107			if(!entry.is_object()) {
108				std::cerr << "alert_evaluator: alert entry must be an object" << std::endl;
109				return -1;
110			}
111			if(!entry.contains("id") || !entry["id"].is_string()) {
112				std::cerr << "alert_evaluator: alert entry requires string id" << std::endl;
113				return -1;
114			}
115			if(!entry.contains("metric") || !entry["metric"].is_string()) {
116				std::cerr << "alert_evaluator: alert " << entry["id"] << " requires string metric" << std::endl;
117				return -1;
118			}
119	
120			rule r;
121			r.id = entry["id"].get<std::string>();
122			r.metric = entry["metric"].get<std::string>();
123			if(entry.contains("target") && entry["target"].is_string()) r.target = entry["target"].get<std::string>();
124			if(entry.contains("proto") && entry["proto"].is_string()) r.proto = entry["proto"].get<std::string>();
125			if(entry.contains("flow_roles")) {
126				if(!entry["flow_roles"].is_array() || r.target != "flow") throw std::runtime_error("flow_roles requires flow target");
127				for(const auto &role : entry["flow_roles"]) {
128					if(!role.is_string() || role.get<std::string>().empty()) throw std::runtime_error("flow_roles must contain non-empty strings");
129					if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role.get<std::string>()) != r.flow_roles.end()) throw std::runtime_error("flow_roles must not contain duplicates");
130					r.flow_roles.push_back(role.get<std::string>());
131				}
132			}
133			if(entry.contains("indicator_category")) {
134				if(!entry["indicator_category"].is_string() || (entry["indicator_category"] != "quality" && entry["indicator_category"] != "other")) throw std::runtime_error("indicator_category must be quality or other");
135				r.indicator_category = entry["indicator_category"].get<std::string>();
136			}
137			if(entry.contains("type") && entry["type"].is_string()) r.type = parse_rule_type(entry["type"].get<std::string>());
138			if(entry.contains("operator") && entry["operator"].is_string()) r.op = parse_compare_op(entry["operator"].get<std::string>());
139			if(entry.contains("error_threshold")) r.error_threshold = entry["error_threshold"].get<double>();
140			if(entry.contains("recover_threshold")) r.recover_threshold = entry["recover_threshold"].get<double>();
141			else r.recover_threshold = r.error_threshold;
142			if(entry.contains("delta_threshold")) r.delta_threshold = entry["delta_threshold"].get<double>();
143			if(entry.contains("trigger_after_sec")) r.trigger_after_sec = entry["trigger_after_sec"].get<double>();
144			if(entry.contains("recover_after_sec")) r.recover_after_sec = entry["recover_after_sec"].get<double>();
145			else r.recover_after_sec = r.type == rule_type::counter_delta ? 3.0 : 0.0;
146			if(entry.contains("missing_after_sec")) r.missing_after_sec = entry["missing_after_sec"].get<double>();
147			if(r.trigger_after_sec < 0.0 || r.recover_after_sec < 0.0 || r.missing_after_sec < 0.0) throw std::runtime_error("alert durations must be non-negative");
148			if(entry.contains("severity") && entry["severity"].is_string()) r.severity = entry["severity"].get<std::string>();
149			r.enabled = read_bool(entry, "enabled", true);
150	
151			m_rules.push_back(std::move(r));
152			}
153			catch(const std::exception &e) {
154				std::cerr << "alert_evaluator: invalid alert entry: " << e.what() << std::endl;
155				return -1;
156			}
157		}
158	
159		if(profile_format) {
160			const auto library = m_rules;
161			std::map<std::string, rule> rules_by_id;
162			for(const auto &r : library) { if(!rules_by_id.emplace(r.id, r).second) { std::cerr << "alert_evaluator: duplicate rule id " << r.id << std::endl; return -1; } }
163			std::map<std::string, std::vector<std::string>> profiles;
164			for(const auto &profile : root["profiles"]) {
165				if(!profile.is_object() || !profile.contains("id") || !profile["id"].is_string() || !profile.contains("rule_ids") || !profile["rule_ids"].is_array()) { std::cerr << "alert_evaluator: invalid profile" << std::endl; return -1; }
166				const auto id = profile["id"].get<std::string>();
167				if(id.empty() || profiles.contains(id)) { std::cerr << "alert_evaluator: duplicate or empty profile id" << std::endl; return -1; }
168				auto &ids = profiles[id];
169				for(const auto &rule_id : profile["rule_ids"]) { if(!rule_id.is_string() || !rules_by_id.contains(rule_id.get<std::string>())) { std::cerr << "alert_evaluator: unknown profile rule id" << std::endl; return -1; } ids.push_back(rule_id.get<std::string>()); }
170			}
171			m_rules.clear();
172			std::set<std::string> assigned;
173			for(const auto &assignment : root["assignments"]) {
174				if(!assignment.is_object() || !assignment.contains("scope") || !assignment["scope"].is_object() || !assignment.contains("profile_ids") || !assignment["profile_ids"].is_array()) { std::cerr << "alert_evaluator: invalid assignment" << std::endl; return -1; }
175				const auto &scope = assignment["scope"];
176				if(!scope.contains("kind") || !scope["kind"].is_string()) { std::cerr << "alert_evaluator: assignment scope requires kind" << std::endl; return -1; }
177				const auto kind = scope["kind"].get<std::string>();
178				std::string target_id; int priority = 0; std::string scoped_proto; std::string scoped_target;
179				if(kind == "protocol") { if(scope.contains("proto")) { if(!scope["proto"].is_string()) { std::cerr << "alert_evaluator: protocol scope proto must be string" << std::endl; return -1; } scoped_proto = scope["proto"].get<std::string>(); } if(scope.contains("target")) { if(!scope["target"].is_string()) { std::cerr << "alert_evaluator: protocol scope target must be string" << std::endl; return -1; } scoped_target = scope["target"].get<std::string>(); } }
180				else if(kind == "managed_target") { if(!scope.contains("target_id") || !scope["target_id"].is_string() || scope["target_id"].get<std::string>().empty()) { std::cerr << "alert_evaluator: managed_target scope requires target_id" << std::endl; return -1; } target_id = scope["target_id"].get<std::string>(); priority = scope.contains("target_type") && scope["target_type"] == "group" ? 1 : 2; }
181				else { std::cerr << "alert_evaluator: unknown assignment scope kind" << std::endl; return -1; }
182				for(const auto &profile_id : assignment["profile_ids"]) {
183					if(!profile_id.is_string() || !profiles.contains(profile_id.get<std::string>())) { std::cerr << "alert_evaluator: unknown assignment profile" << std::endl; return -1; }
184					for(const auto &rule_id : profiles[profile_id.get<std::string>()]) {
185						rule r = rules_by_id.at(rule_id); r.monitoring_target_id = target_id; r.scope_priority = priority; if(!scoped_proto.empty()) r.proto = scoped_proto; if(!scoped_target.empty()) r.target = scoped_target; if(!r.flow_roles.empty() && r.target != "flow") { std::cerr << "alert_evaluator: flow_roles requires flow target after assignment" << std::endl; return -1; }
186						if(assignment.contains("overrides") && assignment["overrides"].is_object() && assignment["overrides"].contains(rule_id)) { const auto &o = assignment["overrides"][rule_id]; if(!o.is_object()) { std::cerr << "alert_evaluator: rule override must be object" << std::endl; return -1; } if(o.contains("enabled")) r.enabled = o["enabled"].get<bool>(); if(o.contains("severity")) r.severity = o["severity"].get<std::string>(); if(o.contains("error_threshold")) r.error_threshold = o["error_threshold"].get<double>(); if(o.contains("recover_threshold")) r.recover_threshold = o["recover_threshold"].get<double>(); if(o.contains("delta_threshold")) r.delta_threshold = o["delta_threshold"].get<double>(); if(o.contains("trigger_after_sec")) r.trigger_after_sec = o["trigger_after_sec"].get<double>(); if(o.contains("recover_after_sec")) r.recover_after_sec = o["recover_after_sec"].get<double>(); if(o.contains("missing_after_sec")) r.missing_after_sec = o["missing_after_sec"].get<double>(); }
187						const auto key = r.id + "|" + target_id + "|" + std::to_string(priority); if(!assigned.insert(key).second) { std::cerr << "alert_evaluator: conflicting assignment for " << r.id << std::endl; return -1; } m_rules.push_back(std::move(r));
188					}
189				}
190			}
191	
192		return 0;
193	}
