236	void alert_evaluator::evaluate_entry(double now, const rule &r, const json &entry, bool is_interface) {
237		if(!matches_target(r, entry, is_interface)) return;
238	
239		const auto state_key = make_state_key(r, entry, is_interface);
240		auto &s = m_states[state_key];
241		auto value = metric_value(entry, r.metric);
242		const bool available = value.has_value() && std::isfinite(*value);
243		update_metric_availability(now, r, entry, is_interface, state_key, s, available);
244		if(!available) return;
245	
246		s.last_seen_time = now;
247		s.metric_available = true;
248		s.metric_missing = false;
249		switch(r.type) {
250		case rule_type::threshold:
251			evaluate_threshold(now, r, entry, is_interface, state_key, s, *value);
252			break;
253		case rule_type::counter_delta:
254			evaluate_counter_delta(now, r, entry, is_interface, state_key, s, *value);
255			break;
256		}
257	}
