259	void alert_evaluator::update_metric_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, bool available) {
260		if(available) {
261			if(s.metric_missing) emit_data_availability(now, r, entry, is_interface, state_key, true);
262			s.metric_available = true;
263			s.metric_missing = false;
264			return;
265		}
266		if(!s.metric_available || r.missing_after_sec <= 0.0 || s.metric_missing || now - s.last_seen_time < r.missing_after_sec) return;
267		s.metric_missing = true;
268		emit_data_availability(now, r, entry, is_interface, state_key, false);
269	}
