271	void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
272		if(!s.active) {
273			if(!compare(value, r.op, r.error_threshold)) {
274				s.error_pending_since = 0.0;
275				return;
276			}
277			if(s.error_pending_since <= 0.0) s.error_pending_since = now;
278			if(now - s.error_pending_since < r.trigger_after_sec) return;
279			s.active = true;
280			s.error_pending_since = 0.0;
281			s.recovery_pending_since = 0.0;
282			s.last_error_time = now;
283			json detail{{"metric", r.metric}, {"value", value}, {"threshold", r.error_threshold}, {"operator", "error"}};
284			update_active_state(now, r, entry, is_interface, s, value, detail);
285			emit_alert(now, r, entry, is_interface, "detected", value, std::move(detail));
286			return;
287		}
288	
289		if(compare(value, r.op, r.recover_threshold)) {
290			s.recovery_pending_since = 0.0;
291			update_active_state(now, r, entry, is_interface, s, value, json{{"metric", r.metric}, {"value", value}, {"threshold", r.error_threshold}, {"operator", "error"}});
292			return;
293		}
294		if(s.recovery_pending_since <= 0.0) s.recovery_pending_since = now;
295		if(now - s.recovery_pending_since < r.recover_after_sec) return;
296		s.active = false;
297		s.recovery_pending_since = 0.0;
298		emit_alert(now, r, entry, is_interface, "recovered", value, json{{"metric", r.metric}, {"value", value}, {"threshold", r.recover_threshold}, {"operator", "recover"}});
299	}
