301	void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
302		if(!s.has_last_value) { s.has_last_value = true; s.last_value = value; return; }
303		const double delta = value - s.last_value;
304		s.last_value = value;
305		if(compare(delta, r.op, r.delta_threshold)) {
306			json detail{{"metric", r.metric}, {"value", value}, {"delta", delta}, {"threshold", r.delta_threshold}};
307			if(!s.active) { s.active = true; emit_alert(now, r, entry, is_interface, "detected", value, detail); }
308			s.last_error_time = now;
309			update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
310			return;
311		}
312		if(s.active && now - s.last_error_time >= r.recover_after_sec) {
313			s.active = false;
314			emit_alert(now, r, entry, is_interface, "recovered", value, json{{"metric", r.metric}, {"value", value}, {"delta", delta}, {"recover_after_sec", r.recover_after_sec}});
315		}
316	}
