370	bool alert_evaluator::compare(double lhs, compare_op op, double rhs) {
371		switch(op) {
372		case compare_op::gt: return lhs > rhs;
373		case compare_op::ge: return lhs >= rhs;
374		case compare_op::lt: return lhs < rhs;
375		case compare_op::le: return lhs <= rhs;
376		case compare_op::eq: return lhs == rhs;
377		case compare_op::ne: return lhs != rhs;
378		}
379		return false;
380	}
