 94	bool stream_state_projector::apply_event(const json &event) {
 95		if(!event.is_object()) return false;
 96		const std::string type = event.value("type", std::string{});
 97		const json source = event.value("source", json::object());
 98		const json detail = event.value("detail", json::object());
 99		const double time = event.value("event_time", event.value("time", 0.0));
100		if(!source.is_object() || time <= 0.0) return false;
101		const std::string stream_key = source.value("stream_key", std::string{});
102		if(stream_key.empty()) return false;
103	
104		const bool stream_event = lifecycle_type(type, "stream");
105		const bool flow_event = lifecycle_type(type, "flow");
106		const bool flow_state_update = flow_state_update_type(type);
107		const bool alert_state_update = alert_state_update_type(type);
108		if(!stream_event && !flow_event && !flow_state_update && !alert_state_update) return false;
109	
110		auto &stream = m_streams[stream_key];
111		if(!stream.is_object()) {
112			stream = json{{"stream_key", stream_key}, {"flows", json::object()}, {"first_seen", time}};
113		}
114		if(alert_state_update) {
115			const std::string flow_key = source.value("flow_key", std::string{});
116			if(flow_key.empty()) {
117				update_alert_state(stream, source, detail, type, time);
