 14	std::vector<std::string> split_path(const std::string &path) {
 15		std::vector<std::string> out;
 16		std::size_t start = 0;
 17		while(start <= path.size()) {
 18			const auto pos = path.find('.', start);
 19			const auto end = (pos == std::string::npos) ? path.size() : pos;
 20			if(end > start) {
 21				out.emplace_back(path.substr(start, end - start));
 22			}
 23			if(pos == std::string::npos) {
 24				break;
 25			}
 26			start = pos + 1;
 27		}
 28		return out;
 29	}
