195	void alert_evaluator::evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces) {
196		auto evaluate_entries = [this, now](const json::array_t &entries, bool is_interface) {
197			for(const auto &entry : entries) {
198				if(!entry.is_object()) continue;
199				std::map<std::string, const rule *> resolved;
200				for(const auto &r : m_rules) {
201					if(!r.enabled || !matches_target(r, entry, is_interface)) continue;
202					auto it = resolved.find(r.id);
203					if(it == resolved.end() || it->second->scope_priority < r.scope_priority) resolved[r.id] = &r;
204				}
205				for(const auto &[id, r] : resolved) evaluate_entry(now, *r, entry, is_interface);
206			}
207		};
208		evaluate_entries(metrics, false);
209		evaluate_entries(interfaces, true);
210	}
