212	json::array_t alert_evaluator::active_alerts() const {
213		json::array_t out;
214		for(const auto &[state_key, s] : m_states) {
215			if(!s.active) {
216				continue;
217			}
218			json entry = s.source.is_object() ? s.source : json::object();
219			if(s.detail.is_object()) {
220				for(const auto &[key, value] : s.detail.items()) {
221					if(!entry.contains(key)) {
222						entry[key] = value;
223					}
224				}
225			}
226			entry["state_key"] = state_key;
227			entry["state"] = "active";
228			entry["last_value"] = s.last_value;
229			entry["last_error_time"] = s.last_error_time;
230			entry["last_seen_time"] = s.last_seen_time;
231			out.push_back(std::move(entry));
232		}
233		return out;
234	}
235	
236	void alert_evaluator::evaluate_entry(double now, const rule &r, const json &entry, bool is_interface) {
237		if(!matches_target(r, entry, is_interface)) return;
238	
239		const auto state_key = make_state_key(r, entry, is_interface);
240		auto &s = m_states[state_key];
241		auto value = metric_value(entry, r.metric);
242		const bool available = value.has_value() && std::isfinite(*value);
243		update_metric_availability(now, r, entry, is_interface, state_key, s, available);
244		if(!available) return;
245	
246		s.last_seen_time = now;
247		s.metric_available = true;
248		s.metric_missing = false;
249		switch(r.type) {
250		case rule_type::threshold:
251			evaluate_threshold(now, r, entry, is_interface, state_key, s, *value);
252			break;
253		case rule_type::counter_delta:
254			evaluate_counter_delta(now, r, entry, is_interface, state_key, s, *value);
255			break;
256		}
257	}
258	
259	void alert_evaluator::update_metric_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, bool available) {
260		if(available) {
261			if(s.metric_missing) emit_data_availability(now, r, entry, is_interface, state_key, true);
262			s.metric_available = true;
263			s.metric_missing = false;
264			return;
265		}
266		if(!s.metric_available || r.missing_after_sec <= 0.0 || s.metric_missing || now - s.last_seen_time < r.missing_after_sec) return;
267		s.metric_missing = true;
268		emit_data_availability(now, r, entry, is_interface, state_key, false);
269	}
270	
271	void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
272		if(!s.active) {
273			if(!compare(value, r.op, r.error_threshold)) {
274				s.error_pending_since = 0.0;
275				return;
276			}
277			if(s.error_pending_since <= 0.0) s.error_pending_since = now;
278			if(now - s.error_pending_since < r.trigger_after_sec) return;
279			s.active = true;
280			s.error_pending_since = 0.0;
281			s.recovery_pending_since = 0.0;
282			s.last_error_time = now;
283			json detail{{"metric", r.metric}, {"value", value}, {"threshold", r.error_threshold}, {"operator", "error"}};
284			update_active_state(now, r, entry, is_interface, s, value, detail);
285			emit_alert(now, r, entry, is_interface, "detected", value, std::move(detail));
286			return;
287		}
288	
289		if(compare(value, r.op, r.recover_threshold)) {
290			s.recovery_pending_since = 0.0;
291			update_active_state(now, r, entry, is_interface, s, value, json{{"metric", r.metric}, {"value", value}, {"threshold", r.error_threshold}, {"operator", "error"}});
292			return;
293		}
294		if(s.recovery_pending_since <= 0.0) s.recovery_pending_since = now;
295		if(now - s.recovery_pending_since < r.recover_after_sec) return;
296		s.active = false;
297		s.recovery_pending_since = 0.0;
298		emit_alert(now, r, entry, is_interface, "recovered", value, json{{"metric", r.metric}, {"value", value}, {"threshold", r.recover_threshold}, {"operator", "recover"}});
299	}
300	
301	void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
302		if(!s.has_last_value) { s.has_last_value = true; s.last_value = value; return; }
303		const double delta = value - s.last_value;
304		s.last_value = value;
305		if(compare(delta, r.op, r.delta_threshold)) {
306			json detail{{"metric", r.metric}, {"value", value}, {"delta", delta}, {"threshold", r.delta_threshold}};
307			if(!s.active) { s.active = true; emit_alert(now, r, entry, is_interface, "detected", value, detail); }
308			s.last_error_time = now;
309			update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
310			return;
311		}
312		if(s.active && now - s.last_error_time >= r.recover_after_sec) {
313			s.active = false;
314			emit_alert(now, r, entry, is_interface, "recovered", value, json{{"metric", r.metric}, {"value", value}, {"delta", delta}, {"recover_after_sec", r.recover_after_sec}});
315		}
316	}
317	
318	void alert_evaluator::emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail) {
319		detail["alert_id"] = r.id;
320		detail["state_key"] = make_state_key(r, entry, is_interface);
321		detail["severity"] = r.severity;
322		detail["indicator_category"] = r.indicator_category;
323		detail["action"] = action;
324		detail["value"] = value;
325		detail["comparison_operator"] = compare_operator(r.op);
326		detail["error_threshold"] = r.error_threshold;
327		detail["recover_threshold"] = r.recover_threshold;
328		detail["trigger_after_sec"] = r.trigger_after_sec;
329		detail["recover_after_sec"] = r.recover_after_sec;
330		detail["missing_after_sec"] = r.missing_after_sec;
331		m_events.emit(event_record{.time_epoch = now, .type = action == "detected" ? "alert_detected" : "alert_recovered", .source = make_target_source(r, entry, is_interface), .detail = std::move(detail)});
332	}
333	
334	void alert_evaluator::emit_data_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, bool available) {
335		json detail{{"alert_id", r.id}, {"state_key", state_key + "|data"}, {"severity", r.severity}, {"indicator_category", r.indicator_category}, {"metric", r.metric}, {"missing_after_sec", r.missing_after_sec}, {"action", available ? "available" : "unavailable"}};
336		m_events.emit(event_record{.time_epoch = now, .type = available ? "alert_data_available" : "alert_data_unavailable", .source = make_target_source(r, entry, is_interface), .detail = std::move(detail)});
337	}
338	
339	void alert_evaluator::update_active_state(double now, const rule &r, const json &entry, bool is_interface, state &s, double value, json detail) {
340		detail["alert_id"] = r.id;
341		detail["severity"] = r.severity;
342		detail["indicator_category"] = r.indicator_category;
343		detail["comparison_operator"] = compare_operator(r.op);
344		detail["error_threshold"] = r.error_threshold;
345		detail["recover_threshold"] = r.recover_threshold;
346		detail["trigger_after_sec"] = r.trigger_after_sec;
347		detail["recover_after_sec"] = r.recover_after_sec;
348		detail["missing_after_sec"] = r.missing_after_sec;
349		detail["value"] = value;
350		s.source = make_target_source(r, entry, is_interface);
351		s.detail = std::move(detail);
352		s.last_value = value;
353		s.last_seen_time = now;
354	}
