356	std::optional<double> alert_evaluator::metric_value(const json &entry, const std::string &path) {
357		const json *cur = &entry;
358		for(const auto &part : split_path(path)) {
359			if(!cur->is_object() || !cur->contains(part)) {
360				return std::nullopt;
361			}
362			cur = &(*cur)[part];
363		}
364		if(cur->is_number()) {
365			return cur->get<double>();
366		}
367		return std::nullopt;
368	}
369	
370	bool alert_evaluator::compare(double lhs, compare_op op, double rhs) {
371		switch(op) {
372		case compare_op::gt: return lhs > rhs;
373		case compare_op::ge: return lhs >= rhs;
374		case compare_op::lt: return lhs < rhs;
375		case compare_op::le: return lhs <= rhs;
376		case compare_op::eq: return lhs == rhs;
377		case compare_op::ne: return lhs != rhs;
378		}
379		return false;
380	}
381	
382	std::string alert_evaluator::compare_operator(compare_op op) {
383		switch(op) {
384		case compare_op::gt: return ">";
385		case compare_op::ge: return ">=";
386		case compare_op::lt: return "<";
387		case compare_op::le: return "<=";
388		case compare_op::eq: return "==";
389		case compare_op::ne: return "!=";
390		}
391		return "?";
392	}
393	
394	bool alert_evaluator::matches_target(const rule &r, const json &entry, bool is_interface) {
395		if(r.target == "interface") {
396			return is_interface;
397		}
398		if(is_interface) {
399			return r.target == "any";
400		}
401		if(r.target == "flow" && !entry.contains("flow_key")) {
402			return false;
403		}
404		if(r.target == "stream" && entry.contains("flow_key")) {
405			return false;
406		}
407		if(!r.proto.empty()) {
408			const auto proto = json_string_or_empty(entry, "proto");
409			if(proto != r.proto) {
410				return false;
411			}
412		}
413		if(!r.flow_roles.empty()) {
414			const auto role = json_string_or_empty(entry, "role");
415			if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role) == r.flow_roles.end()) {
416				return false;
417			}
418		}
419		return true;
420	}
