439	json alert_evaluator::make_target_source(const rule &r, const json &entry, bool is_interface) {
440		json source{
441			{"alert_id", r.id},
442			{"severity", r.severity},
443			{"indicator_category", r.indicator_category},
444			{"target", is_interface ? "interface" : (entry.contains("flow_key") ? "flow" : "stream")},
445		};
446		for(const auto &key : {"proto", "stream_key", "flow_key", "interface_id", "name"}) {
447			if(entry.contains(key)) {
448				source[key] = entry[key];
449			}
450		}
451		if(!r.monitoring_target_id.empty()) source["monitoring_target_id"] = r.monitoring_target_id;
452		return source;
453	}
