455	alert_evaluator::rule_type alert_evaluator::parse_rule_type(const std::string &value) {
456		if(value == "threshold") return rule_type::threshold;
457		if(value == "counter_delta") return rule_type::counter_delta;
458		throw std::runtime_error("unknown alert rule type: " + value);
459	}
