function RuleCondition({ rule, metric }: { rule: AlertRule; metric?: AlertMetricDefinition }) { const unit = metric?.unit; if (rule.type === "counter_delta") return <>{rule.metric} {(rule.operator ?? ">")}Δ <ValueHint value={rule.delta_threshold} unit={unit} /> / <ValueHint value={rule.recover_after_sec ?? 3} unit="s" /></>; return <>{rule.metric} {rule.operator ?? ">"} <ValueHint value={rule.error_threshold} unit={unit} /> (recover <ValueHint value={rule.recover_threshold} unit={unit} />)</>; }
function ruleConditionText(rule: AlertRule, metric?: AlertMetricDefinition) { const unit = metric?.unit; if (rule.type === "counter_delta") return rule.metric + " " + (rule.operator ?? ">") + " Δ" + formatMetricValue(rule.delta_threshold, unit) + " / " + formatMetricValue(rule.recover_after_sec ?? 3, "s"); return rule.metric + " " + (rule.operator ?? ">") + " " + formatMetricValue(rule.error_threshold, unit) + " (recover " + formatMetricValue(rule.recover_threshold, unit) + ")"; }

type AlertRowProps = { index: number; row: AlertRule; metrics: AlertMetricDefinition[]; flowRoles: Record<string, string[]>; busy: boolean; onUpdate: (index: number, patch: Partial<AlertRule>) => void; onRemove: (index: number) => void };
function AlertRow({ index, row, metrics, flowRoles, busy, onUpdate, onRemove }: AlertRowProps) {
  const availableRoles = (row.target ?? "any") === "flow" && row.proto ? flowRoles[row.proto] ?? [] : [];
  const target = row.target ?? "any";
  const type = row.type ?? "threshold";
  const candidates = metrics.filter((metric) => supportsMetric(metric, target, row.proto));
  const selected = metrics.find((metric) => metric.key === row.metric);
  const unit = selected?.unit;
  const listId = "alert-metrics-" + index;
  const changeType = (nextType: AlertRule["type"]) => {
    if (nextType === "counter_delta") onUpdate(index, { type: nextType, delta_threshold: row.delta_threshold ?? 0, recover_after_sec: row.recover_after_sec ?? 3, error_threshold: undefined, recover_threshold: undefined });
    else onUpdate(index, { type: "threshold", operator: row.operator ?? ">", error_threshold: row.error_threshold ?? 0, recover_threshold: row.recover_threshold ?? 0, delta_threshold: undefined, recover_after_sec: undefined });
  };
  return <tr><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={"maintenance-switch " + (row.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={row.id} disabled={busy} onChange={(event) => onUpdate(index, { id: event.target.value })} /></td><td><select value={target} disabled={busy || row.proto === "RTP" || row.proto === "RTMP" || row.proto === "SRT"} onChange={(event) => onUpdate(index, { target: event.target.value as AlertRule["target"], metric: "" })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td>{availableRoles.length > 0 ? <RolePicker roles={availableRoles} value={row.flow_roles ?? []} disabled={busy} onChange={(flow_roles) => onUpdate(index, { flow_roles })} /> : "—"}</td><td><select value={row.indicator_category ?? "other"} disabled={busy} aria-label="Indicator category" onChange={(event) => onUpdate(index, { indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">Other</option><option value="quality">Quality</option></select></td><td><input className="alerts-metric-input" list={listId} value={row.metric} disabled={busy} onChange={(event) => onUpdate(index, { metric: event.target.value })} placeholder="Search metric" title={selected?.description ? metricTooltip(selected) : undefined} aria-label={selected?.description ? "Metric: " + metricTooltip(selected) : "Metric"} /><datalist id={listId}>{candidates.map((metric) => <option key={metric.key} value={metric.key} label={metric.description ?? metric.key} />)}</datalist>{selected?.preview && <span className="alerts-preview">Preview</span>}</td><td><span className="alerts-rule-controls"><select value={type} disabled={busy} onChange={(event) => changeType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option></select>{type === "threshold" && <select className="alerts-operator" value={row.operator ?? ">"} disabled={busy} onChange={(event) => onUpdate(index, { operator: event.target.value as AlertRule["operator"]})}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</span></td><td><AlertNumberInput value={type === "counter_delta" ? row.delta_threshold : row.error_threshold} unit={unit} busy={busy} ariaLabel="Trigger value" onValue={(value) => onUpdate(index, type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} /></td><td>{type === "counter_delta" ? <AlertNumberInput value={row.recover_after_sec} unit="s" min={0} busy={busy} ariaLabel="Recovery duration" onValue={(value) => onUpdate(index, { recover_after_sec: value })} /> : <AlertNumberInput value={row.recover_threshold} unit={unit} busy={busy} ariaLabel="Recovery value" onValue={(value) => onUpdate(index, { recover_threshold: value })} />}</td><td><select value={row.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate(index, { severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={() => onRemove(index)} aria-label="Delete alert rule" title="Delete alert rule"><Icon name="delete" size={16} /></button></td></tr>;
}

type RolePickerProps = { roles: string[]; value: string[]; disabled: boolean; onChange: (value: string[] | undefined) => void };
function RolePicker({ roles, value, disabled, onChange }: RolePickerProps) {
  const selected = value.length ? new Set(value) : new Set(roles);
  const selectedRoles = roles.filter((role) => selected.has(role));
  const label = selectedRoles.length === roles.length ? "All roles" : selectedRoles.length === 1 ? selectedRoles[0] : selectedRoles[0] + " +" + (selectedRoles.length - 1);
  const toggle = (role: string, checked: boolean) => {
    const next = roles.filter((item) => item === role ? checked : selected.has(item));
    onChange(next.length === roles.length ? undefined : next);
  };
  return <details className={"alerts-role-picker" + (disabled ? " is-disabled" : "")}><summary aria-label="Flow roles" title={selectedRoles.join(", ")} onClick={(event) => { if (disabled) event.preventDefault(); }}>{label}</summary><div className="alerts-role-picker-menu">{roles.map((role) => <label key={role}><input type="checkbox" checked={selected.has(role)} disabled={disabled} onChange={(event) => toggle(role, event.currentTarget.checked)} />{role}</label>)}</div></details>;
}

