}

function levelForType(type: string, detail: unknown): EventLogItem["level"] {
  if (type === "alert_detected" || type === "alert_data_unavailable") {
    const severity = stringValue(recordValue(detail)?.severity)?.toLowerCase();
    if (severity === "error" || severity === "critical") return "error";
    if (severity === "warning" || severity === "warn") return "warn";
  }
  if (/error|failed|failure/i.test(type)) return "error";
  if (/warn|stale|drop|loss|timeout/i.test(type)) return "warn";
  return "info";
}

function messageForType(type: string) {
  proto?: string;
  flow_roles?: string[];
  indicator_category?: AlertIndicatorCategory;
  metric: string;
  type?: AlertRuleType;
  operator?: AlertOperator;
  error_threshold?: number;
  recover_threshold?: number;
  delta_threshold?: number;
  trigger_after_sec?: number;
  recover_after_sec?: number;
  missing_after_sec?: number;
  severity?: string;
};

export type AlertProfile = { id: string; title?: string; rule_ids: string[] };
export type AlertAssignmentScope = { kind: "protocol"; proto?: string; target?: AlertTarget } | { kind: "managed_target"; target_id: string; target_type?: "single" | "group" };
