.alerts-role-picker-menu { position: absolute; z-index: 8; top: calc(100% + 4px); left: 0; display: grid; min-width: max-content; padding: var(--space-1); border: 1px solid var(--line-strong); border-radius: var(--radius-sm); background: var(--surface-raised); box-shadow: var(--shadow-md); }
