.alerts-inline-field { display: flex; align-items: center; gap: 4px; color: var(--muted); font-size: var(--font-size-xs); }
.alerts-inline-field input { min-width: 0; }
.alerts-timing-controls { display: grid; gap: 4px; }
.alerts-timing-controls label { display: grid; grid-template-columns: 46px minmax(0, 1fr); align-items: center; gap: 4px; color: var(--muted); font-size: 10px; }
.alerts-empty { padding: var(--space-4) !important; color: var(--muted); text-align: center !important; }
@media (max-width: 760px) { .alerts-toolbar { grid-template-columns: 1fr; } .alerts-table th, .alerts-table td { padding: var(--space-1); font-size: var(--font-size-xs); } }

