bool need_value(int i, int argc, const char* name) {
    if (i + 1 >= argc) {
        std::cerr << "missing value for " << name << "\n";
        return false;
    }
    return true;
}

std::optional<options> parse_args(int argc, char** argv) {
    options opt;

    try {
        for (int i = 1; i < argc; ++i) {
            std::string a = argv[i];

            auto next = [&](const char* name) -> const char* {
                if (!need_value(i, argc, name)) {
                    return nullptr;
                }
                return argv[++i];
            };

            if (a == "--proto") {
                const char* v = next("--proto");
                if (!v) return std::nullopt;

                std::string s = v;
                if (s == "rtp") {
                    opt.proto = proto_type::rtp;
                } else if (s == "srt") {
                    opt.proto = proto_type::srt;
                } else {
                    std::cerr << "invalid proto: " << s << "\n";
                    return std::nullopt;
                }
            } else if (a == "--dst") {
                const char* v = next("--dst");
                if (!v) return std::nullopt;
                opt.dst = v;
            } else if (a == "--port") {
                const char* v = next("--port");
                if (!v) return std::nullopt;
                opt.port = parse_u16(v, "--port");
            } else if (a == "--bitrate") {
                const char* v = next("--bitrate");
                if (!v) return std::nullopt;
                opt.bitrate_bps = static_cast<std::uint32_t>(std::stoul(v));
            } else if (a == "--payload-size") {
                const char* v = next("--payload-size");
                if (!v) return std::nullopt;
                opt.payload_size = static_cast<std::size_t>(std::stoull(v));
            } else if (a == "--ssrc") {
                const char* v = next("--ssrc");
                if (!v) return std::nullopt;
                opt.ssrc = static_cast<std::uint32_t>(std::stoul(v));
            } else if (a == "--pt") {
                const char* v = next("--pt");
                if (!v) return std::nullopt;
                opt.pt = parse_u8(v, "--pt");
            } else if (a == "--clock-rate") {
                const char* v = next("--clock-rate");
                if (!v) return std::nullopt;
                opt.clock_rate = static_cast<std::uint32_t>(std::stoul(v));
            } else if (a == "--mpegts-payload") {
                const char* v = next("--mpegts-payload");
                if (!v) return std::nullopt;
                opt.mpegts_payload = std::stoul(v) != 0;
            } else if (a == "--srt-streamid") {
                const char* v = next("--srt-streamid");
                if (!v) return std::nullopt;
                opt.srt_streamid = v;
            } else if (a == "--impair") {
                const char* v = next("--impair");
                if (!v) return std::nullopt;
                std::string error;
                if (!parse_impairment(v, opt, error)) {
                    std::cerr << error << "\n";
                    return std::nullopt;
                }
            } else if (a == "--loss" || a == "--duplicate" || a == "--reorder") {
                const char* v = next(a.c_str());
                if (!v) return std::nullopt;
                counted_impairment parsed;
                parsed.mode = occurrence_mode::rate;
                parsed.rate = parse_finite_double(v, a.c_str());
                counted_impairment* target = a == "--loss" ? &opt.loss :
                    (a == "--duplicate" ? &opt.duplicate : &opt.reorder);
                std::string error;
                if (!set_counted_impairment(*target, std::move(parsed), a.c_str() + 2, error)) {
                    std::cerr << error << "\n";
                    return std::nullopt;
                }
                opt.uses_legacy_impairment_options = true;
            } else if (a == "--jitter-ms") {
                const char* v = next("--jitter-ms");
                if (!v) return std::nullopt;
                jitter_impairment parsed;
                parsed.mode = jitter_mode::random;
                parsed.max_ms = parse_finite_double(v, "--jitter-ms");
                std::string error;
                if (!set_jitter_impairment(opt.jitter, std::move(parsed), error)) {
                    std::cerr << error << "\n";
                    return std::nullopt;
                }
                opt.uses_legacy_impairment_options = true;
            } else if (a == "--jitter-target-ms") {
                const char* v = next("--jitter-target-ms");
                if (!v) return std::nullopt;
                jitter_impairment parsed;
                parsed.mode = jitter_mode::target;
                parsed.target_ms = parse_finite_double(v, "--jitter-target-ms");
                parsed.target_mode = opt.jitter.target_mode;
                std::string error;
                if (!set_jitter_impairment(opt.jitter, std::move(parsed), error)) {
                    std::cerr << error << "\n";
                    return std::nullopt;
                }
                opt.uses_legacy_impairment_options = true;
            } else if (a == "--jitter-target-mode") {
                const char* v = next("--jitter-target-mode");
                if (!v) return std::nullopt;
                const std::string mode = v;
                if (mode == "ordered") {
                    opt.jitter.target_mode = jitter_target_mode::ordered;
                } else if (mode == "reorder") {
                    opt.jitter.target_mode = jitter_target_mode::reorder;
                } else {
                    std::cerr << "--jitter-target-mode must be ordered or reorder\n";
                    return std::nullopt;
                }
                opt.uses_legacy_impairment_options = true;
            } else if (a == "--seed") {
                const char* v = next("--seed");
                if (!v) return std::nullopt;
                opt.seed = parse_u32(v, "--seed");
            } else if (a == "--fec") {
                opt.fec = true;
                opt.uses_fec_options = true;
            } else if (a == "--fec-row-port") {
                const char* v = next("--fec-row-port");
                if (!v) return std::nullopt;
                opt.fec_row_port = parse_u16(v, "--fec-row-port");
                opt.uses_fec_options = true;
            } else if (a == "--fec-col-port") {
                const char* v = next("--fec-col-port");
                if (!v) return std::nullopt;
                opt.fec_col_port = parse_u16(v, "--fec-col-port");
                opt.uses_fec_options = true;
            } else if (a == "--fec-pt") {
                const char* v = next("--fec-pt");
                if (!v) return std::nullopt;
                opt.fec_pt = parse_u8(v, "--fec-pt");
                opt.uses_fec_options = true;
            } else if (a == "--fec-row-ssrc") {
                const char* v = next("--fec-row-ssrc");
                if (!v) return std::nullopt;
                opt.fec_row_ssrc = static_cast<std::uint32_t>(std::stoul(v));
                opt.uses_fec_options = true;
            } else if (a == "--fec-col-ssrc") {
                const char* v = next("--fec-col-ssrc");
                if (!v) return std::nullopt;
                opt.fec_col_ssrc = static_cast<std::uint32_t>(std::stoul(v));
                opt.uses_fec_options = true;
            } else if (a == "--fec-l") {
                const char* v = next("--fec-l");
                if (!v) return std::nullopt;
                opt.fec_l = static_cast<std::uint32_t>(std::stoul(v));
                opt.uses_fec_options = true;
            } else if (a == "--fec-d") {
                const char* v = next("--fec-d");
                if (!v) return std::nullopt;
                opt.fec_d = static_cast<std::uint32_t>(std::stoul(v));
                opt.uses_fec_options = true;
            } else if (a == "--mcast-if") {
                const char* v = next("--mcast-if");
                if (!v) return std::nullopt;
                opt.mcast_if = v;
                opt.uses_mcast_options = true;
            } else if (a == "--mcast-ttl") {
                const char* v = next("--mcast-ttl");
                if (!v) return std::nullopt;
                opt.mcast_ttl = std::stoi(v);
                opt.uses_mcast_options = true;
            } else if (a == "--mcast-loop") {
                const char* v = next("--mcast-loop");
                if (!v) return std::nullopt;
                opt.mcast_loop = std::stoi(v);
                opt.uses_mcast_options = true;
            } else if (a == "--help" || a == "-h") {
                return std::nullopt;
            } else {
                std::cerr << "unknown option: " << a << "\n";
                return std::nullopt;
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "argument parse error: " << e.what() << "\n";
        return std::nullopt;
    }

    if (opt.payload_size == 0) {
        std::cerr << "--payload-size must be greater than 0\n";
        return std::nullopt;
    }

    if (opt.bitrate_bps == 0) {
        std::cerr << "--bitrate must be greater than 0\n";
        return std::nullopt;
    }

    if (opt.srt_streamid.size() > 512) {
        std::cerr << "--srt-streamid must be at most 512 bytes\n";
        return std::nullopt;
    }

    if (opt.proto == proto_type::srt && opt.uses_fec_options) {
        std::cerr << "--fec and --fec-* are available only with --proto rtp\n";
        return std::nullopt;
    }

    if (opt.proto == proto_type::srt && opt.uses_mcast_options) {
        std::cerr << "--mcast-* options are available only with --proto rtp\n";
        return std::nullopt;
    }

    const auto valid_rate = [](double value) {
        return std::isfinite(value) && value >= 0.0 && value <= 1.0;
    };
    const auto validate_counted = [&valid_rate](const counted_impairment& value, bool reorder, const char* type) {
        if (value.mode == occurrence_mode::rate) {
            if (!valid_rate(value.rate)) {
                std::cerr << "--impair " << type << ",mode=rate requires rate in 0..1\n";
                return false;
            }
        } else if (value.mode == occurrence_mode::periodic) {
            if (reorder && value.periodic.count > UINT64_MAX / 2) {
                std::cerr << "--impair reorder,mode=periodic count is too large\n";
                return false;
            }
            if (value.periodic.basis == period_basis::packets) {
                const bool exceeds_period = reorder
                    ? value.periodic.count > value.periodic.packet_period / 2
                    : value.periodic.count > value.periodic.packet_period;
                if (exceeds_period) {
                    std::cerr << "--impair " << type
                              << ",mode=periodic count exceeds the packet period\n";
                    return false;
                }
            }
        }
        return true;
    };

    if (!validate_counted(opt.loss, false, "loss") ||
        !validate_counted(opt.duplicate, false, "duplicate") ||
        !validate_counted(opt.reorder, true, "reorder")) {
        return std::nullopt;
    }

    if (opt.jitter.mode == jitter_mode::random &&
        (opt.jitter.max_ms < 0.0 || opt.jitter.max_ms > 60000.0)) {
        std::cerr << "jitter random max-ms must be in 0..60000\n";
        return std::nullopt;
    }

    if (opt.jitter.mode == jitter_mode::target &&
        (opt.jitter.target_ms < 0.0 || opt.jitter.target_ms > 60000.0)) {
        std::cerr << "jitter target target-ms must be in 0..60000\n";
        return std::nullopt;
    }

    if (opt.jitter.target_mode == jitter_target_mode::reorder &&
        opt.jitter.mode != jitter_mode::target) {
        std::cerr << "--jitter-target-mode reorder requires --jitter-target-ms\n";
        return std::nullopt;
    }

    const double ordered_target_limit_ms = ordered_jitter_target_limit_ms(opt);
    if (opt.jitter.mode == jitter_mode::target &&
        opt.jitter.target_ms > ordered_target_limit_ms &&
        opt.jitter.target_mode != jitter_target_mode::reorder) {
        std::cerr
            << "jitter target-ms " << opt.jitter.target_ms
            << " exceeds the ordered "
            << (opt.proto == proto_type::rtp ? "RTP" : "SRT")
            << " limit of " << ordered_target_limit_ms
            << " ms at the configured bitrate and payload size; "
               "use target-mode=reorder in --impair jitter or --jitter-target-mode reorder\n";
        return std::nullopt;
    }

    if (opt.fec_l == 0 || opt.fec_d == 0) {
        std::cerr << "--fec-l and --fec-d must be greater than 0\n";
        return std::nullopt;
    }

    if (opt.mcast_ttl < 0 || opt.mcast_ttl > 255) {
        std::cerr << "--mcast-ttl must be 0..255\n";
        return std::nullopt;
    }

    return opt;
}

struct udp_rtp_sender {
    int fd{-1};
    sockaddr_in addr{};

    std::uint32_t ssrc{0};
    std::uint8_t pt{33};
    std::uint16_t seq{0};
    std::uint32_t timestamp{0};

    std::size_t payload_size{1316};
    bool mpegts_payload{false};

    std::string mcast_if{};
    int mcast_ttl{1};
    int mcast_loop{1};

    bool open(const std::string& ip, std::uint16_t port) {
        fd = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (fd < 0) {
            perror("socket");
            return false;
        }

        std::memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);

        if (::inet_pton(AF_INET, ip.c_str(), &addr.sin_addr) != 1) {
            std::cerr << "invalid ip: " << ip << "\n";
            return false;
        }

        if (is_ipv4_multicast_addr(addr.sin_addr)) {
    reorder_selector reorder_;
    packet_submitter submit_;
    std::optional<delayed_packet> delayed_;
};

enum class jitter_target_protocol {
    rtp,
    srt,
};

double jitter_target_offset_ms(
    jitter_target_protocol protocol,
    double target_ms,
    bool high_phase)
{
    if (!high_phase) return 0.0;
    return protocol == jitter_target_protocol::rtp ? target_ms : target_ms / 2.0;
}

class packet_scheduler {
public:
    packet_scheduler(
        const options& opt,
        packet_submitter send,
        jitter_target_protocol target_protocol)
        : jitter_ms_(opt.jitter.max_ms)
        , jitter_target_ms_(opt.jitter.target_ms)
        , target_reorder_(jitter_target_reorders(opt))
        , target_protocol_(target_protocol)
        , send_(std::move(send))
        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , worker_([this] { run(); }) {}

    ~packet_scheduler() {
        stop();
    }

    packet_scheduler(const packet_scheduler&) = delete;
    packet_scheduler& operator=(const packet_scheduler&) = delete;

    void set_base_time(clock_type::time_point value) {
        base_time_ = value;
    }

    void submit(packet value) {
        auto due = base_time_.value_or(clock_type::now());
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (target_reorder_ == false && last_due_ && due < *last_due_) {
            due = *last_due_;
        }
        last_due_ = due;

        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) {
                return;
            }
            scheduled_.emplace(std::make_pair(due, next_sequence_++), std::move(value));
        }
        wake_.notify_one();
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) {
                return;
            }
            stopping_ = true;
            scheduled_.clear();
        }
        wake_.notify_one();
        if (worker_.joinable()) {
            worker_.join();
        }
    }

private:
    using schedule_key = std::pair<clock_type::time_point, std::uint64_t>;

    void run() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (stopping_ == false) {
            if (scheduled_.empty()) {
                wake_.wait(lock);
                continue;
            }

            const auto due = scheduled_.begin()->first.first;
            if (clock_type::now() < due) {
                wake_.wait_until(lock, due);
                continue;
            }

            packet value = std::move(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
            lock.unlock();
            send_(std::move(value));
            lock.lock();
        }
    }

    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            target_protocol_, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    double jitter_ms_{0.0};
    double jitter_target_ms_{0.0};
    bool target_reorder_{false};
    jitter_target_protocol target_protocol_{jitter_target_protocol::rtp};
    packet_submitter send_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    bool target_high_phase_{false};
    std::optional<clock_type::time_point> base_time_;
    std::optional<clock_type::time_point> last_due_;
    std::mutex mutex_;
    std::condition_variable wake_;
    std::map<schedule_key, packet> scheduled_;
    std::uint64_t next_sequence_{0};
    bool stopping_{false};
    std::thread worker_;
};

bool counted_impairment_enabled(const counted_impairment& value) {
    return value.mode == occurrence_mode::periodic ||
           (value.mode == occurrence_mode::rate && value.rate > 0.0);
}

bool jitter_impairment_enabled(const jitter_impairment& value) {
    return (value.mode == jitter_mode::random && value.max_ms > 0.0) ||
           (value.mode == jitter_mode::target && value.target_ms > 0.0);
}

std::string describe_counted_impairment(const counted_impairment& value, bool reorder) {
    if (value.mode == occurrence_mode::none) {
        return "off";
    }
    std::ostringstream out;
    if (value.mode == occurrence_mode::rate) {
        out << "rate=" << value.rate;
        return out.str();
    }

    if (value.periodic.basis == period_basis::packets) {
        out << "periodic=" << value.periodic.packet_period << "p";
    } else {
        out << "periodic="
            << std::chrono::duration<double, std::milli>(value.periodic.time_period).count()
            << "ms";
    }
    out << ",count=" << value.periodic.count;
    if (reorder) {
        out << "pairs";
    }
    return out.str();
}

bool impairment_enabled(const options& opt) {
    return counted_impairment_enabled(opt.loss) ||
           counted_impairment_enabled(opt.duplicate) ||
           counted_impairment_enabled(opt.reorder) ||
           jitter_impairment_enabled(opt.jitter);
}

void print_impairment(const options& opt) {
    if (!impairment_enabled(opt)) {
        return;
    }

    std::cerr
        << "impairment: loss=" << describe_counted_impairment(opt.loss, false)
        << " duplicate=" << describe_counted_impairment(opt.duplicate, false)
        << " reorder=" << describe_counted_impairment(opt.reorder, true);

    if (opt.jitter.mode == jitter_mode::random) {
        std::cerr << " jitter=random,max-ms=" << opt.jitter.max_ms;
    } else if (opt.jitter.mode == jitter_mode::target) {
        std::cerr << " jitter=target,target-ms=" << opt.jitter.target_ms
                  << ",target-mode=" << jitter_target_mode_name(opt.jitter.target_mode);
    }
    if (opt.seed) {
        std::cerr << " seed=" << *opt.seed;
    }

    std::cerr << "\n";
}

void print_impairment_warnings(const options& opt) {
    const double interval_ms = nominal_packet_interval_ms(opt);
    const bool has_counted_errors =
        counted_impairment_enabled(opt.loss) ||
        counted_impairment_enabled(opt.duplicate) ||
        counted_impairment_enabled(opt.reorder);
    const bool has_rate_error =
        (opt.loss.mode == occurrence_mode::rate && opt.loss.rate > 0.0) ||
        (opt.duplicate.mode == occurrence_mode::rate && opt.duplicate.rate > 0.0) ||
        (opt.reorder.mode == occurrence_mode::rate && opt.reorder.rate > 0.0);

    if (opt.uses_legacy_impairment_options) {
        std::cerr << "warning: legacy impairment aliases are deprecated; use --impair type,mode=...,key=value\n";
    }

    const auto warn_time_period_capacity = [&opt](
        const counted_impairment& value, bool reorder, const char* type) {
        if (value.mode != occurrence_mode::periodic ||
            value.periodic.basis != period_basis::time) {
            return;
        }
        const double expected_packets =
            static_cast<double>(opt.bitrate_bps) / static_cast<double>(opt.payload_size * 8) *
            std::chrono::duration<double>(value.periodic.time_period).count();
        const std::uint64_t required = reorder ? value.periodic.count * 2 : value.periodic.count;
        if (expected_packets < static_cast<double>(required)) {
            std::cerr
                << "warning: --impair " << type << " time period has about "
                << expected_packets << " nominal packets but requires " << required
                << "; a window can contain fewer errors than count.\n";
        }
    };
    warn_time_period_capacity(opt.loss, false, "loss");
    warn_time_period_capacity(opt.duplicate, false, "duplicate");
    warn_time_period_capacity(opt.reorder, true, "reorder");

    if (opt.jitter.mode == jitter_mode::random && opt.jitter.max_ms > interval_ms) {
        std::cerr
            << "warning: jitter random max-ms " << opt.jitter.max_ms
            << " exceeds the nominal packet interval " << interval_ms
            << " ms; ordered delivery clamps some delays, so the configured maximum delay may not be observed.\n";
    }

    if (jitter_target_reorders(opt)) {
        std::cerr
            << "warning: jitter target-mode=reorder permits "
            << (opt.proto == proto_type::rtp ? "RTP" : "SRT")
            << " data packets to arrive out of order; target-ms is best effort and includes reordering effects.\n";
    }

    if (jitter_impairment_enabled(opt.jitter) &&
        opt.jitter.mode == jitter_mode::target && has_counted_errors) {
        std::cerr
            << "warning: loss, duplicate, or reorder injection changes the jitter estimator input; jitter target-ms is not guaranteed with these impairments.\n";
    }

    if (has_rate_error) {
