void run_rtp(const options& opt) {
    const double packets_per_sec =
        static_cast<double>(opt.bitrate_bps) /
        static_cast<double>(opt.payload_size * 8);

    if (packets_per_sec <= 0.0) {
        std::cerr << "invalid packets_per_sec\n";
        return;
    }

    const auto interval = std::chrono::nanoseconds(
        static_cast<long long>(1'000'000'000.0 / packets_per_sec));

    const std::uint32_t ts_step =
        static_cast<std::uint32_t>(
            static_cast<double>(opt.clock_rate) / packets_per_sec);

    udp_rtp_sender media;
    media.ssrc = opt.ssrc;
    media.pt = opt.pt;
    media.payload_size = opt.payload_size;
    media.mpegts_payload = opt.mpegts_payload;
    apply_mcast_options(media, opt);

    if (!media.open(opt.dst, opt.port)) {
        return;
    }

    udp_rtp_sender fec_row;
    udp_rtp_sender fec_col;

    if (opt.fec) {
        fec_row.ssrc = opt.fec_row_ssrc;
        fec_row.pt = opt.fec_pt;
        fec_row.payload_size = opt.payload_size;
        fec_row.mpegts_payload = false;
        apply_mcast_options(fec_row, opt);

        fec_col.ssrc = opt.fec_col_ssrc;
        fec_col.pt = opt.fec_pt;
        fec_col.payload_size = opt.payload_size;
        fec_col.mpegts_payload = false;
        apply_mcast_options(fec_col, opt);

        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
            media.close();
            return;
        }

        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
            media.close();
            fec_row.close();
            return;
        }
    }

    std::cerr
        << "RTP media: " << opt.dst << ":" << opt.port
        << " ssrc=" << opt.ssrc
        << " pt=" << static_cast<int>(opt.pt)
        << " bitrate=" << opt.bitrate_bps
        << " payload=" << opt.payload_size
        << " pps=" << packets_per_sec
        << " ts_step=" << ts_step
        << "\n";

    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
        std::cerr
            << "multicast: ttl=" << opt.mcast_ttl
            << " loop=" << opt.mcast_loop;

        if (!opt.mcast_if.empty()) {
            std::cerr << " if=" << opt.mcast_if;
        } else {
            std::cerr << " if=<route-default>";
        }

        std::cerr << "\n";
    }

    print_impairment(opt);
    print_impairment_warnings(opt);

    if (opt.fec) {
        std::cerr
            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
            << " ssrc=" << opt.fec_row_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " L=" << opt.fec_l
            << "\n";

        std::cerr
            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
            << " ssrc=" << opt.fec_col_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " D=" << opt.fec_d
            << "\n";
    }

    packet_scheduler scheduler(
        opt,
        [&media](packet value) { media.send_packet(value); },
        jitter_target_protocol::rtp);
    packet_impairer impairment(opt, [&scheduler](packet value) {
        scheduler.submit(std::move(value));
    });

    packet media_packet;

    fec_state fec;
    std::vector<std::uint8_t> fec_packet;

    auto next = clock_type::now();

    while (!g_stop) {
        media.make_packet(media_packet);

        if (opt.fec) {
            xor_payload(fec.row_xor, media_packet);
            xor_payload(fec.col_xor, media_packet);

            ++fec.row_count;
            ++fec.col_count;

            if (fec.row_count >= opt.fec_l) {
                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
                fec_row.send_packet(fec_packet);

                ++fec_row.seq;
                fec_row.timestamp += ts_step * opt.fec_l;

                fec.row_xor.clear();
                fec.row_count = 0;
            }

            if (fec.col_count >= opt.fec_d) {
                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
                fec_col.send_packet(fec_packet);

                ++fec_col.seq;
                fec_col.timestamp += ts_step * opt.fec_d;

                fec.col_xor.clear();
                fec.col_count = 0;
            }
        }

        scheduler.set_base_time(next);
        impairment.submit(media_packet);

        ++media.seq;
        media.timestamp += ts_step;

        next += interval;
        std::this_thread::sleep_until(next);
    }

    impairment.flush();
    scheduler.stop();
    media.close();

    if (opt.fec) {
        fec_row.close();
        fec_col.close();
    }
}

#ifdef ENABLE_SRT
class srt_impairment_proxy {
public:
    explicit srt_impairment_proxy(const options& opt)
        : jitter_ms_(opt.jitter.max_ms)
        , jitter_target_ms_(opt.jitter.target_ms)
        , target_reorder_(jitter_target_reorders(opt))
        , nominal_interval_ms_(
            1000.0 * static_cast<double>(opt.payload_size) * 8.0 /
            static_cast<double>(opt.bitrate_bps))
        , rng_(opt.seed ? (*opt.seed ^ 0x85ebca6bU) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , impairment_(opt, [this](packet value) {
            schedule(std::move(value));
        }) {}

    ~srt_impairment_proxy() {
        stop();
    }

    bool open(const std::string& dst, std::uint16_t port) {
        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (downstream_fd_ < 0) {
            perror("SRT proxy downstream socket");
            return false;
        }

        std::memset(&destination_, 0, sizeof(destination_));
        destination_.sin_family = AF_INET;
        destination_.sin_port = htons(port);
        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
            std::cerr << "invalid SRT destination ip: " << dst << "\n";
            close_fds();
            return false;
        }

        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (upstream_fd_ < 0) {
            perror("SRT proxy upstream socket");
            close_fds();
            return false;
        }

        sockaddr_in listen{};
        listen.sin_family = AF_INET;
        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        listen.sin_port = 0;
        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
            perror("SRT proxy bind");
            close_fds();
            return false;
        }

        socklen_t length = sizeof(listen);
        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
            perror("SRT proxy getsockname");
            close_fds();
            return false;
        }

        local_port_ = ntohs(listen.sin_port);
        return true;
    }

    void start() {
        worker_ = std::thread([this] { run(); });
    }

    void stop() {
        stopping_ = true;
        if (worker_.joinable()) {
            worker_.join();
        }
        close_fds();
    }

    std::uint16_t local_port() const {
        return local_port_;
    }

private:
    static bool is_data_packet(const packet& value) {
        return value.size() >= 16 && (value[0] & 0x80U) == 0;
    }

    void close_fds() {
        if (upstream_fd_ >= 0) {
            ::close(upstream_fd_);
            upstream_fd_ = -1;
        }
        if (downstream_fd_ >= 0) {
            ::close(downstream_fd_);
            downstream_fd_ = -1;
        }
    }

    void send_downstream(const packet& value) {
        const auto sent = ::sendto(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&destination_),
            sizeof(destination_));
        if (sent < 0) {
            perror("SRT proxy send downstream");
        }
    }

    void send_upstream(const packet& value) {
        if (!has_sender_) {
            return;
        }

        const auto sent = ::sendto(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&sender_),
            sender_length_);
        if (sent < 0) {
            perror("SRT proxy send upstream");
        }
    }

    void schedule(packet value) {
        const auto base = next_base_time_.value_or(clock_type::now());
        next_base_time_ = base + std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double, std::milli>(nominal_interval_ms_));

        auto due = base;
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (target_reorder_ == false && last_due_ && due < *last_due_) {
            due = *last_due_;
        }

        scheduled_.emplace(due, std::move(value));
        last_due_ = due;
    }

    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            jitter_target_protocol::srt, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    void flush_ready() {
        const auto now = clock_type::now();
        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
            send_downstream(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
        }
    }

    void forward_from_upstream() {
        packet value(65536);
        sockaddr_storage source{};
        socklen_t source_length = sizeof(source);
        const auto received = ::recvfrom(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<sockaddr*>(&source),
            &source_length);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        sender_ = source;
        sender_length_ = source_length;
        has_sender_ = true;

        if (is_data_packet(value)) {
            impairment_.submit(std::move(value));
        } else {
            send_downstream(value);
        }
    }

    void forward_from_downstream() {
        packet value(65536);
        const auto received = ::recvfrom(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            nullptr,
            nullptr);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        send_upstream(value);
    }

    void run() {
        while (!stopping_) {
            pollfd fds[2]{};
            fds[0].fd = upstream_fd_;
            fds[0].events = POLLIN;
            fds[1].fd = downstream_fd_;
            fds[1].events = POLLIN;
        if (is_ipv4_multicast_addr(addr.sin_addr)) {
            if (!configure_multicast()) {
                return false;
            }
        }

        return true;
    }

    bool configure_multicast() {
        const unsigned char ttl = static_cast<unsigned char>(mcast_ttl);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
            perror("setsockopt IP_MULTICAST_TTL");
            return false;
        }

        const unsigned char loop = static_cast<unsigned char>(mcast_loop != 0);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof(loop)) < 0) {
            perror("setsockopt IP_MULTICAST_LOOP");
            return false;
        }

        if (!mcast_if.empty()) {
            in_addr local_if{};
            if (::inet_pton(AF_INET, mcast_if.c_str(), &local_if) != 1) {
                std::cerr << "invalid --mcast-if: " << mcast_if << "\n";
                return false;
            }

            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &local_if, sizeof(local_if)) < 0) {
                perror("setsockopt IP_MULTICAST_IF");
                return false;
            }
        }

        return true;
    }

    void close() {
        if (fd >= 0) {
            ::close(fd);
            fd = -1;
        }
    }

    void make_packet(std::vector<std::uint8_t>& out) {
        out.resize(12 + payload_size);

        out[0] = 0x80;          // V=2, P=0, X=0, CC=0
        out[1] = pt & 0x7f;     // M=0, PT

        put_u16_be(&out[2], seq);
        put_u32_be(&out[4], timestamp);
        put_u32_be(&out[8], ssrc);

        auto* payload = out.data() + 12;

        if (mpegts_payload) {
            // MPEG-TS風ダミーpayload。
            // 188 byteごとにsync byte 0x47を置くだけなので、再生可能なTSではない。
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = (i % 188 == 0)
                    ? 0x47
                    : static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        } else {
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        }
    }

    void send_packet(const std::vector<std::uint8_t>& packet) {
        const auto n = ::sendto(
            fd,
            packet.data(),
            packet.size(),
            0,
            reinterpret_cast<const sockaddr*>(&addr),
            sizeof(addr));

        if (n < 0) {
            perror("sendto");
        }
    }
};

struct fec_state {
    std::vector<std::uint8_t> row_xor;
    std::vector<std::uint8_t> col_xor;

    std::uint32_t row_count{0};
    std::uint32_t col_count{0};
};

void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
    constexpr std::size_t header_size = 12;

    if (rtp_packet.size() < header_size) {
        return;
    }

    const std::size_t payload_len = rtp_packet.size() - header_size;

    if (acc.empty()) {
        acc.assign(payload_len, 0);
    }

    const auto n = std::min(acc.size(), payload_len);
    for (std::size_t i = 0; i < n; ++i) {
        acc[i] ^= rtp_packet[header_size + i];
    }
}

void make_fec_payload_packet(
    udp_rtp_sender& fec_sender,
    const std::vector<std::uint8_t>& xor_payload_data,
    std::vector<std::uint8_t>& out)
{
    fec_sender.payload_size = xor_payload_data.size();
    fec_sender.make_packet(out);

    if (!xor_payload_data.empty()) {
        std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
    }
}

void apply_mcast_options(udp_rtp_sender& s, const options& opt) {
    s.mcast_if = opt.mcast_if;
    s.mcast_ttl = opt.mcast_ttl;
    s.mcast_loop = opt.mcast_loop;
}

using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class occurrence_selector {
public:
    occurrence_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool hit(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const bool selected = packets_in_period_ >
                settings_.periodic.packet_period - settings_.periodic.count;
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            selected_in_window_ = 0;
            time_window_active_ = true;
        }
        if (!time_window_active_ ||
            selected_in_window_ >= settings_.periodic.count) {
            return false;
        }
        ++selected_in_window_;
        return true;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t selected_in_window_{0};
    bool time_window_active_{false};
};

class reorder_selector {
public:
    reorder_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool starts_pair(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const std::uint64_t pair_packets = settings_.periodic.count * 2;
            const std::uint64_t first_pair_packet =
                settings_.periodic.packet_period - pair_packets + 1;
            const bool selected = packets_in_period_ >= first_pair_packet &&
                ((packets_in_period_ - first_pair_packet) % 2 == 0);
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            packets_in_window_ = 0;
            time_window_active_ = true;
        }
        if (!time_window_active_) {
            return false;
        }
        const std::uint64_t pair_packets = settings_.periodic.count * 2;
        const bool selected = packets_in_window_ < pair_packets &&
            (packets_in_window_ % 2 == 0);
        if (packets_in_window_ < pair_packets) {
            ++packets_in_window_;
        }
        return selected;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t packets_in_window_{0};
    bool time_window_active_{false};
};

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_(opt.loss, impairment_seed(opt, 0x243f6a88U))
        , duplicate_(opt.duplicate, impairment_seed(opt, 0x85a308d3U))
        , reorder_(opt.reorder, impairment_seed(opt, 0x13198a2eU))
        , submit_(std::move(submit)) {}

    void submit(packet value) {
        const auto now = clock_type::now();
        const bool drop = loss_.hit(now);
        const bool duplicate = duplicate_.hit(now);
        const bool reorder = reorder_.starts_pair(now);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = delayed_packet{std::move(value), duplicate};
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
        }
    }

private:
    static std::uint32_t impairment_seed(const options& opt, std::uint32_t salt) {
        return opt.seed ? (*opt.seed ^ salt) : std::random_device{}();
    }

    struct delayed_packet {
        packet value;
        bool duplicate{false};
    };

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    occurrence_selector loss_;
    occurrence_selector duplicate_;
    reorder_selector reorder_;
    packet_submitter submit_;
    std::optional<delayed_packet> delayed_;
};

enum class jitter_target_protocol {
-rwxr-xr-x. 1 root root  41248 May  6 15:20 be/build/streamgen
-rwxr-xr-x. 1 root root 114496 Sep  9 15:37 be/tools/streamgen

item.aggregated_output:
        opt.clock_rate > 0 && opt.jitter.target_ms < 1000.0 / opt.clock_rate) {
        std::cerr
            << "warning: jitter target-ms " << opt.jitter.target_ms
            << " is below the RTP timestamp resolution " << (1000.0 / opt.clock_rate)
            << " ms; the target cannot be represented exactly.\n";
    }

    if (opt.proto == proto_type::srt && jitter_impairment_enabled(opt.jitter) &&
        opt.jitter.mode == jitter_mode::target &&
        opt.jitter.target_ms < 10.0) {
        std::cerr
            << "warning: SRT impairment scheduling polls at up to 10 ms; small jitter targets can be dominated by scheduler latency.\n";
    }

    if (opt.proto == proto_type::srt && has_counted_errors) {
        std::cerr
            << "warning: SRT retransmission and receiver buffering can change observed loss, reorder, and jitter from the UDP proxy settings.\n";
    }
}

void run_rtp(const options& opt) {
    const double packets_per_sec =
        static_cast<double>(opt.bitrate_bps) /
        static_cast<double>(opt.payload_size * 8);

    if (packets_per_sec <= 0.0) {
        std::cerr << "invalid packets_per_sec\n";
        return;
    }

    const auto interval = std::chrono::nanoseconds(
        static_cast<long long>(1'000'000'000.0 / packets_per_sec));

    const std::uint32_t ts_step =
        static_cast<std::uint32_t>(
            static_cast<double>(opt.clock_rate) / packets_per_sec);

    udp_rtp_sender media;
    media.ssrc = opt.ssrc;
    media.pt = opt.pt;
    media.payload_size = opt.payload_size;
    media.mpegts_payload = opt.mpegts_payload;
    apply_mcast_options(media, opt);

    if (!media.open(opt.dst, opt.port)) {
        return;
    }

    udp_rtp_sender fec_row;
    udp_rtp_sender fec_col;

    if (opt.fec) {
        fec_row.ssrc = opt.fec_row_ssrc;
        fec_row.pt = opt.fec_pt;
        fec_row.payload_size = opt.payload_size;
        fec_row.mpegts_payload = false;
        apply_mcast_options(fec_row, opt);

        fec_col.ssrc = opt.fec_col_ssrc;
        fec_col.pt = opt.fec_pt;
        fec_col.payload_size = opt.payload_size;
        fec_col.mpegts_payload = false;
        apply_mcast_options(fec_col, opt);

        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
            media.close();
            return;
        }

        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
            media.close();
            fec_row.close();
            return;
        }
    }

    std::cerr
        << "RTP media: " << opt.dst << ":" << opt.port
        << " ssrc=" << opt.ssrc
        << " pt=" << static_cast<int>(opt.pt)
        << " bitrate=" << opt.bitrate_bps
        << " payload=" << opt.payload_size
        << " pps=" << packets_per_sec
        << " ts_step=" << ts_step
        << "\n";

    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
        std::cerr
            << "multicast: ttl=" << opt.mcast_ttl
            << " loop=" << opt.mcast_loop;

        if (!opt.mcast_if.empty()) {
            std::cerr << " if=" << opt.mcast_if;
        } else {
            std::cerr << " if=<route-default>";
        }

        std::cerr << "\n";
    }

    print_impairment(opt);
    print_impairment_warnings(opt);

    if (opt.fec) {
        std::cerr
            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
            << " ssrc=" << opt.fec_row_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " L=" << opt.fec_l
            << "\n";

        std::cerr
            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
            << " ssrc=" << opt.fec_col_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " D=" << opt.fec_d
            << "\n";
    }

    packet_scheduler scheduler(
        opt,
        [&media](packet value) { media.send_packet(value); },
        jitter_target_protocol::rtp);
    packet_impairer impairment(opt, [&scheduler](packet value) {
        scheduler.submit(std::move(value));
    });

    packet media_packet;

    fec_state fec;
    std::vector<std::uint8_t> fec_packet;

    auto next = clock_type::now();

    while (!g_stop) {
        media.make_packet(media_packet);

        if (opt.fec) {
            xor_payload(fec.row_xor, media_packet);
            xor_payload(fec.col_xor, media_packet);

            ++fec.row_count;
            ++fec.col_count;

            if (fec.row_count >= opt.fec_l) {
                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
                fec_row.send_packet(fec_packet);

                ++fec_row.seq;
                fec_row.timestamp += ts_step * opt.fec_l;

                fec.row_xor.clear();
                fec.row_count = 0;
            }

            if (fec.col_count >= opt.fec_d) {
                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
                fec_col.send_packet(fec_packet);

                ++fec_col.seq;
                fec_col.timestamp += ts_step * opt.fec_d;

                fec.col_xor.clear();
                fec.col_count = 0;
            }
        }

        scheduler.set_base_time(next);
        impairment.submit(media_packet);

        ++media.seq;
        media.timestamp += ts_step;

        next += interval;
        std::this_thread::sleep_until(next);
    }

    impairment.flush();
    scheduler.stop();
    media.close();

    if (opt.fec) {
        fec_row.close();
        fec_col.close();
    }
}

#ifdef ENABLE_SRT
class srt_impairment_proxy {
public:
    explicit srt_impairment_proxy(const options& opt)
        : jitter_ms_(opt.jitter.max_ms)
        , jitter_target_ms_(opt.jitter.target_ms)
        , target_reorder_(jitter_target_reorders(opt))
        , nominal_interval_ms_(
            1000.0 * static_cast<double>(opt.payload_size) * 8.0 /
            static_cast<double>(opt.bitrate_bps))
        , rng_(opt.seed ? (*opt.seed ^ 0x85ebca6bU) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , impairment_(opt, [this](packet value) {
            schedule(std::move(value));
        }) {}

    ~srt_impairment_proxy() {
        stop();
    }

    bool open(const std::string& dst, std::uint16_t port) {
        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (downstream_fd_ < 0) {
            perror("SRT proxy downstream socket");
            return false;
        }

        std::memset(&destination_, 0, sizeof(destination_));
        destination_.sin_family = AF_INET;
        destination_.sin_port = htons(port);
        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
            std::cerr << "invalid SRT destination ip: " << dst << "\n";
            close_fds();
            return false;
        }

        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (upstream_fd_ < 0) {
            perror("SRT proxy upstream socket");
            close_fds();
            return false;
        }

        sockaddr_in listen{};
        listen.sin_family = AF_INET;
        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        listen.sin_port = 0;
        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
            perror("SRT proxy bind");
            close_fds();
            return false;
        }

        socklen_t length = sizeof(listen);
        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
            perror("SRT proxy getsockname");
            close_fds();
            return false;
        }

        local_port_ = ntohs(listen.sin_port);
        return true;
    }

    void start() {
        worker_ = std::thread([this] { run(); });
    }

    void stop() {
        stopping_ = true;
        if (worker_.joinable()) {
            worker_.join();
        }
        close_fds();
    }

    std::uint16_t local_port() const {
        return local_port_;
    }

private:
    static bool is_data_packet(const packet& value) {
        return value.size() >= 16 && (value[0] & 0x80U) == 0;
    }

    void close_fds() {
        if (upstream_fd_ >= 0) {
            ::close(upstream_fd_);
            upstream_fd_ = -1;
        }
        if (downstream_fd_ >= 0) {
            ::close(downstream_fd_);
            downstream_fd_ = -1;
        }
    }

    void send_downstream(const packet& value) {
        const auto sent = ::sendto(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&destination_),
            sizeof(destination_));
        if (sent < 0) {
            perror("SRT proxy send downstream");
        }
    }

    void send_upstream(const packet& value) {
        if (!has_sender_) {
            return;
        }

        const auto sent = ::sendto(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&sender_),
            sender_length_);
        if (sent < 0) {
            perror("SRT proxy send upstream");
        }
    }

    void schedule(packet value) {
        const auto base = next_base_time_.value_or(clock_type::now());
        next_base_time_ = base + std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double, std::milli>(nominal_interval_ms_));

        auto due = base;
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (target_reorder_ == false && last_due_ && due < *last_due_) {
            due = *last_due_;
        }

        scheduled_.emplace(due, std::move(value));
        last_due_ = due;
    }

    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            jitter_target_protocol::srt, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    void flush_ready() {
        const auto now = clock_type::now();
        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
            send_downstream(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
        }
    }

    void forward_from_upstream() {
        packet value(65536);
        sockaddr_storage source{};
        socklen_t source_length = sizeof(source);
        const auto received = ::recvfrom(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<sockaddr*>(&source),
            &source_length);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        sender_ = source;
        sender_length_ = source_length;
        has_sender_ = true;

        if (is_data_packet(value)) {
            impairment_.submit(std::move(value));
        } else {
            send_downstream(value);
        }
    }

    void forward_from_downstream() {
        packet value(65536);
        const auto received = ::recvfrom(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            nullptr,
            nullptr);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        send_upstream(value);
    }

    void run() {
        while (!stopping_) {
            pollfd fds[2]{};
            fds[0].fd = upstream_fd_;
            fds[0].events = POLLIN;
            fds[1].fd = downstream_fd_;
            fds[1].events = POLLIN;
        if (is_ipv4_multicast_addr(addr.sin_addr)) {
            if (!configure_multicast()) {
                return false;
            }
        }

        return true;
    }

    bool configure_multicast() {
        const unsigned char ttl = static_cast<unsigned char>(mcast_ttl);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
            perror("setsockopt IP_MULTICAST_TTL");
            return false;
        }

        const unsigned char loop = static_cast<unsigned char>(mcast_loop != 0);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof(loop)) < 0) {
            perror("setsockopt IP_MULTICAST_LOOP");
            return false;
        }

        if (!mcast_if.empty()) {
            in_addr local_if{};
            if (::inet_pton(AF_INET, mcast_if.c_str(), &local_if) != 1) {
                std::cerr << "invalid --mcast-if: " << mcast_if << "\n";
                return false;
            }

            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &local_if, sizeof(local_if)) < 0) {
                perror("setsockopt IP_MULTICAST_IF");
                return false;
            }
        }

        return true;
    }

    void close() {
        if (fd >= 0) {
            ::close(fd);
            fd = -1;
        }
    }

    void make_packet(std::vector<std::uint8_t>& out) {
        out.resize(12 + payload_size);

        out[0] = 0x80;          // V=2, P=0, X=0, CC=0
        out[1] = pt & 0x7f;     // M=0, PT

        put_u16_be(&out[2], seq);
        put_u32_be(&out[4], timestamp);
        put_u32_be(&out[8], ssrc);

        auto* payload = out.data() + 12;

        if (mpegts_payload) {
            // MPEG-TS風ダミーpayload。
            // 188 byteごとにsync byte 0x47を置くだけなので、再生可能なTSではない。
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = (i % 188 == 0)
                    ? 0x47
                    : static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        } else {
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        }
    }

    void send_packet(const std::vector<std::uint8_t>& packet) {
        const auto n = ::sendto(
            fd,
            packet.data(),
            packet.size(),
            0,
            reinterpret_cast<const sockaddr*>(&addr),
            sizeof(addr));

        if (n < 0) {
            perror("sendto");
        }
    }
};

struct fec_state {
    std::vector<std::uint8_t> row_xor;
    std::vector<std::uint8_t> col_xor;

    std::uint32_t row_count{0};
    std::uint32_t col_count{0};
};

void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
    constexpr std::size_t header_size = 12;

    if (rtp_packet.size() < header_size) {
        return;
    }

    const std::size_t payload_len = rtp_packet.size() - header_size;

    if (acc.empty()) {
        acc.assign(payload_len, 0);
    }

    const auto n = std::min(acc.size(), payload_len);
    for (std::size_t i = 0; i < n; ++i) {
        acc[i] ^= rtp_packet[header_size + i];
    }
}

void make_fec_payload_packet(
    udp_rtp_sender& fec_sender,
    const std::vector<std::uint8_t>& xor_payload_data,
    std::vector<std::uint8_t>& out)
{
    fec_sender.payload_size = xor_payload_data.size();
    fec_sender.make_packet(out);

    if (!xor_payload_data.empty()) {
        std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
    }
}

void apply_mcast_options(udp_rtp_sender& s, const options& opt) {
    s.mcast_if = opt.mcast_if;
    s.mcast_ttl = opt.mcast_ttl;
    s.mcast_loop = opt.mcast_loop;
}

using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class occurrence_selector {
public:
    occurrence_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool hit(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const bool selected = packets_in_period_ >
                settings_.periodic.packet_period - settings_.periodic.count;
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            selected_in_window_ = 0;
            time_window_active_ = true;
        }
        if (!time_window_active_ ||
            selected_in_window_ >= settings_.periodic.count) {
            return false;
        }
        ++selected_in_window_;
        return true;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t selected_in_window_{0};
    bool time_window_active_{false};
};

class reorder_selector {
public:
    reorder_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool starts_pair(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const std::uint64_t pair_packets = settings_.periodic.count * 2;
            const std::uint64_t first_pair_packet =
                settings_.periodic.packet_period - pair_packets + 1;
            const bool selected = packets_in_period_ >= first_pair_packet &&
                ((packets_in_period_ - first_pair_packet) % 2 == 0);
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            packets_in_window_ = 0;
            time_window_active_ = true;
        }
        if (!time_window_active_) {
            return false;
        }
        const std::uint64_t pair_packets = settings_.periodic.count * 2;
        const bool selected = packets_in_window_ < pair_packets &&
            (packets_in_window_ % 2 == 0);
        if (packets_in_window_ < pair_packets) {
            ++packets_in_window_;
        }
        return selected;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t packets_in_window_{0};
    bool time_window_active_{false};
};

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_(opt.loss, impairment_seed(opt, 0x243f6a88U))
        , duplicate_(opt.duplicate, impairment_seed(opt, 0x85a308d3U))
        , reorder_(opt.reorder, impairment_seed(opt, 0x13198a2eU))
        , submit_(std::move(submit)) {}

    void submit(packet value) {
        const auto now = clock_type::now();
        const bool drop = loss_.hit(now);
        const bool duplicate = duplicate_.hit(now);
        const bool reorder = reorder_.starts_pair(now);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = delayed_packet{std::move(value), duplicate};
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
        }
    }

private:
    static std::uint32_t impairment_seed(const options& opt, std::uint32_t salt) {
        return opt.seed ? (*opt.seed ^ salt) : std::random_device{}();
    }

    struct delayed_packet {
        packet value;
        bool duplicate{false};
    };

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    occurrence_selector loss_;
    occurrence_selector duplicate_;
    reorder_selector reorder_;
    packet_submitter submit_;
    std::optional<delayed_packet> delayed_;
};

enum class jitter_target_protocol {
-rwxr-xr-x. 1 root root  41248 May  6 15:20 be/build/streamgen
-rwxr-xr-x. 1 root root 114496 Sep  9 15:37 be/tools/streamgen

item.formatted_output:
        opt.clock_rate > 0 && opt.jitter.target_ms < 1000.0 / opt.clock_rate) {
        std::cerr
            << "warning: jitter target-ms " << opt.jitter.target_ms
            << " is below the RTP timestamp resolution " << (1000.0 / opt.clock_rate)
            << " ms; the target cannot be represented exactly.\n";
    }

    if (opt.proto == proto_type::srt && jitter_impairment_enabled(opt.jitter) &&
        opt.jitter.mode == jitter_mode::target &&
        opt.jitter.target_ms < 10.0) {
        std::cerr
            << "warning: SRT impairment scheduling polls at up to 10 ms; small jitter targets can be dominated by scheduler latency.\n";
    }

    if (opt.proto == proto_type::srt && has_counted_errors) {
        std::cerr
            << "warning: SRT retransmission and receiver buffering can change observed loss, reorder, and jitter from the UDP proxy settings.\n";
    }
}

void run_rtp(const options& opt) {
    const double packets_per_sec =
        static_cast<double>(opt.bitrate_bps) /
        static_cast<double>(opt.payload_size * 8);

    if (packets_per_sec <= 0.0) {
        std::cerr << "invalid packets_per_sec\n";
        return;
    }

    const auto interval = std::chrono::nanoseconds(
        static_cast<long long>(1'000'000'000.0 / packets_per_sec));

    const std::uint32_t ts_step =
        static_cast<std::uint32_t>(
            static_cast<double>(opt.clock_rate) / packets_per_sec);

    udp_rtp_sender media;
    media.ssrc = opt.ssrc;
    media.pt = opt.pt;
    media.payload_size = opt.payload_size;
    media.mpegts_payload = opt.mpegts_payload;
    apply_mcast_options(media, opt);

    if (!media.open(opt.dst, opt.port)) {
        return;
    }

    udp_rtp_sender fec_row;
    udp_rtp_sender fec_col;

    if (opt.fec) {
        fec_row.ssrc = opt.fec_row_ssrc;
        fec_row.pt = opt.fec_pt;
        fec_row.payload_size = opt.payload_size;
        fec_row.mpegts_payload = false;
        apply_mcast_options(fec_row, opt);

        fec_col.ssrc = opt.fec_col_ssrc;
        fec_col.pt = opt.fec_pt;
        fec_col.payload_size = opt.payload_size;
        fec_col.mpegts_payload = false;
        apply_mcast_options(fec_col, opt);

        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
            media.close();
            return;
        }

        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
            media.close();
            fec_row.close();
            return;
        }
    }

    std::cerr
        << "RTP media: " << opt.dst << ":" << opt.port
        << " ssrc=" << opt.ssrc
        << " pt=" << static_cast<int>(opt.pt)
        << " bitrate=" << opt.bitrate_bps
        << " payload=" << opt.payload_size
        << " pps=" << packets_per_sec
        << " ts_step=" << ts_step
        << "\n";

    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
        std::cerr
            << "multicast: ttl=" << opt.mcast_ttl
            << " loop=" << opt.mcast_loop;

        if (!opt.mcast_if.empty()) {
            std::cerr << " if=" << opt.mcast_if;
        } else {
            std::cerr << " if=<route-default>";
        }

        std::cerr << "\n";
    }

    print_impairment(opt);
    print_impairment_warnings(opt);

    if (opt.fec) {
        std::cerr
            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
            << " ssrc=" << opt.fec_row_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " L=" << opt.fec_l
            << "\n";

        std::cerr
            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
            << " ssrc=" << opt.fec_col_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " D=" << opt.fec_d
            << "\n";
    }

    packet_scheduler scheduler(
        opt,
        [&media](packet value) { media.send_packet(value); },
        jitter_target_protocol::rtp);
    packet_impairer impairment(opt, [&scheduler](packet value) {
        scheduler.submit(std::move(value));
    });

    packet media_packet;

    fec_state fec;
    std::vector<std::uint8_t> fec_packet;

    auto next = clock_type::now();

    while (!g_stop) {
        media.make_packet(media_packet);

        if (opt.fec) {
            xor_payload(fec.row_xor, media_packet);
            xor_payload(fec.col_xor, media_packet);

            ++fec.row_count;
            ++fec.col_count;

            if (fec.row_count >= opt.fec_l) {
                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
                fec_row.send_packet(fec_packet);

                ++fec_row.seq;
                fec_row.timestamp += ts_step * opt.fec_l;

                fec.row_xor.clear();
                fec.row_count = 0;
            }

            if (fec.col_count >= opt.fec_d) {
                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
                fec_col.send_packet(fec_packet);

                ++fec_col.seq;
                fec_col.timestamp += ts_step * opt.fec_d;

                fec.col_xor.clear();
                fec.col_count = 0;
            }
        }

        scheduler.set_base_time(next);
        impairment.submit(media_packet);

        ++media.seq;
        media.timestamp += ts_step;

        next += interval;
        std::this_thread::sleep_until(next);
    }

    impairment.flush();
    scheduler.stop();
    media.close();

    if (opt.fec) {
        fec_row.close();
        fec_col.close();
    }
}

#ifdef ENABLE_SRT
class srt_impairment_proxy {
public:
    explicit srt_impairment_proxy(const options& opt)
        : jitter_ms_(opt.jitter.max_ms)
        , jitter_target_ms_(opt.jitter.target_ms)
        , target_reorder_(jitter_target_reorders(opt))
        , nominal_interval_ms_(
            1000.0 * static_cast<double>(opt.payload_size) * 8.0 /
            static_cast<double>(opt.bitrate_bps))
        , rng_(opt.seed ? (*opt.seed ^ 0x85ebca6bU) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , impairment_(opt, [this](packet value) {
            schedule(std::move(value));
        }) {}

    ~srt_impairment_proxy() {
        stop();
    }

    bool open(const std::string& dst, std::uint16_t port) {
        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (downstream_fd_ < 0) {
            perror("SRT proxy downstream socket");
            return false;
        }

        std::memset(&destination_, 0, sizeof(destination_));
        destination_.sin_family = AF_INET;
        destination_.sin_port = htons(port);
        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
            std::cerr << "invalid SRT destination ip: " << dst << "\n";
            close_fds();
            return false;
        }

        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (upstream_fd_ < 0) {
            perror("SRT proxy upstream socket");
            close_fds();
            return false;
        }

        sockaddr_in listen{};
        listen.sin_family = AF_INET;
        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        listen.sin_port = 0;
        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
            perror("SRT proxy bind");
            close_fds();
            return false;
        }

        socklen_t length = sizeof(listen);
        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
            perror("SRT proxy getsockname");
            close_fds();
            return false;
        }

        local_port_ = ntohs(listen.sin_port);
        return true;
    }

    void start() {
        worker_ = std::thread([this] { run(); });
    }

    void stop() {
        stopping_ = true;
        if (worker_.joinable()) {
            worker_.join();
        }
        close_fds();
    }

    std::uint16_t local_port() const {
        return local_port_;
    }

private:
    static bool is_data_packet(const packet& value) {
        return value.size() >= 16 && (value[0] & 0x80U) == 0;
    }

    void close_fds() {
        if (upstream_fd_ >= 0) {
            ::close(upstream_fd_);
            upstream_fd_ = -1;
        }
        if (downstream_fd_ >= 0) {
            ::close(downstream_fd_);
            downstream_fd_ = -1;
        }
    }

    void send_downstream(const packet& value) {
        const auto sent = ::sendto(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&destination_),
            sizeof(destination_));
        if (sent < 0) {
            perror("SRT proxy send downstream");
        }
    }

    void send_upstream(const packet& value) {
        if (!has_sender_) {
            return;
        }

        const auto sent = ::sendto(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&sender_),
            sender_length_);
        if (sent < 0) {
            perror("SRT proxy send upstream");
        }
    }

    void schedule(packet value) {
        const auto base = next_base_time_.value_or(clock_type::now());
        next_base_time_ = base + std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double, std::milli>(nominal_interval_ms_));

        auto due = base;
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (target_reorder_ == false && last_due_ && due < *last_due_) {
            due = *last_due_;
        }

        scheduled_.emplace(due, std::move(value));
        last_due_ = due;
    }

    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            jitter_target_protocol::srt, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    void flush_ready() {
        const auto now = clock_type::now();
        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
            send_downstream(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
        }
    }

    void forward_from_upstream() {
        packet value(65536);
        sockaddr_storage source{};
        socklen_t source_length = sizeof(source);
        const auto received = ::recvfrom(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<sockaddr*>(&source),
            &source_length);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        sender_ = source;
        sender_length_ = source_length;
        has_sender_ = true;

        if (is_data_packet(value)) {
            impairment_.submit(std::move(value));
        } else {
            send_downstream(value);
        }
    }

    void forward_from_downstream() {
        packet value(65536);
        const auto received = ::recvfrom(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            nullptr,
            nullptr);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        send_upstream(value);
    }

    void run() {
        while (!stopping_) {
            pollfd fds[2]{};
            fds[0].fd = upstream_fd_;
            fds[0].events = POLLIN;
            fds[1].fd = downstream_fd_;
            fds[1].events = POLLIN;
        if (is_ipv4_multicast_addr(addr.sin_addr)) {
            if (!configure_multicast()) {
                return false;
            }
        }

        return true;
    }

    bool configure_multicast() {
        const unsigned char ttl = static_cast<unsigned char>(mcast_ttl);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
            perror("setsockopt IP_MULTICAST_TTL");
            return false;
        }

        const unsigned char loop = static_cast<unsigned char>(mcast_loop != 0);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof(loop)) < 0) {
            perror("setsockopt IP_MULTICAST_LOOP");
            return false;
        }

        if (!mcast_if.empty()) {
            in_addr local_if{};
            if (::inet_pton(AF_INET, mcast_if.c_str(), &local_if) != 1) {
                std::cerr << "invalid --mcast-if: " << mcast_if << "\n";
                return false;
            }

            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &local_if, sizeof(local_if)) < 0) {
                perror("setsockopt IP_MULTICAST_IF");
                return false;
            }
        }

        return true;
    }

    void close() {
        if (fd >= 0) {
            ::close(fd);
            fd = -1;
        }
    }

    void make_packet(std::vector<std::uint8_t>& out) {
        out.resize(12 + payload_size);

        out[0] = 0x80;          // V=2, P=0, X=0, CC=0
        out[1] = pt & 0x7f;     // M=0, PT

        put_u16_be(&out[2], seq);
        put_u32_be(&out[4], timestamp);
        put_u32_be(&out[8], ssrc);

        auto* payload = out.data() + 12;

        if (mpegts_payload) {
            // MPEG-TS風ダミーpayload。
            // 188 byteごとにsync byte 0x47を置くだけなので、再生可能なTSではない。
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = (i % 188 == 0)
                    ? 0x47
                    : static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        } else {
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        }
    }

    void send_packet(const std::vector<std::uint8_t>& packet) {
        const auto n = ::sendto(
            fd,
            packet.data(),
            packet.size(),
            0,
            reinterpret_cast<const sockaddr*>(&addr),
            sizeof(addr));

        if (n < 0) {
            perror("sendto");
        }
    }
};

struct fec_state {
    std::vector<std::uint8_t> row_xor;
    std::vector<std::uint8_t> col_xor;

    std::uint32_t row_count{0};
    std::uint32_t col_count{0};
};

void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
    constexpr std::size_t header_size = 12;

    if (rtp_packet.size() < header_size) {
        return;
    }

    const std::size_t payload_len = rtp_packet.size() - header_size;

    if (acc.empty()) {
        acc.assign(payload_len, 0);
    }

    const auto n = std::min(acc.size(), payload_len);
    for (std::size_t i = 0; i < n; ++i) {
        acc[i] ^= rtp_packet[header_size + i];
    }
}

void make_fec_payload_packet(
    udp_rtp_sender& fec_sender,
    const std::vector<std::uint8_t>& xor_payload_data,
    std::vector<std::uint8_t>& out)
{
    fec_sender.payload_size = xor_payload_data.size();
    fec_sender.make_packet(out);

    if (!xor_payload_data.empty()) {
        std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
    }
}

void apply_mcast_options(udp_rtp_sender& s, const options& opt) {
    s.mcast_if = opt.mcast_if;
    s.mcast_ttl = opt.mcast_ttl;
    s.mcast_loop = opt.mcast_loop;
}

using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class occurrence_selector {
public:
    occurrence_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool hit(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const bool selected = packets_in_period_ >
                settings_.periodic.packet_period - settings_.periodic.count;
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            selected_in_window_ = 0;
            time_window_active_ = true;
        }
        if (!time_window_active_ ||
            selected_in_window_ >= settings_.periodic.count) {
            return false;
        }
        ++selected_in_window_;
        return true;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t selected_in_window_{0};
    bool time_window_active_{false};
};

class reorder_selector {
public:
    reorder_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool starts_pair(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const std::uint64_t pair_packets = settings_.periodic.count * 2;
            const std::uint64_t first_pair_packet =
                settings_.periodic.packet_period - pair_packets + 1;
            const bool selected = packets_in_period_ >= first_pair_packet &&
                ((packets_in_period_ - first_pair_packet) % 2 == 0);
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            packets_in_window_ = 0;
            time_window_active_ = true;
        }
        if (!time_window_active_) {
            return false;
        }
        const std::uint64_t pair_packets = settings_.periodic.count * 2;
        const bool selected = packets_in_window_ < pair_packets &&
            (packets_in_window_ % 2 == 0);
        if (packets_in_window_ < pair_packets) {
            ++packets_in_window_;
        }
        return selected;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t packets_in_window_{0};
    bool time_window_active_{false};
};

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_(opt.loss, impairment_seed(opt, 0x243f6a88U))
        , duplicate_(opt.duplicate, impairment_seed(opt, 0x85a308d3U))
        , reorder_(opt.reorder, impairment_seed(opt, 0x13198a2eU))
        , submit_(std::move(submit)) {}

    void submit(packet value) {
        const auto now = clock_type::now();
        const bool drop = loss_.hit(now);
        const bool duplicate = duplicate_.hit(now);
        const bool reorder = reorder_.starts_pair(now);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = delayed_packet{std::move(value), duplicate};
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
        }
    }

private:
    static std::uint32_t impairment_seed(const options& opt, std::uint32_t salt) {
        return opt.seed ? (*opt.seed ^ salt) : std::random_device{}();
    }

    struct delayed_packet {
        packet value;
        bool duplicate{false};
    };

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    occurrence_selector loss_;
    occurrence_selector duplicate_;
    reorder_selector reorder_;
    packet_submitter submit_;
    std::optional<delayed_packet> delayed_;
};

enum class jitter_target_protocol {
-rwxr-xr-x. 1 root root  41248 May  6 15:20 be/build/streamgen
-rwxr-xr-x. 1 root root 114496 Sep  9 15:37 be/tools/streamgen

output.text:
        opt.clock_rate > 0 && opt.jitter.target_ms < 1000.0 / opt.clock_rate) {
        std::cerr
            << "warning: jitter target-ms " << opt.jitter.target_ms
            << " is below the RTP timestamp resolution " << (1000.0 / opt.clock_rate)
            << " ms; the target cannot be represented exactly.\n";
    }

    if (opt.proto == proto_type::srt && jitter_impairment_enabled(opt.jitter) &&
        opt.jitter.mode == jitter_mode::target &&
        opt.jitter.target_ms < 10.0) {
        std::cerr
            << "warning: SRT impairment scheduling polls at up to 10 ms; small jitter targets can be dominated by scheduler latency.\n";
    }

    if (opt.proto == proto_type::srt && has_counted_errors) {
        std::cerr
            << "warning: SRT retransmission and receiver buffering can change observed loss, reorder, and jitter from the UDP proxy settings.\n";
    }
}

void run_rtp(const options& opt) {
    const double packets_per_sec =
        static_cast<double>(opt.bitrate_bps) /
        static_cast<double>(opt.payload_size * 8);

    if (packets_per_sec <= 0.0) {
        std::cerr << "invalid packets_per_sec\n";
        return;
    }

    const auto interval = std::chrono::nanoseconds(
        static_cast<long long>(1'000'000'000.0 / packets_per_sec));

    const std::uint32_t ts_step =
        static_cast<std::uint32_t>(
            static_cast<double>(opt.clock_rate) / packets_per_sec);

    udp_rtp_sender media;
    media.ssrc = opt.ssrc;
    media.pt = opt.pt;
    media.payload_size = opt.payload_size;
    media.mpegts_payload = opt.mpegts_payload;
    apply_mcast_options(media, opt);

    if (!media.open(opt.dst, opt.port)) {
        return;
    }

    udp_rtp_sender fec_row;
    udp_rtp_sender fec_col;

    if (opt.fec) {
        fec_row.ssrc = opt.fec_row_ssrc;
        fec_row.pt = opt.fec_pt;
        fec_row.payload_size = opt.payload_size;
        fec_row.mpegts_payload = false;
        apply_mcast_options(fec_row, opt);

        fec_col.ssrc = opt.fec_col_ssrc;
        fec_col.pt = opt.fec_pt;
        fec_col.payload_size = opt.payload_size;
        fec_col.mpegts_payload = false;
        apply_mcast_options(fec_col, opt);

        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
            media.close();
            return;
        }

        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
            media.close();
            fec_row.close();
            return;
        }
    }

    std::cerr
        << "RTP media: " << opt.dst << ":" << opt.port
        << " ssrc=" << opt.ssrc
        << " pt=" << static_cast<int>(opt.pt)
        << " bitrate=" << opt.bitrate_bps
        << " payload=" << opt.payload_size
        << " pps=" << packets_per_sec
        << " ts_step=" << ts_step
        << "\n";

    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
        std::cerr
            << "multicast: ttl=" << opt.mcast_ttl
            << " loop=" << opt.mcast_loop;

        if (!opt.mcast_if.empty()) {
            std::cerr << " if=" << opt.mcast_if;
        } else {
            std::cerr << " if=<route-default>";
        }

        std::cerr << "\n";
    }

    print_impairment(opt);
    print_impairment_warnings(opt);

    if (opt.fec) {
        std::cerr
            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
            << " ssrc=" << opt.fec_row_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " L=" << opt.fec_l
            << "\n";

        std::cerr
            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
            << " ssrc=" << opt.fec_col_ssrc
            << " pt=" << static_cast<int>(opt.fec_pt)
            << " D=" << opt.fec_d
            << "\n";
    }

    packet_scheduler scheduler(
        opt,
        [&media](packet value) { media.send_packet(value); },
        jitter_target_protocol::rtp);
    packet_impairer impairment(opt, [&scheduler](packet value) {
        scheduler.submit(std::move(value));
    });

    packet media_packet;

    fec_state fec;
    std::vector<std::uint8_t> fec_packet;

    auto next = clock_type::now();

    while (!g_stop) {
        media.make_packet(media_packet);

        if (opt.fec) {
            xor_payload(fec.row_xor, media_packet);
            xor_payload(fec.col_xor, media_packet);

            ++fec.row_count;
            ++fec.col_count;

            if (fec.row_count >= opt.fec_l) {
                make_fec_payload_packet(fec_row, fec.row_xor, fec_packet);
                fec_row.send_packet(fec_packet);

                ++fec_row.seq;
                fec_row.timestamp += ts_step * opt.fec_l;

                fec.row_xor.clear();
                fec.row_count = 0;
            }

            if (fec.col_count >= opt.fec_d) {
                make_fec_payload_packet(fec_col, fec.col_xor, fec_packet);
                fec_col.send_packet(fec_packet);

                ++fec_col.seq;
                fec_col.timestamp += ts_step * opt.fec_d;

                fec.col_xor.clear();
                fec.col_count = 0;
            }
        }

        scheduler.set_base_time(next);
        impairment.submit(media_packet);

        ++media.seq;
        media.timestamp += ts_step;

        next += interval;
        std::this_thread::sleep_until(next);
    }

    impairment.flush();
    scheduler.stop();
    media.close();

    if (opt.fec) {
        fec_row.close();
        fec_col.close();
    }
}

#ifdef ENABLE_SRT
class srt_impairment_proxy {
public:
    explicit srt_impairment_proxy(const options& opt)
        : jitter_ms_(opt.jitter.max_ms)
        , jitter_target_ms_(opt.jitter.target_ms)
        , target_reorder_(jitter_target_reorders(opt))
        , nominal_interval_ms_(
            1000.0 * static_cast<double>(opt.payload_size) * 8.0 /
            static_cast<double>(opt.bitrate_bps))
        , rng_(opt.seed ? (*opt.seed ^ 0x85ebca6bU) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , impairment_(opt, [this](packet value) {
            schedule(std::move(value));
        }) {}

    ~srt_impairment_proxy() {
        stop();
    }

    bool open(const std::string& dst, std::uint16_t port) {
        downstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (downstream_fd_ < 0) {
            perror("SRT proxy downstream socket");
            return false;
        }

        std::memset(&destination_, 0, sizeof(destination_));
        destination_.sin_family = AF_INET;
        destination_.sin_port = htons(port);
        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
            std::cerr << "invalid SRT destination ip: " << dst << "\n";
            close_fds();
            return false;
        }

        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (upstream_fd_ < 0) {
            perror("SRT proxy upstream socket");
            close_fds();
            return false;
        }

        sockaddr_in listen{};
        listen.sin_family = AF_INET;
        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        listen.sin_port = 0;
        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
            perror("SRT proxy bind");
            close_fds();
            return false;
        }

        socklen_t length = sizeof(listen);
        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
            perror("SRT proxy getsockname");
            close_fds();
            return false;
        }

        local_port_ = ntohs(listen.sin_port);
        return true;
    }

    void start() {
        worker_ = std::thread([this] { run(); });
    }

    void stop() {
        stopping_ = true;
        if (worker_.joinable()) {
            worker_.join();
        }
        close_fds();
    }

    std::uint16_t local_port() const {
        return local_port_;
    }

private:
    static bool is_data_packet(const packet& value) {
        return value.size() >= 16 && (value[0] & 0x80U) == 0;
    }

    void close_fds() {
        if (upstream_fd_ >= 0) {
            ::close(upstream_fd_);
            upstream_fd_ = -1;
        }
        if (downstream_fd_ >= 0) {
            ::close(downstream_fd_);
            downstream_fd_ = -1;
        }
    }

    void send_downstream(const packet& value) {
        const auto sent = ::sendto(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&destination_),
            sizeof(destination_));
        if (sent < 0) {
            perror("SRT proxy send downstream");
        }
    }

    void send_upstream(const packet& value) {
        if (!has_sender_) {
            return;
        }

        const auto sent = ::sendto(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<const sockaddr*>(&sender_),
            sender_length_);
        if (sent < 0) {
            perror("SRT proxy send upstream");
        }
    }

    void schedule(packet value) {
        const auto base = next_base_time_.value_or(clock_type::now());
        next_base_time_ = base + std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double, std::milli>(nominal_interval_ms_));

        auto due = base;
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (target_reorder_ == false && last_due_ && due < *last_due_) {
            due = *last_due_;
        }

        scheduled_.emplace(due, std::move(value));
        last_due_ = due;
    }

    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            jitter_target_protocol::srt, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    void flush_ready() {
        const auto now = clock_type::now();
        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
            send_downstream(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
        }
    }

    void forward_from_upstream() {
        packet value(65536);
        sockaddr_storage source{};
        socklen_t source_length = sizeof(source);
        const auto received = ::recvfrom(
            upstream_fd_,
            value.data(),
            value.size(),
            0,
            reinterpret_cast<sockaddr*>(&source),
            &source_length);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        sender_ = source;
        sender_length_ = source_length;
        has_sender_ = true;

        if (is_data_packet(value)) {
            impairment_.submit(std::move(value));
        } else {
            send_downstream(value);
        }
    }

    void forward_from_downstream() {
        packet value(65536);
        const auto received = ::recvfrom(
            downstream_fd_,
            value.data(),
            value.size(),
            0,
            nullptr,
            nullptr);
        if (received <= 0) {
            return;
        }

        value.resize(static_cast<std::size_t>(received));
        send_upstream(value);
    }

    void run() {
        while (!stopping_) {
            pollfd fds[2]{};
            fds[0].fd = upstream_fd_;
            fds[0].events = POLLIN;
            fds[1].fd = downstream_fd_;
            fds[1].events = POLLIN;
        if (is_ipv4_multicast_addr(addr.sin_addr)) {
            if (!configure_multicast()) {
                return false;
            }
        }

        return true;
    }

    bool configure_multicast() {
        const unsigned char ttl = static_cast<unsigned char>(mcast_ttl);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
            perror("setsockopt IP_MULTICAST_TTL");
            return false;
        }

        const unsigned char loop = static_cast<unsigned char>(mcast_loop != 0);
        if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_LOOP, &loop, sizeof(loop)) < 0) {
            perror("setsockopt IP_MULTICAST_LOOP");
            return false;
        }

        if (!mcast_if.empty()) {
            in_addr local_if{};
            if (::inet_pton(AF_INET, mcast_if.c_str(), &local_if) != 1) {
                std::cerr << "invalid --mcast-if: " << mcast_if << "\n";
                return false;
            }

            if (::setsockopt(fd, IPPROTO_IP, IP_MULTICAST_IF, &local_if, sizeof(local_if)) < 0) {
                perror("setsockopt IP_MULTICAST_IF");
                return false;
            }
        }

        return true;
    }

    void close() {
        if (fd >= 0) {
            ::close(fd);
            fd = -1;
        }
    }

    void make_packet(std::vector<std::uint8_t>& out) {
        out.resize(12 + payload_size);

        out[0] = 0x80;          // V=2, P=0, X=0, CC=0
        out[1] = pt & 0x7f;     // M=0, PT

        put_u16_be(&out[2], seq);
        put_u32_be(&out[4], timestamp);
        put_u32_be(&out[8], ssrc);

        auto* payload = out.data() + 12;

        if (mpegts_payload) {
            // MPEG-TS風ダミーpayload。
            // 188 byteごとにsync byte 0x47を置くだけなので、再生可能なTSではない。
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = (i % 188 == 0)
                    ? 0x47
                    : static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        } else {
            for (std::size_t i = 0; i < payload_size; ++i) {
                payload[i] = static_cast<std::uint8_t>((seq + i) & 0xff);
            }
        }
    }

    void send_packet(const std::vector<std::uint8_t>& packet) {
        const auto n = ::sendto(
            fd,
            packet.data(),
            packet.size(),
            0,
            reinterpret_cast<const sockaddr*>(&addr),
            sizeof(addr));

        if (n < 0) {
            perror("sendto");
        }
    }
};

struct fec_state {
    std::vector<std::uint8_t> row_xor;
    std::vector<std::uint8_t> col_xor;

    std::uint32_t row_count{0};
    std::uint32_t col_count{0};
};

void xor_payload(std::vector<std::uint8_t>& acc, const std::vector<std::uint8_t>& rtp_packet) {
    constexpr std::size_t header_size = 12;

    if (rtp_packet.size() < header_size) {
        return;
    }

    const std::size_t payload_len = rtp_packet.size() - header_size;

    if (acc.empty()) {
        acc.assign(payload_len, 0);
    }

    const auto n = std::min(acc.size(), payload_len);
    for (std::size_t i = 0; i < n; ++i) {
        acc[i] ^= rtp_packet[header_size + i];
    }
}

void make_fec_payload_packet(
    udp_rtp_sender& fec_sender,
    const std::vector<std::uint8_t>& xor_payload_data,
    std::vector<std::uint8_t>& out)
{
    fec_sender.payload_size = xor_payload_data.size();
    fec_sender.make_packet(out);

    if (!xor_payload_data.empty()) {
        std::memcpy(out.data() + 12, xor_payload_data.data(), xor_payload_data.size());
    }
}

void apply_mcast_options(udp_rtp_sender& s, const options& opt) {
    s.mcast_if = opt.mcast_if;
    s.mcast_ttl = opt.mcast_ttl;
    s.mcast_loop = opt.mcast_loop;
}

using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class occurrence_selector {
public:
    occurrence_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool hit(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const bool selected = packets_in_period_ >
                settings_.periodic.packet_period - settings_.periodic.count;
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            selected_in_window_ = 0;
            time_window_active_ = true;
        }
        if (!time_window_active_ ||
            selected_in_window_ >= settings_.periodic.count) {
            return false;
        }
        ++selected_in_window_;
        return true;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t selected_in_window_{0};
    bool time_window_active_{false};
};

class reorder_selector {
public:
    reorder_selector(const counted_impairment& settings, std::uint32_t seed)
        : settings_(settings)
        , rng_(seed) {}

    bool starts_pair(clock_type::time_point now) {
        if (settings_.mode == occurrence_mode::none) {
            return false;
        }
        if (settings_.mode == occurrence_mode::rate) {
            return settings_.rate > 0.0 && distribution_(rng_) < settings_.rate;
        }

        if (settings_.periodic.basis == period_basis::packets) {
            ++packets_in_period_;
            const std::uint64_t pair_packets = settings_.periodic.count * 2;
            const std::uint64_t first_pair_packet =
                settings_.periodic.packet_period - pair_packets + 1;
            const bool selected = packets_in_period_ >= first_pair_packet &&
                ((packets_in_period_ - first_pair_packet) % 2 == 0);
            if (packets_in_period_ == settings_.periodic.packet_period) {
                packets_in_period_ = 0;
            }
            return selected;
        }

        if (!time_started_) {
            time_started_ = true;
            next_boundary_ = now + settings_.periodic.time_period;
            return false;
        }
        while (now >= next_boundary_) {
            next_boundary_ += settings_.periodic.time_period;
            packets_in_window_ = 0;
            time_window_active_ = true;
        }
        if (!time_window_active_) {
            return false;
        }
        const std::uint64_t pair_packets = settings_.periodic.count * 2;
        const bool selected = packets_in_window_ < pair_packets &&
            (packets_in_window_ % 2 == 0);
        if (packets_in_window_ < pair_packets) {
            ++packets_in_window_;
        }
        return selected;
    }

private:
    counted_impairment settings_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::uint64_t packets_in_period_{0};
    bool time_started_{false};
    clock_type::time_point next_boundary_{};
    std::uint64_t packets_in_window_{0};
    bool time_window_active_{false};
};

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_(opt.loss, impairment_seed(opt, 0x243f6a88U))
        , duplicate_(opt.duplicate, impairment_seed(opt, 0x85a308d3U))
        , reorder_(opt.reorder, impairment_seed(opt, 0x13198a2eU))
        , submit_(std::move(submit)) {}

    void submit(packet value) {
        const auto now = clock_type::now();
        const bool drop = loss_.hit(now);
        const bool duplicate = duplicate_.hit(now);
        const bool reorder = reorder_.starts_pair(now);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = delayed_packet{std::move(value), duplicate};
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_with_duplicate(std::move(delayed_->value), delayed_->duplicate);
            delayed_.reset();
        }
    }

private:
    static std::uint32_t impairment_seed(const options& opt, std::uint32_t salt) {
        return opt.seed ? (*opt.seed ^ salt) : std::random_device{}();
    }

    struct delayed_packet {
        packet value;
        bool duplicate{false};
    };

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    occurrence_selector loss_;
    occurrence_selector duplicate_;
    reorder_selector reorder_;
    packet_submitter submit_;
    std::optional<delayed_packet> delayed_;
};

enum class jitter_target_protocol {
-rwxr-xr-x. 1 root root  41248 May  6 15:20 be/build/streamgen
-rwxr-xr-x. 1 root root 114496 Sep  9 15:37 be/tools/streamgen

