 276	bool parse_impairment(const std::string& value, options& opt, std::string& error) {
 277	    std::vector<std::string> items;
 278	    std::size_t begin = 0;
 279	    while (begin <= value.size()) {
 280	        const std::size_t end = value.find(',', begin);
 281	        items.push_back(value.substr(begin, end == std::string::npos ? end : end - begin));
 282	        if (end == std::string::npos) break;
 283	        begin = end + 1;
 284	    }
 285	
 286	    if (items.empty() || items.front().empty()) {
 287	        error = "--impair requires a type";
 288	        return false;
 289	    }
 290	
 291	    std::map<std::string, std::string> fields;
 292	    for (std::size_t i = 1; i < items.size(); ++i) {
 293	        const std::size_t equals = items[i].find('=');
 294	        if (equals == std::string::npos || equals == 0 || equals + 1 == items[i].size()) {
 295	            error = "--impair fields must be key=value";
 296	            return false;
 297	        }
 298	        const auto [it, inserted] = fields.emplace(items[i].substr(0, equals), items[i].substr(equals + 1));
 299	        if (!inserted) {
 300	            error = "--impair contains a repeated field: " + it->first;
 301	            return false;
 302	        }
 303	    }
 304	
 305	    const auto field = [&fields](const char* name) -> const std::string* {
 306	        const auto it = fields.find(name);
 307	        return it == fields.end() ? nullptr : &it->second;
 308	    };
 309	    const auto only_fields = [&fields, &error](std::initializer_list<const char*> allowed) {
 310	        for (const auto& [name, ignored] : fields) {
 311	            (void)ignored;
 312	            if (std::find(allowed.begin(), allowed.end(), name) == allowed.end()) {
 313	                error = "--impair field is not valid for this type/mode: " + name;
 314	                return false;
 315	            }
 316	        }
 317	        return true;
 318	    };
 319	
 320	    const std::string& type = items.front();
 321	    if (type == "loss" || type == "duplicate" || type == "reorder") {
 322	        const std::string* mode = field("mode");
 323	        if (!mode) {
 324	            error = "--impair " + type + " requires mode=rate or mode=periodic";
 325	            return false;
 326	        }
 327	
 328	        counted_impairment parsed;
 329	        if (*mode == "rate") {
 330	            const std::string* rate = field("rate");
 331	            if (!rate || !only_fields({"mode", "rate"})) {
 332	                if (!rate && error.empty()) error = "--impair " + type + ",mode=rate requires rate";
 333	                return false;
 334	            }
 335	            parsed.mode = occurrence_mode::rate;
 336	            parsed.rate = parse_finite_double(*rate, "rate");
 337	        } else if (*mode == "periodic") {
 338	            const std::string* period = field("period");
 339	            const std::string* count = field("count");
 340	            if (!period || !count || !only_fields({"mode", "period", "count"})) {
 341	                if ((!period || !count) && error.empty()) error = "--impair " + type + ",mode=periodic requires period and count";
 342	                return false;
 343	            }
 344	            parsed.mode = occurrence_mode::periodic;
 345	            if (!parse_period(*period, parsed.periodic, error)) return false;
 346	            parsed.periodic.count = parse_positive_u64(*count, "count");
 347	        } else {
 348	            error = "--impair " + type + " mode must be rate or periodic";
 349	            return false;
 350	        }
 351	
 352	        counted_impairment* target = type == "loss" ? &opt.loss :
 353	            (type == "duplicate" ? &opt.duplicate : &opt.reorder);
 354	        return set_counted_impairment(*target, std::move(parsed), type.c_str(), error);
 355	    }
 356	
 357	    if (type == "jitter") {
 358	        const std::string* mode = field("mode");
 359	        if (!mode) {
 360	            error = "--impair jitter requires mode=random or mode=target";
 361	            return false;
 362	        }
 363	
 364	        jitter_impairment parsed;
 365	        if (*mode == "random") {
 366	            const std::string* max_ms = field("max-ms");
 367	            if (!max_ms || !only_fields({"mode", "max-ms"})) {
 368	                if (!max_ms && error.empty()) error = "--impair jitter,mode=random requires max-ms";
 369	                return false;
 370	            }
 371	            parsed.mode = jitter_mode::random;
 372	            parsed.max_ms = parse_finite_double(*max_ms, "max-ms");
 373	        } else if (*mode == "target") {
 374	            const std::string* target_ms = field("target-ms");
 375	            const std::string* target_mode = field("target-mode");
 376	            if (!target_ms || !only_fields({"mode", "target-ms", "target-mode"})) {
 377	                if (!target_ms && error.empty()) error = "--impair jitter,mode=target requires target-ms";
 378	                return false;
 379	            }
 380	            parsed.mode = jitter_mode::target;
 381	            parsed.target_ms = parse_finite_double(*target_ms, "target-ms");
 382	            if (target_mode && *target_mode == "reorder") {
 383	                parsed.target_mode = jitter_target_mode::reorder;
 384	            } else if (target_mode && *target_mode != "ordered") {
 385	                error = "jitter target-mode must be ordered or reorder";
 386	                return false;
 387	            }
 388	        } else {
 389	            error = "--impair jitter mode must be random or target";
 390	            return false;
 391	        }
 392	        return set_jitter_impairment(opt.jitter, std::move(parsed), error);
 393	    }
 394	
 395	    error = "--impair type must be loss, duplicate, reorder, or jitter";
 396	    return false;
 397	}
