1109	class packet_scheduler {
1110	public:
1111	    packet_scheduler(
1112	        const options& opt,
1113	        packet_submitter send,
1114	        jitter_target_protocol target_protocol)
1115	        : jitter_ms_(opt.jitter.max_ms)
1116	        , jitter_target_ms_(opt.jitter.target_ms)
1117	        , target_reorder_(jitter_target_reorders(opt))
1118	        , target_protocol_(target_protocol)
1119	        , send_(std::move(send))
1120	        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
1121	        , jitter_distribution_(0.0, jitter_ms_)
1122	        , worker_([this] { run(); }) {}
1123	
1124	    ~packet_scheduler() {
1125	        stop();
1126	    }
1127	
1128	    packet_scheduler(const packet_scheduler&) = delete;
1129	    packet_scheduler& operator=(const packet_scheduler&) = delete;
1130	
1131	    void set_base_time(clock_type::time_point value) {
1132	        base_time_ = value;
1133	    }
1134	
1135	    void submit(packet value) {
1136	        auto due = base_time_.value_or(clock_type::now());
1137	        if (jitter_target_ms_ > 0.0) {
1138	            due += std::chrono::duration_cast<clock_type::duration>(
1139	                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
1140	        } else if (jitter_ms_ > 0.0) {
1141	            due += std::chrono::duration_cast<clock_type::duration>(
1142	                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
1143	        }
1144	
1145	        if (target_reorder_ == false && last_due_ && due < *last_due_) {
1146	            due = *last_due_;
1147	        }
1148	        last_due_ = due;
1149	
1150	        {
1151	            std::lock_guard<std::mutex> lock(mutex_);
1152	            if (stopping_) {
1153	                return;
1154	            }
1155	            scheduled_.emplace(std::make_pair(due, next_sequence_++), std::move(value));
1156	        }
1157	        wake_.notify_one();
1158	    }
1159	
1160	    void stop() {
1161	        {
1162	            std::lock_guard<std::mutex> lock(mutex_);
1163	            if (stopping_) {
1164	                return;
1165	            }
1166	            stopping_ = true;
1167	            scheduled_.clear();
1168	        }
1169	        wake_.notify_one();
1170	        if (worker_.joinable()) {
1171	            worker_.join();
1172	        }
1173	    }
1174	
1175	private:
1176	    using schedule_key = std::pair<clock_type::time_point, std::uint64_t>;
1177	
1178	    void run() {
1179	        std::unique_lock<std::mutex> lock(mutex_);
1180	        while (stopping_ == false) {
1181	            if (scheduled_.empty()) {
1182	                wake_.wait(lock);
1183	                continue;
1184	            }
1185	
1186	            const auto due = scheduled_.begin()->first.first;
1187	            if (clock_type::now() < due) {
1188	                wake_.wait_until(lock, due);
1189	                continue;
1190	            }
1360	        opt.clock_rate > 0 && opt.jitter.target_ms < 1000.0 / opt.clock_rate) {
1361	        std::cerr
1362	            << "warning: jitter target-ms " << opt.jitter.target_ms
1363	            << " is below the RTP timestamp resolution " << (1000.0 / opt.clock_rate)
1364	            << " ms; the target cannot be represented exactly.\n";
1365	    }
1366	
1367	    if (opt.proto == proto_type::srt && jitter_impairment_enabled(opt.jitter) &&
1368	        opt.jitter.mode == jitter_mode::target &&
1369	        opt.jitter.target_ms < 10.0) {
1370	        std::cerr
1371	            << "warning: SRT impairment scheduling polls at up to 10 ms; small jitter targets can be dominated by scheduler latency.\n";
1372	    }
1373	
1374	    if (opt.proto == proto_type::srt && has_counted_errors) {
1375	        std::cerr
1376	            << "warning: SRT retransmission and receiver buffering can change observed loss, reorder, and jitter from the UDP proxy settings.\n";
1377	    }
1378	}
