1380	void run_rtp(const options& opt) {
1381	    const double packets_per_sec =
1382	        static_cast<double>(opt.bitrate_bps) /
1383	        static_cast<double>(opt.payload_size * 8);
1384	
1385	    if (packets_per_sec <= 0.0) {
1386	        std::cerr << "invalid packets_per_sec\n";
1387	        return;
1388	    }
1389	
1390	    const auto interval = std::chrono::nanoseconds(
1391	        static_cast<long long>(1'000'000'000.0 / packets_per_sec));
1392	
1393	    const std::uint32_t ts_step =
1394	        static_cast<std::uint32_t>(
1395	            static_cast<double>(opt.clock_rate) / packets_per_sec);
1396	
1397	    udp_rtp_sender media;
1398	    media.ssrc = opt.ssrc;
1399	    media.pt = opt.pt;
1400	    media.payload_size = opt.payload_size;
