1402	    apply_mcast_options(media, opt);
1403	
1404	    if (!media.open(opt.dst, opt.port)) {
1405	        return;
1406	    }
1407	
1408	    udp_rtp_sender fec_row;
1409	    udp_rtp_sender fec_col;
1410	
1411	    if (opt.fec) {
1412	        fec_row.ssrc = opt.fec_row_ssrc;
1413	        fec_row.pt = opt.fec_pt;
1414	        fec_row.payload_size = opt.payload_size;
1415	        fec_row.mpegts_payload = false;
1416	        apply_mcast_options(fec_row, opt);
1417	
1418	        fec_col.ssrc = opt.fec_col_ssrc;
1419	        fec_col.pt = opt.fec_pt;
1420	        fec_col.payload_size = opt.payload_size;
1421	        fec_col.mpegts_payload = false;
1422	        apply_mcast_options(fec_col, opt);
1423	
1424	        if (!fec_row.open(opt.dst, opt.fec_row_port)) {
1425	            media.close();
1426	            return;
1427	        }
1428	
1429	        if (!fec_col.open(opt.dst, opt.fec_col_port)) {
1430	            media.close();
1431	            fec_row.close();
1432	            return;
1433	        }
1434	    }
1435	
1436	    std::cerr
1437	        << "RTP media: " << opt.dst << ":" << opt.port
1438	        << " ssrc=" << opt.ssrc
1439	        << " pt=" << static_cast<int>(opt.pt)
1440	        << " bitrate=" << opt.bitrate_bps
1441	        << " payload=" << opt.payload_size
1442	        << " pps=" << packets_per_sec
1443	        << " ts_step=" << ts_step
1444	        << "\n";
1445	
1446	    if (is_ipv4_multicast_addr(media.addr.sin_addr)) {
1447	        std::cerr
1448	            << "multicast: ttl=" << opt.mcast_ttl
1449	            << " loop=" << opt.mcast_loop;
1450	
1451	        if (!opt.mcast_if.empty()) {
1452	            std::cerr << " if=" << opt.mcast_if;
1453	        } else {
1454	            std::cerr << " if=<route-default>";
1455	        }
1456	
1457	        std::cerr << "\n";
1458	    }
1459	
1460	    print_impairment(opt);
1461	    print_impairment_warnings(opt);
1462	
1463	    if (opt.fec) {
1464	        std::cerr
1465	            << "RTP FEC row: " << opt.dst << ":" << opt.fec_row_port
1466	            << " ssrc=" << opt.fec_row_ssrc
1467	            << " pt=" << static_cast<int>(opt.fec_pt)
1468	            << " L=" << opt.fec_l
1469	            << "\n";
1470	
1471	        std::cerr
1472	            << "RTP FEC col: " << opt.dst << ":" << opt.fec_col_port
1473	            << " ssrc=" << opt.fec_col_ssrc
1474	            << " pt=" << static_cast<int>(opt.fec_pt)
1475	            << " D=" << opt.fec_d
1476	            << "\n";
1477	    }
1478	
1479	    packet_scheduler scheduler(
1480	        opt,
1481	        [&media](packet value) { media.send_packet(value); },
1482	        jitter_target_protocol::rtp);
1483	    packet_impairer impairment(opt, [&scheduler](packet value) {
1484	        scheduler.submit(std::move(value));
