309	bool parse_impairment(const std::string& value, options& opt, std::string& error) {
310	    std::vector<std::string> items;
311	    std::size_t begin = 0;
312	    while (begin <= value.size()) {
313	        const std::size_t end = value.find(',', begin);
314	        items.push_back(value.substr(begin, end == std::string::npos ? end : end - begin));
315	        if (end == std::string::npos) break;
316	        begin = end + 1;
317	    }
318	
319	    if (items.empty() || items.front().empty()) {
320	        error = "--impair requires a type";
321	        return false;
322	    }
323	
324	    std::map<std::string, std::string> fields;
325	    for (std::size_t i = 1; i < items.size(); ++i) {
326	        const std::size_t equals = items[i].find('=');
327	        if (equals == std::string::npos || equals == 0 || equals + 1 == items[i].size()) {
328	            error = "--impair fields must be key=value";
329	            return false;
330	        }
331	        const auto [it, inserted] = fields.emplace(items[i].substr(0, equals), items[i].substr(equals + 1));
332	        if (!inserted) {
333	            error = "--impair contains a repeated field: " + it->first;
334	            return false;
335	        }
336	    }
337	
338	    const auto field = [&fields](const char* name) -> const std::string* {
339	        const auto it = fields.find(name);
340	        return it == fields.end() ? nullptr : &it->second;
341	    };
342	    const auto only_fields = [&fields, &error](std::initializer_list<const char*> allowed) {
343	        for (const auto& [name, ignored] : fields) {
344	            (void)ignored;
345	            if (std::find(allowed.begin(), allowed.end(), name) == allowed.end()) {
346	                error = "--impair field is not valid for this type/mode: " + name;
347	                return false;
348	            }
349	        }
350	        return true;
351	    };
352	
353	    const std::string& type = items.front();
354	    if (type == "loss" || type == "duplicate" || type == "reorder") {
355	        const std::string* mode = field("mode");
356	        if (!mode) {
357	            error = "--impair " + type + " requires mode=rate or mode=periodic";
358	            return false;
359	        }
360	
361	        counted_impairment parsed;
362	        if (*mode == "rate") {
363	            const std::string* rate = field("rate");
364	            if (!rate || !only_fields({"mode", "rate"})) {
365	                if (!rate && error.empty()) error = "--impair " + type + ",mode=rate requires rate";
366	                return false;
367	            }
368	            parsed.mode = occurrence_mode::rate;
369	            parsed.rate = parse_finite_double(*rate, "rate");
370	        } else if (*mode == "periodic") {
371	            const std::string* period = field("period");
372	            const std::string* count = field("count");
373	            if (!period || !count || !only_fields({"mode", "period", "count"})) {
374	                if ((!period || !count) && error.empty()) error = "--impair " + type + ",mode=periodic requires period and count";
375	                return false;
376	            }
377	            parsed.mode = occurrence_mode::periodic;
378	            if (!parse_period(*period, parsed.periodic, error)) return false;
379	            parsed.periodic.count = parse_positive_u64(*count, "count");
380	        } else {
381	            error = "--impair " + type + " mode must be rate or periodic";
382	            return false;
383	        }
384	
385	        counted_impairment* target = type == "loss" ? &opt.loss :
386	            (type == "duplicate" ? &opt.duplicate : &opt.reorder);
387	        return set_counted_impairment(*target, std::move(parsed), type.c_str(), error);
388	    }
389	
390	    if (type == "jitter") {
391	        const std::string* mode = field("mode");
392	        if (!mode) {
393	            error = "--impair jitter requires mode=random or mode=target";
394	            return false;
395	        }
396	
397	        jitter_impairment parsed;
398	        if (*mode == "random") {
399	            const std::string* max_ms = field("max-ms");
400	            if (!max_ms || !only_fields({"mode", "max-ms"})) {
401	                if (!max_ms && error.empty()) error = "--impair jitter,mode=random requires max-ms";
402	                return false;
403	            }
404	            parsed.mode = jitter_mode::random;
405	            parsed.max_ms = parse_finite_double(*max_ms, "max-ms");
406	        } else if (*mode == "target") {
407	            const std::string* target_ms = field("target-ms");
408	            const std::string* target_mode = field("target-mode");
409	            if (!target_ms || !only_fields({"mode", "target-ms", "target-mode"})) {
410	                if (!target_ms && error.empty()) error = "--impair jitter,mode=target requires target-ms";
411	                return false;
412	            }
413	            parsed.mode = jitter_mode::target;
414	            parsed.target_ms = parse_finite_double(*target_ms, "target-ms");
415	            if (target_mode && *target_mode == "reorder") {
416	                parsed.target_mode = jitter_target_mode::reorder;
417	            } else if (target_mode && *target_mode != "ordered") {
418	                error = "jitter target-mode must be ordered or reorder";
419	                return false;
420	            }
421	        } else {
422	            error = "--impair jitter mode must be random or target";
423	            return false;
424	        }
425	        return set_jitter_impairment(opt.jitter, std::move(parsed), error);
426	    }
427	
428	    error = "--impair type must be loss, duplicate, reorder, or jitter";
429	    return false;
430	}
