1302i
std::uint32_t modulation_seed(const options& opt, const std::optional<modulation>& setting, std::uint32_t salt) {
    if (setting && setting->seed) return *setting->seed ^ salt;
    return opt.seed ? (*opt.seed ^ salt) : std::random_device{}();
}

class modulation_driver {
public:
    modulation_driver(std::optional<modulation> setting, std::uint32_t seed)
        : setting_(std::move(setting)), seed_(seed) {}

    bool enabled() const { return setting_.has_value(); }

    double value_at(clock_type::time_point now) {
        if (!setting_) return 0.0;
        if (!started_) started_ = now;
        const auto& setting = *setting_;
        const double period = std::chrono::duration<double>(setting.period).count();
        const double phase = std::chrono::duration<double>(setting.phase).count();
        double position = std::fmod(std::chrono::duration<double>(now - *started_).count() + phase, period);
        if (position < 0.0) position += period;
        const double fraction = position / period;
        double normalized = 0.0;
        switch (setting.curve) {
        case modulation_curve::sine:
            normalized = 0.5 - 0.5 * std::cos(2.0 * std::acos(-1.0) * fraction);
            break;
        case modulation_curve::triangle:
            normalized = fraction < 0.5 ? fraction * 2.0 : (1.0 - fraction) * 2.0;
            break;
        case modulation_curve::step:
            normalized = fraction < 0.5 ? 0.0 : 1.0;
            break;
        case modulation_curve::random: {
            const auto update = std::chrono::duration<double>(setting.update).count();
            const std::uint64_t slot = static_cast<std::uint64_t>(std::floor(position / update));
            std::uint32_t value = seed_ ^ static_cast<std::uint32_t>(slot) ^ static_cast<std::uint32_t>(slot >> 32);
            value ^= value >> 16;
            value *= 0x7feb352dU;
            value ^= value >> 15;
            value *= 0x846ca68bU;
            value ^= value >> 16;
            normalized = static_cast<double>(value) / static_cast<double>(UINT32_MAX);
            break;
        }
        }
        return setting.min_value + (setting.max_value - setting.min_value) * normalized;
    }

private:
    std::optional<modulation> setting_;
    std::uint32_t seed_{0};
    std::optional<clock_type::time_point> started_;
};

