struct counted_impairment {
    occurrence_mode mode{occurrence_mode::none};
    double rate{0.0};
    periodic_occurrence periodic{};
};

enum class jitter_mode {
    none,
    random,
    target,
};

struct jitter_impairment {
    jitter_mode mode{jitter_mode::none};
    double max_ms{0.0};
    double target_ms{0.0};
    jitter_target_mode target_mode{jitter_target_mode::ordered};
};

enum class modulation_metric {
    bitrate,
    jitter,
};

enum class modulation_curve {
    sine,
    triangle,
    step,
    random,
};

struct modulation {
    modulation_metric metric{modulation_metric::bitrate};
    modulation_curve curve{modulation_curve::sine};
    double min_value{0.0};
    double max_value{0.0};
    clock_type::duration period{};
    clock_type::duration phase{};
    clock_type::duration update{};
    std::optional<std::uint32_t> seed{};
};

struct options {
    proto_type proto{proto_type::rtp};

    std::string dst{"127.0.0.1"};
    std::uint16_t port{5000};
    std::uint32_t bitrate_bps{1'000'000};
    std::size_t payload_size{188 * 7};

    std::uint32_t ssrc{1001};
    std::uint8_t pt{33};
    std::uint32_t clock_rate{90000};
    std::string srt_streamid{};

    bool mpegts_payload{true};

    counted_impairment loss{};
    counted_impairment duplicate{};
    counted_impairment reorder{};
    jitter_impairment jitter{};
    std::optional<modulation> bitrate_modulation{};
    std::optional<modulation> jitter_modulation{};
    std::optional<std::uint32_t> seed{};
    bool uses_legacy_impairment_options{false};

    bool fec{false};
    std::uint16_t fec_row_port{5002};
    std::uint16_t fec_col_port{5004};
    std::uint8_t fec_pt{96};
    std::uint32_t fec_row_ssrc{2001};
    std::uint32_t fec_col_ssrc{2002};

    // 簡易FEC用。厳密なRFC/SMPTE準拠ではない。
    std::uint32_t fec_l{4};
    std::uint32_t fec_d{4};
    bool uses_fec_options{false};

    // IPv4 multicast送信用オプション。
    // --dst が 224.0.0.0/4 の場合に適用される。
    std::string mcast_if{};
    int mcast_ttl{1};
    int mcast_loop{1};
    bool uses_mcast_options{false};
};

const char* jitter_target_mode_name(jitter_target_mode mode) {
    return mode == jitter_target_mode::ordered ? "ordered" : "reorder";
}

double max_bitrate_bps(const options& opt) {
    return opt.bitrate_modulation ? opt.bitrate_modulation->max_value : static_cast<double>(opt.bitrate_bps);
}

double nominal_packet_interval_ms(const options& opt) {
    return 1000.0 * static_cast<double>(opt.payload_size) * 8.0 /
        static_cast<double>(opt.bitrate_bps);
}

double ordered_jitter_target_limit_ms(const options& opt) {
    const double interval_ms = 1000.0 * static_cast<double>(opt.payload_size) * 8.0 / max_bitrate_bps(opt);
    return opt.proto == proto_type::rtp ? interval_ms : interval_ms * 2.0;
}

bool has_jitter_target(const options& opt) {
    return (opt.jitter.mode == jitter_mode::target && opt.jitter.target_ms > 0.0) ||
           opt.jitter_modulation.has_value();
}

bool jitter_target_reorders(const options& opt) {
    return has_jitter_target(opt) && opt.jitter.target_mode == jitter_target_mode::reorder;
}

std::uint16_t parse_u16(const char* s, const char* name) {
    const auto v = std::stoul(s);
    if (v > 65535) {
    }

    error = "--impair type must be loss, duplicate, reorder, or jitter";
    return false;
}

bool parse_modulation_duration(const std::string& value, clock_type::duration& out, std::string& error) {
    periodic_occurrence parsed;
    if (!parse_period(value, parsed, error)) return false;
    if (parsed.basis != period_basis::time) {
        error = "--modulate period, phase, and update must use ms or s units";
        return false;
    }
    out = parsed.time_period;
    return true;
}

double parse_modulation_value(const std::string& value, modulation_metric metric) {
    if (metric == modulation_metric::jitter) {
        const std::string number = value.ends_with("ms") ? value.substr(0, value.size() - 2) : value;
        return parse_finite_double(number, "jitter value");
    }

    double multiplier = 1.0;
    std::string number = value;
    if (!value.empty()) {
        const char suffix = value.back();
        if (suffix == 'k' || suffix == 'K') multiplier = 1'000.0;
        else if (suffix == 'm' || suffix == 'M') multiplier = 1'000'000.0;
        else if (suffix == 'g' || suffix == 'G') multiplier = 1'000'000'000.0;
        if (multiplier != 1.0) number.pop_back();
    }
    return parse_finite_double(number, "bitrate value") * multiplier;
}

bool parse_modulation(const std::string& value, options& opt, std::string& error) {
    std::vector<std::string> items;
    std::size_t begin = 0;
    while (begin <= value.size()) {
        const std::size_t end = value.find(',', begin);
        items.push_back(value.substr(begin, end == std::string::npos ? end : end - begin));
        if (end == std::string::npos) break;
        begin = end + 1;
    }
    if (items.empty() || items.front().empty()) {
        error = "--modulate requires bitrate or jitter";
        return false;
    }

    modulation parsed;
    if (items.front() == "bitrate") parsed.metric = modulation_metric::bitrate;
    else if (items.front() == "jitter") parsed.metric = modulation_metric::jitter;
    else {
        error = "--modulate metric must be bitrate or jitter";
        return false;
    }

    std::map<std::string, std::string> fields;
    for (std::size_t i = 1; i < items.size(); ++i) {
        const std::size_t equals = items[i].find('=');
        if (equals == std::string::npos || equals == 0 || equals + 1 == items[i].size()) {
            error = "--modulate fields must be key=value";
            return false;
        }
        const auto [it, inserted] = fields.emplace(items[i].substr(0, equals), items[i].substr(equals + 1));
        if (!inserted) {
            error = "--modulate contains a repeated field: " + it->first;
            return false;
        }
    }
    const auto field = [&fields](const char* name) -> const std::string* {
        const auto it = fields.find(name);
        return it == fields.end() ? nullptr : &it->second;
    };
    const auto only_fields = [&fields, &error](std::initializer_list<const char*> allowed) {
        for (const auto& [name, ignored] : fields) {
            (void)ignored;
            if (std::find(allowed.begin(), allowed.end(), name) == allowed.end()) {
                error = "--modulate field is not valid for this curve: " + name;
                return false;
            }
        }
        return true;
    };

    const std::string* curve = field("curve");
    const std::string* min = field("min");
    const std::string* max = field("max");
    const std::string* period = field("period");
    if (!curve || !min || !max || !period) {
        error = "--modulate requires curve, min, max, and period";
        return false;
    }
    if (*curve == "sine") parsed.curve = modulation_curve::sine;
    else if (*curve == "triangle") parsed.curve = modulation_curve::triangle;
    else if (*curve == "step") parsed.curve = modulation_curve::step;
    else if (*curve == "random") parsed.curve = modulation_curve::random;
    else {
        error = "--modulate curve must be sine, triangle, step, or random";
        return false;
    }
    if (!only_fields(parsed.curve == modulation_curve::random
            ? std::initializer_list<const char*>{"curve", "min", "max", "period", "phase", "update", "seed"}
            : std::initializer_list<const char*>{"curve", "min", "max", "period", "phase"})) return false;

    parsed.min_value = parse_modulation_value(*min, parsed.metric);
    parsed.max_value = parse_modulation_value(*max, parsed.metric);
    if (!std::isfinite(parsed.min_value) || !std::isfinite(parsed.max_value) || parsed.min_value > parsed.max_value) {
        error = "--modulate requires finite min <= max";
        return false;
    }
    if (parsed.metric == modulation_metric::bitrate && (parsed.min_value <= 0.0 || parsed.max_value > 0xffffffffULL)) {
        error = "--modulate bitrate range must be greater than zero and at most 4294967295 bps";
        return false;
    }
    if (parsed.metric == modulation_metric::jitter && (parsed.min_value < 0.0 || parsed.max_value > 60000.0)) {
        error = "--modulate jitter range must be in 0..60000 ms";
        return false;
    }
    if (!parse_modulation_duration(*period, parsed.period, error)) return false;
    if (const auto* phase = field("phase")) {
        if (!parse_modulation_duration(*phase, parsed.phase, error)) return false;
        parsed.phase %= parsed.period;
    }
    if (parsed.curve == modulation_curve::random) {
        parsed.update = std::min(parsed.period, std::chrono::duration_cast<clock_type::duration>(std::chrono::seconds(1)));
        if (const auto* update = field("update")) {
            if (!parse_modulation_duration(*update, parsed.update, error)) return false;
        }
        if (parsed.update > parsed.period) {
            error = "--modulate random update must not exceed period";
            return false;
        }
        if (const auto* seed = field("seed")) parsed.seed = parse_u32(seed->c_str(), "modulate seed");
    }

    std::optional<modulation>& target = parsed.metric == modulation_metric::bitrate
        ? opt.bitrate_modulation : opt.jitter_modulation;
    if (target) {
        error = std::string("multiple --modulate settings for ") + (parsed.metric == modulation_metric::bitrate ? "bitrate" : "jitter");
        return false;
    }
    if (parsed.metric == modulation_metric::jitter && opt.jitter.mode != jitter_mode::none) {
        error = "--modulate jitter conflicts with --impair jitter";
        return false;
    }
    target = std::move(parsed);
    return true;
}

void usage(const char* argv0) {
    std::cerr
        << "Usage:\n"
        << "  " << argv0 << " --proto rtp --dst 127.0.0.1 --port 5000 --ssrc 1001 --pt 33 --bitrate 1000000\n"
        << "  " << argv0 << " --proto rtp --dst 239.1.1.1 --port 5000 --ssrc 1001 --bitrate 1000000 --mcast-if 192.168.1.10 --mcast-ttl 16\n"
        << "  " << argv0 << " --proto rtp --port 5000 --bitrate 1000000 --fec --fec-row-port 5002 --fec-col-port 5004\n"
        << "  " << argv0 << " --proto srt --dst 127.0.0.1 --port 9000 --bitrate 1000000 --srt-streamid test/srt-9000\n"
        << "\nOptions:\n"
        << "  --proto rtp|srt\n"
        << "  --dst <ip>\n"
        << "  --port <port>\n"
    jitter_target_protocol target_protocol_{jitter_target_protocol::rtp};
    packet_submitter send_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    bool target_high_phase_{false};
    std::optional<clock_type::time_point> base_time_;
    std::optional<clock_type::time_point> last_due_;
    std::mutex mutex_;
    std::condition_variable wake_;
    std::map<schedule_key, packet> scheduled_;
    std::uint64_t next_sequence_{0};
    bool stopping_{false};
    std::thread worker_;
};

bool counted_impairment_enabled(const counted_impairment& value) {
    return value.mode == occurrence_mode::periodic ||
           (value.mode == occurrence_mode::rate && value.rate > 0.0);
}

bool jitter_impairment_enabled(const jitter_impairment& value) {
    return (value.mode == jitter_mode::random && value.max_ms > 0.0) ||
           (value.mode == jitter_mode::target && value.target_ms > 0.0);
}

std::string describe_counted_impairment(const counted_impairment& value, bool reorder) {
    if (value.mode == occurrence_mode::none) {
        return "off";
    }
    std::ostringstream out;
    if (value.mode == occurrence_mode::rate) {
        out << "rate=" << value.rate;
        return out.str();
    }

    if (value.periodic.basis == period_basis::packets) {
        out << "periodic=" << value.periodic.packet_period << "p";
    } else {
        out << "periodic="
            << std::chrono::duration<double, std::milli>(value.periodic.time_period).count()
            << "ms";
    }
    out << ",count=" << value.periodic.count;
    if (reorder) {
        out << "pairs";
    }
    return out.str();
}

const char* modulation_curve_name(modulation_curve curve) {
    switch (curve) {
    case modulation_curve::sine: return "sine";
    case modulation_curve::triangle: return "triangle";
    case modulation_curve::step: return "step";
    case modulation_curve::random: return "random";
    }
    return "unknown";
}

void print_modulation(const options& opt) {
    const auto print_one = [](const modulation& value) {
        std::cerr << (value.metric == modulation_metric::bitrate ? "bitrate" : "jitter")
                  << ",curve=" << modulation_curve_name(value.curve)
                  << ",min=" << value.min_value
                  << ",max=" << value.max_value
                  << ",period=" << std::chrono::duration<double, std::milli>(value.period).count() << "ms";
        if (value.phase != clock_type::duration::zero()) std::cerr << ",phase=" << std::chrono::duration<double, std::milli>(value.phase).count() << "ms";
        if (value.curve == modulation_curve::random) {
            std::cerr << ",update=" << std::chrono::duration<double, std::milli>(value.update).count() << "ms";
            if (value.seed) std::cerr << ",seed=" << *value.seed;
        }
    };
    if (!opt.bitrate_modulation && !opt.jitter_modulation) return;
    std::cerr << "modulate:";
    if (opt.bitrate_modulation) { std::cerr << " "; print_one(*opt.bitrate_modulation); }
    if (opt.jitter_modulation) { std::cerr << " "; print_one(*opt.jitter_modulation); }
    std::cerr << "\n";
}

bool impairment_enabled(const options& opt) {
    return counted_impairment_enabled(opt.loss) ||
           counted_impairment_enabled(opt.duplicate) ||
           counted_impairment_enabled(opt.reorder) ||
           jitter_impairment_enabled(opt.jitter) ||
           opt.jitter_modulation.has_value();
}

void print_impairment(const options& opt) {
    if (!impairment_enabled(opt)) {
        return;
    }

    std::cerr
        << "impairment: loss=" << describe_counted_impairment(opt.loss, false)
        << " duplicate=" << describe_counted_impairment(opt.duplicate, false)
        << " reorder=" << describe_counted_impairment(opt.reorder, true);

    if (opt.jitter.mode == jitter_mode::random) {
        std::cerr << " jitter=random,max-ms=" << opt.jitter.max_ms;
    } else if (opt.jitter.mode == jitter_mode::target) {
        std::cerr << " jitter=target,target-ms=" << opt.jitter.target_ms
                  << ",target-mode=" << jitter_target_mode_name(opt.jitter.target_mode);
    }
    if (opt.seed) {
        std::cerr << " seed=" << *opt.seed;
    }

    std::cerr << "\n";
}

void print_impairment_warnings(const options& opt) {
    const double interval_ms = nominal_packet_interval_ms(opt);
    const bool has_counted_errors =
        counted_impairment_enabled(opt.loss) ||
        counted_impairment_enabled(opt.duplicate) ||
        counted_impairment_enabled(opt.reorder);
    const bool has_rate_error =
        (opt.loss.mode == occurrence_mode::rate && opt.loss.rate > 0.0) ||
        (opt.duplicate.mode == occurrence_mode::rate && opt.duplicate.rate > 0.0) ||
        (opt.reorder.mode == occurrence_mode::rate && opt.reorder.rate > 0.0);

    if (opt.uses_legacy_impairment_options) {
        std::cerr << "warning: legacy impairment aliases are deprecated; use --impair type,mode=...,key=value\n";
    }

    const auto warn_time_period_capacity = [&opt](
        const counted_impairment& value, bool reorder, const char* type) {
        if (value.mode != occurrence_mode::periodic ||
            value.periodic.basis != period_basis::time) {
            return;
        }
        const double expected_packets =
            static_cast<double>(opt.bitrate_bps) / static_cast<double>(opt.payload_size * 8) *
            std::chrono::duration<double>(value.periodic.time_period).count();
        const std::uint64_t required = reorder ? value.periodic.count * 2 : value.periodic.count;
        if (expected_packets < static_cast<double>(required)) {
            std::cerr
                << "warning: --impair " << type << " time period has about "
                << expected_packets << " nominal packets but requires " << required
                << "; a window can contain fewer errors than count.\n";
        }
    };
    warn_time_period_capacity(opt.loss, false, "loss");
    warn_time_period_capacity(opt.duplicate, false, "duplicate");
    warn_time_period_capacity(opt.reorder, true, "reorder");

    if (opt.jitter.mode == jitter_mode::random && opt.jitter.max_ms > interval_ms) {
        std::cerr
            << "warning: jitter random max-ms " << opt.jitter.max_ms
            << " exceeds the nominal packet interval " << interval_ms
            << " ms; ordered delivery clamps some delays, so the configured maximum delay may not be observed.\n";
    }

    if (jitter_target_reorders(opt)) {
        std::cerr
            << "warning: jitter target-mode=reorder permits "
            << (opt.proto == proto_type::rtp ? "RTP" : "SRT")
            << " data packets to arrive out of order; target-ms is best effort and includes reordering effects.\n";
    }

    if (jitter_impairment_enabled(opt.jitter) &&
        opt.jitter.mode == jitter_mode::target && has_counted_errors) {
        std::cerr
            << "warning: loss, duplicate, or reorder injection changes the jitter estimator input; jitter target-ms is not guaranteed with these impairments.\n";
    }

    if (has_rate_error) {
        std::cerr
            << "warning: rate-mode impairments are independent probabilities; short captures need not match their configured rates.\n";
    }

    const int active_counted = static_cast<int>(counted_impairment_enabled(opt.loss)) +
        static_cast<int>(counted_impairment_enabled(opt.duplicate)) +
        static_cast<int>(counted_impairment_enabled(opt.reorder));
    if (active_counted > 1) {
        std::cerr
            << "warning: combined loss, duplicate, and reorder act on the same source packets; observed counts can differ from individual settings.\n";
    }

    if (opt.proto == proto_type::rtp && jitter_impairment_enabled(opt.jitter) &&
        opt.jitter.mode == jitter_mode::target &&
        opt.clock_rate > 0 && opt.jitter.target_ms < 1000.0 / opt.clock_rate) {
        std::cerr
            << "warning: jitter target-ms " << opt.jitter.target_ms
            << " is below the RTP timestamp resolution " << (1000.0 / opt.clock_rate)
            << " ms; the target cannot be represented exactly.\n";
    }

    if (opt.proto == proto_type::srt && jitter_impairment_enabled(opt.jitter) &&
        opt.jitter.mode == jitter_mode::target &&
        opt.jitter.target_ms < 10.0) {
        std::cerr
