        base_time_ = value;
    }

    void submit(packet value) {
        const auto base = base_time_.value_or(clock_type::now());
        auto due = base;
        const double target_ms = jitter_modulation_.enabled()
            ? jitter_modulation_.value_at(base) : jitter_target_ms_;
