function buildEventMarkerBuckets(events: EventLogItem[], range: { start: number; end: number }): EventMarkerBucket[] {
  const bucketSec = eventBucketStepSec(range.end - range.start);
  const buckets = new Map<number, EventLogItem[]>();
  for (const event of events) {
    const key = Math.floor(event.time / bucketSec);
    const bucket = buckets.get(key) ?? [];
    bucket.push(event);
    buckets.set(key, bucket);
  }
  return [...buckets.entries()].sort(([left], [right]) => left - right).map(([key, bucket]) => {
    const primary = eventMarkerPrimary(bucket);
    return {
      key: String(key),
      time: primary.time,
      level: bucket.some((event) => event.level === "error") ? "error" : "warn",
      events: bucket,
      primary
    };
  });
}

function clusterEventMarkerBuckets(buckets: EventMarkerBucket[], range: { start: number; end: number }, axisWidth: number): EventMarkerBucket[] {
  if (axisWidth <= 0 || buckets.length < 2) return buckets;
  const minimumDistanceSec = (range.end - range.start) * EVENT_MARKER_MIN_DISTANCE_PX / axisWidth;
  const clusters: EventMarkerBucket[][] = [];
  for (const bucket of buckets) {
    const current = clusters[clusters.length - 1];
    const previous = current?.[current.length - 1];
    if (previous && bucket.time - previous.time < minimumDistanceSec) current.push(bucket);
    else clusters.push([bucket]);
  }
  return clusters.map((cluster) => {
