  const label = newestFirst ? "Newest first" : "Oldest first";
  return <button type="button" className="events-sort-button" onClick={onToggle} data-tooltip-key={newestFirst ? "tooltip.sortEventsNewestFirst" : "tooltip.sortEventsOldestFirst"} aria-label={`Sort events: ${label}`} aria-pressed={newestFirst}>
    <span className="events-sort-clock"><Icon name="clock" size={14} /><Icon name={newestFirst ? "sortNewest" : "sortOldest"} size={9} /></span>
  </button>;
}

