function EventColumnResizers({
  height: 100%;
  max-height: none;
  overflow: auto;
  gap: 0;
  padding: var(--space-1);
  background: var(--surface);
}

.event-row {
  min-height: 30px;
  height: 30px;
  grid-template-columns: 28px var(--event-time-width) var(--event-level-width) var(--event-target-width) minmax(0, 1fr);
  column-gap: 4px;
  row-gap: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  font-size: var(--font-size-xs);
}

.event-column-resizers {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
}

.event-column-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 10px;
  transform: translateX(-50%);
  cursor: col-resize;
  pointer-events: auto;
  touch-action: none;
}

.events-jump-latest {
  position: absolute;
  right: var(--space-2);
  bottom: var(--space-2);
  z-index: 4;
  min-height: 24px;
  padding: 0 var(--space-2);
  border: 1px solid var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--accent);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.events-jump-latest:hover {
  background: var(--accent-soft);
}

.event-column-resizer::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 4px;
  width: 1px;
  background: transparent;
  content: "";
}

.event-column-resizer:hover::before,
.event-column-resizer:active::before {
  background: var(--accent);
}

.event-marker, .event-time, .event-level, .event-target, .event-message {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.event-row:hover {
  background: var(--surface-muted);
}

.event-row.time-neighbor {
  background: color-mix(in srgb, var(--accent-soft) 58%, var(--surface));
}

.event-row.time-neighbor:hover {
  background: color-mix(in srgb, var(--accent-soft) 76%, var(--surface));
}

.event-row.event-primary-selected {
  background: var(--accent-soft);
  box-shadow: inset 4px 0 0 var(--accent);
}

.event-marker {
  display: grid;
  place-items: center;
  min-height: 18px;
  border-radius: 999px;
  color: var(--warning);
  font-size: 10px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.event-row.event-measurement-anchor .event-marker {
  background: color-mix(in srgb, var(--warning-soft) 82%, var(--surface));
}

.event-row.event-primary-selected .event-time {
  color: var(--text-strong);
  font-weight: 700;
}

.event-row.event-related {
  background: color-mix(in srgb, var(--accent-soft) 52%, var(--surface));
  box-shadow: inset 3px 0 0 var(--accent-border);
}

.event-row.event-related:hover {
  background: color-mix(in srgb, var(--accent-soft) 72%, var(--surface));
}

.event-row.event-measurement-anchor {
