725	function EventColumnResizers({
726	  widths,
727	  onResizeStart,
728	  onAutoFit
729	}: {
730	  widths: EventColumnWidths;
731	  onResizeStart: (column: EventColumn, event: ReactPointerEvent<HTMLDivElement>) => void;
