739	  ];
740	  return <div className="event-column-resizers">{boundaries.map(({ column, left: offset, label, tooltipKey }) => (
741	    <div
742	      key={column}
743	      className="event-column-resizer"
744	      style={{ left: offset }}
745	      role="separator"
746	      aria-orientation="vertical"
