function EventRelationConnector({ geometry }: { geometry: EventRelationConnectorGeometry | null }) {
  if (!geometry) return null;
  const top = Math.min(geometry.occurredY, geometry.recoveredY);
  const bottom = Math.max(geometry.occurredY, geometry.recoveredY);
  const path = `M ${geometry.markerX} ${top} H ${geometry.railX} V ${bottom} H ${geometry.markerX}`;
  return <svg className="event-relation-connector" width={geometry.width} height={geometry.height} viewBox={`0 0 ${geometry.width} ${geometry.height}`} aria-hidden="true">
