    <circle className="event-relation-connector-endpoint occurred" cx={geometry.markerX} cy={geometry.occurredY} r="3.5" />
    <circle className="event-relation-connector-endpoint recovered" cx={geometry.markerX} cy={geometry.recoveredY} r="3.5" />
  </svg>;
}

