const r = await tools.exec_command({"cmd":"ed -s fe/client/src/components/EventLog.tsx <<'EOF'
164a
  const locallySelectedEventIdRef = useRef<string | null>(null);
.
972a

function eventRelationEndpoint(event: EventLogItem): EventRelationEndpoint | null {
  if (event.type === "alert_detected" || event.type === "alert_data_unavailable" || event.type.endsWith("_occurred")) return "occurred";
  if (event.type === "alert_recovered" || event.type === "alert_data_available" || event.type.endsWith("_recovered")) return "recovered";
  return null;
}

function eventRelationPairFor(source: EventLogItem | null, related: EventLogItem | null): EventRelationPair | null {
  if (!source || !related) return null;
  const sourceEndpoint = eventRelationEndpoint(source);
  const relatedEndpoint = eventRelationEndpoint(related);
  if (!sourceEndpoint || !relatedEndpoint || sourceEndpoint === relatedEndpoint) return null;
  const occurred = sourceEndpoint === "occurred" ? source : related;
  const recovered = sourceEndpoint === "recovered" ? source : related;
  if (recovered.time < occurred.time) return null;
  return { occurred, recovered, duration: recovered.time - occurred.time };
}

function relationPairMarkers(pair: EventRelationPair | null) {
  const markers = new Map<string, EventRelationMarker>();
  if (!pair) return markers;
  const tooltip = `Occurred → Recovered · ${formatDuration(pair.duration)}`;
  markers.set(pair.occurred.id, { endpoint: "occurred", tooltip });
  markers.set(pair.recovered.id, { endpoint: "recovered", tooltip });
  return markers;
}

function relationConnectorEqual(current: EventRelationConnectorGeometry | null, next: EventRelationConnectorGeometry) {
  return current !== null && current.width === next.width && current.height === next.height &&
    current.railX === next.railX && current.markerX === next.markerX &&
    current.occurredY === next.occurredY && current.recoveredY === next.recoveredY;
}
.
