        continuationTooltip: continuation ? relationContinuationTooltip(otherEvent, continuation, pair.duration) : null
      };
      setRelationConnector((current) => relationConnectorEqual(current, next) ? current : next);
    };
    const scheduleUpdate = () => {
      if (animationFrame !== 0) return;
      animationFrame = window.requestAnimationFrame(update);
    };

    const resizeObserver = new ResizeObserver(scheduleUpdate);
    resizeObserver.observe(frame);
    if (occurredRow) resizeObserver.observe(occurredRow);
    if (recoveredRow) resizeObserver.observe(recoveredRow);
    const mutationObserver = new MutationObserver(scheduleUpdate);
    mutationObserver.observe(list, { childList: true, subtree: true });
    list.addEventListener("scroll", scheduleUpdate, { passive: true });
    scheduleUpdate();

    return () => {
      if (animationFrame !== 0) window.cancelAnimationFrame(animationFrame);
      resizeObserver.disconnect();
      mutationObserver.disconnect();
      list.removeEventListener("scroll", scheduleUpdate);
    };
  }, [detailPresentation, relationPair?.occurred.id, relationPair?.recovered.id, renderedEvents.length, sortOrder, visibleSignature]);

  useLayoutEffect(() => {
    const snapshot = localSelectionSnapshot;
    if (!snapshot) return;
    const selectionIsCurrent = selectedEvent !== null
      && snapshot.selectedEventId === selectedEvent.id
      && (snapshot.selectedTimeSec === null || snapshot.selectedTimeSec === selectedTimeSec)
      && snapshot.tab === tab
      && snapshot.query === normalizedQuery
      && snapshot.sortOrder === sortOrder
      && snapshot.eventsRange === eventsRange;
    if (selectionIsCurrent) return;
    setLocalSelectionSnapshot(null);
  }, [eventsRange, localSelectionSnapshot, normalizedQuery, selectedEvent, selectedTimeSec, sortOrder, tab]);

  useEffect(() => {
    const source = selectedEvent;
    const relation = source ? eventRelationFor(source) : null;
    if (!source || !relation) {
      setRelatedEvent(null);
      return;
    }

    const localRelated = findRelatedEvent(events, source, relation);
    if (localRelated) {
      setRelatedEvent({ sourceId: source.id, event: localRelated });
      return;
    }

    const target = source.flowKey ? { flowKey: source.flowKey } : source.streamKey ? { streamKey: source.streamKey } : null;
    if (!target) return;
    const now = Date.now() / 1000;
    const from = relation.direction === "before" ? Math.max(0, source.time - RELATED_EVENT_LOOKUP_WINDOW_SEC) : source.time;
    const to = relation.direction === "after" ? Math.min(now, source.time + RELATED_EVENT_LOOKUP_WINDOW_SEC) : source.time;
    if (to <= from) return;

    let cancelled = false;
    void Promise.all(relation.counterpartTypes.map((type) => getEvents({ ...target, type, from, to, limit: 100 })))
      .then((results) => {
        if (cancelled) return;
        const related = findRelatedEvent(results.flat(), source, relation);
        if (related) setRelatedEvent({ sourceId: source.id, event: related });
      })
      .catch(() => { /* Keep the detail neutral when history lookup is unavailable. */ });
    return () => { cancelled = true; };
  }, [selectedEvent?.id]);

  useEffect(() => {
    const source = selectedEvent;
    const relation = source ? eventRelationFor(source) : null;
    if (!source || !relation) return;
    const localRelated = findRelatedEvent(events, source, relation);
    if (localRelated) setRelatedEvent({ sourceId: source.id, event: localRelated });
  }, [events, selectedEvent?.id]);

  useLayoutEffect(() => {
    const element = listRef.current;
    if (!element || visibleEvents.length === 0) return;
    const prev = scrollSnapshotRef.current;
    const heightDelta = element.scrollHeight - prev.height;
    if (!followLatestRef.current && heightDelta !== 0) element.scrollTop = prev.top + heightDelta;
    scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
  }, [visibleSignature, tab, normalizedQuery, eventsRange, visibleEvents.length]);

  useLayoutEffect(() => {
    const anchor = localSelectionScrollAnchorRef.current;
    if (!anchor || selectedEvent?.id !== anchor.eventId) return;
    const list = listRef.current;
    const row = eventRowRefs.current.get(anchor.eventId);
    if (!list || !row) return;

    const rowOffset = row.getBoundingClientRect().top - list.getBoundingClientRect().top;
    list.scrollTop = Math.max(0, anchor.scrollTop + rowOffset - anchor.rowOffset);
    scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
    localSelectionScrollAnchorRef.current = null;
  }, [selectedEvent?.id]);

  useLayoutEffect(() => {
    if (detailPresentation !== "inline" || !selectedEvent) return;
    const list = listRef.current;
    const context = list?.querySelector<HTMLElement>(".event-context-inline");
    if (!list || !context) return;

    const listBounds = list.getBoundingClientRect();
    const contextBounds = context.getBoundingClientRect();
    const inset = 4;
    let offset = 0;
    if (contextBounds.top < listBounds.top + inset) offset = contextBounds.top - listBounds.top - inset;
    else if (contextBounds.top > listBounds.bottom - inset) offset = contextBounds.top - listBounds.bottom + 32;
    if (offset === 0) return;

    followLatestRef.current = false;
    list.scrollTop = Math.max(0, list.scrollTop + offset);
    scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
  }, [detailPresentation, selectedEvent?.id]);

  useLayoutEffect(() => {
    const eventId = keyboardSelectionEventIdRef.current;
    if (!eventId || selectedEvent?.id !== eventId) return;
    keyboardSelectionEventIdRef.current = null;

    const list = listRef.current;
    const row = eventRowRefs.current.get(eventId);
    if (!list || !row) return;
    row.focus({ preventScroll: true });

    const listBounds = list.getBoundingClientRect();
    const rowBounds = row.getBoundingClientRect();
    const inset = 4;
    let offset = 0;
    if (rowBounds.top < listBounds.top + inset) offset = rowBounds.top - listBounds.top - inset;
    else if (rowBounds.bottom > listBounds.bottom - inset) offset = rowBounds.bottom - listBounds.bottom + inset;
    if (offset !== 0) {
      followLatestRef.current = false;
      list.scrollTop = Math.max(0, list.scrollTop + offset);
    }
    scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
    setShowLatestJump(list.scrollTop > 8);
  }, [selectedEvent?.id]);
  useLayoutEffect(() => {
    const eventId = relatedEventNavigationIdRef.current;
    if (!eventId || selectedEvent?.id !== eventId) return;

    const list = listRef.current;
    const row = eventRowRefs.current.get(eventId);
    if (!list || !row) return;
    relatedEventNavigationIdRef.current = null;
    row.focus({ preventScroll: true });

    const listBounds = list.getBoundingClientRect();
    const rowBounds = row.getBoundingClientRect();
    const inset = 4;
    let offset = 0;
    if (rowBounds.top < listBounds.top + inset) offset = rowBounds.top - listBounds.top - inset;
    else if (rowBounds.bottom > listBounds.bottom - inset) offset = rowBounds.bottom - listBounds.bottom + inset;
    if (offset !== 0) {
      followLatestRef.current = false;
      list.scrollTop = Math.max(0, list.scrollTop + offset);
    }
    scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
    setShowLatestJump(list.scrollTop > 8);
  }, [selectedEvent?.id, visibleSignature, renderedEvents.length]);


  useLayoutEffect(() => {
    if (selectedTimeSec === null) {
      lastAutoScrolledKeyRef.current = null;
      locallySelectedEventIdRef.current = null;
      return;
    }

    const selected = timeSelectedEvent;
    if (!selected) return;
    const scrollKey = selected.id + ":" + visibleSignature;
    if (lastAutoScrolledKeyRef.current === scrollKey) return;

    if (locallySelectedEventIdRef.current === selected.id) {
      lastAutoScrolledKeyRef.current = scrollKey;
      return;
    }
    locallySelectedEventIdRef.current = null;

    const frame = window.requestAnimationFrame(() => {
      const row = eventRowRefs.current.get(selected.id);
      const list = listRef.current;
      if (!row || !list) return;

      const rowBounds = row.getBoundingClientRect();
      const listBounds = list.getBoundingClientRect();
      const inset = 4;
      let offset = 0;
      if (rowBounds.top < listBounds.top + inset) offset = rowBounds.top - listBounds.top - inset;
      else if (rowBounds.bottom > listBounds.bottom - inset) offset = rowBounds.bottom - listBounds.bottom + inset;
      if (offset === 0) {
        lastAutoScrolledKeyRef.current = scrollKey;
        return;
      }

      followLatestRef.current = false;
      list.scrollTop = Math.max(0, list.scrollTop + offset);
      scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
      lastAutoScrolledKeyRef.current = scrollKey;
    });
    return () => window.cancelAnimationFrame(frame);
  }, [selectedTimeSec, visibleSignature, renderedEvents.length]);

  const applyColumnWidths = (next: EventColumnWidths) => {
    const normalized = normalizeColumnWidths(next);
    if (onChangeColumnWidths) {
      onChangeColumnWidths(normalized);
      return;
    }
    setInternalColumnWidths(normalized);
    try { window.localStorage.setItem(EVENT_LIST_STORAGE_KEY, JSON.stringify(normalized)); } catch { /* Storage may be unavailable. */ }
  };

  const resizeColumn = (column: EventColumn, event: ReactPointerEvent<HTMLDivElement>) => {
    if (window.matchMedia("(max-width: 720px)").matches) return;
    event.preventDefault();
    event.stopPropagation();
    const startX = event.clientX;
    const startWidth = columnWidths[column];
    const previousCursor = document.body.style.cursor;
    document.body.style.cursor = "col-resize";

    const onMove = (moveEvent: PointerEvent) => {
      const limits = EVENT_COLUMN_LIMITS[column];
      applyColumnWidths({ ...columnWidths, [column]: clamp(startWidth + moveEvent.clientX - startX, limits.min, limits.max) });
    };
    const onUp = () => {
      document.body.style.cursor = previousCursor;
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const autoFitColumn = (column: EventColumn, event: ReactMouseEvent<HTMLDivElement>) => {
    if (window.matchMedia("(max-width: 720px)").matches) return;
    event.preventDefault();
    event.stopPropagation();
    const list = listRef.current;
    if (!list) return;
    const row = list.querySelector<HTMLElement>(".event-row");
    const context = document.createElement("canvas").getContext("2d");
    if (!context) return;
    context.font = getComputedStyle(row ?? list).font;
    const widest = renderedEvents.slice(0, AUTO_FIT_SAMPLE_SIZE).reduce((max, item) => Math.max(max, context.measureText(eventColumnText(item, column)).width), 0);
    const limits = EVENT_COLUMN_LIMITS[column];
    applyColumnWidths({ ...columnWidths, [column]: clamp(Math.ceil(widest) + 12, limits.min, limits.max) });
  };

  const captureLocalSelectionAnchor = (event: EventLogItem) => {
    const list = listRef.current;
    const row = eventRowRefs.current.get(event.id);
    if (!list || !row) return;
    localSelectionScrollAnchorRef.current = {
      eventId: event.id,
      scrollTop: list.scrollTop,
      rowOffset: row.getBoundingClientRect().top - list.getBoundingClientRect().top
    };
  };

  const toggleMeasurementAnchor = (event: EventLogItem) => {
    setMeasurementAnchors((current) => {
      if (current.some((anchor) => anchor.event.id === event.id)) {
        return current.filter((anchor) => anchor.event.id !== event.id).map((anchor, index) => ({ ...anchor, number: index + 1 }));
      }
      return [...current, { event, number: current.length + 1 }];
    });
  };

  const toggleSortOrder = () => setSortOrder(sortOrder === "desc" ? "asc" : "desc");

  const jumpToLatest = () => {
    const list = listRef.current;
    if (!list) return;
    list.scrollTop = sortOrder === "desc" ? 0 : list.scrollHeight;
    followLatestRef.current = true;
    scrollSnapshotRef.current = { top: list.scrollTop, height: list.scrollHeight };
    setShowLatestJump(false);
  };

  const createLocalSelectionSnapshot = (event: EventLogItem, snapshotEvents: EventLogItem[], snapshotTime: number | null, outsideRangeEvent: EventLogItem | null = null): LocalSelectionSnapshot => ({
    events: snapshotEvents,
    tab,
    query: normalizedQuery,
    eventsRange,
    sortOrder,
    selectedEventId: event.id,
    selectedTimeSec: snapshotTime,
    outsideRangeEvent
  });
  const selectEventFromPointer = (event: EventLogItem, snapshotEvents = visibleEvents, outsideRangeEvent: EventLogItem | null = null) => {
    keyboardSelectionEventIdRef.current = null;
    selectEvent(event, snapshotEvents, outsideRangeEvent);
  };

  const closeSelectedEvent = () => {
    locallySelectedEventIdRef.current = null;
    keyboardSelectionEventIdRef.current = null;
    lastAutoScrolledKeyRef.current = null;
    setLocalSelectionSnapshot(null);
    setSelectedEvent(null);
    onSelectEvent?.(null);
  };

  const syncEventTime = (event: EventLogItem, callback: ((timeSec: number) => void) | undefined, snapshotEvents = visibleEvents, outsideRangeEvent: EventLogItem | null = null) => {
    if (!callback) return;
    captureLocalSelectionAnchor(event);
    locallySelectedEventIdRef.current = event.id;
    setLocalSelectionSnapshot(createLocalSelectionSnapshot(event, snapshotEvents, event.time, outsideRangeEvent));
    callback(event.time);
  };

  const selectEvent = (event: EventLogItem, snapshotEvents = visibleEvents, outsideRangeEvent: EventLogItem | null = null) => {
    captureLocalSelectionAnchor(event);
    setSelectedEvent(event);
    if (syncTimeOnRowClick) syncEventTime(event, onSelectTime, snapshotEvents, outsideRangeEvent);
    onSelectEvent?.(event);
  };

  const selectRelatedEvent = (event: EventLogItem, outsideRange: boolean) => {
    relatedEventNavigationIdRef.current = event.id;
    const outsideRangeEvent = outsideRange ? event : null;
    if (!syncTimeOnRowClick) setLocalSelectionSnapshot(createLocalSelectionSnapshot(event, visibleEvents, null, outsideRangeEvent));
    selectEventFromPointer(event, visibleEvents, outsideRangeEvent);
  };
  const moveEventSelection = (event: EventLogItem, direction: -1 | 1) => {
    const currentEventId = keyboardSelectionEventIdRef.current ?? event.id;
    const index = renderedEvents.findIndex((item) => item.id === currentEventId);
    const nextEvent = index === -1 ? undefined : renderedEvents[index + direction];
    if (!nextEvent) return;
    keyboardSelectionEventIdRef.current = nextEvent.id;
    selectEvent(nextEvent);
  };

  return (
    <section className={`events-card ${showHeader ? "" : "events-card-embedded"}${measurementAnchors.length ? " has-measurement" : ""}`}>
      {showHeader && (
        <div className="pane-header events-header">
          <div className="pane-header-title-with-icon"><Icon className="pane-header-icon" name="events" size={14} /><h3>Events</h3></div>
          <div className="events-actions">
            {showSearch && <SearchInput className="event-search" value={query} onChange={setQuery} placeholder="Search events" label="event search" />}
            <label className="detail-range-select" data-tooltip-key="tooltip.eventRange">
              <span>Range</span>
              <select value={eventsRange} onChange={(event) => onChangeEventsRange(event.target.value)}>
                <option value="24h">24h</option>
                <option value="12h">12h</option>
                <option value="6h">6h</option>
                <option value="3h">3h</option>
                <option value="1h">1h</option>
                <option value="30m">30m</option>
                <option value="10m">10m</option>
                <option value="5m">5m</option>
                <option value="1m">1m</option>
              </select>
            </label>
            <EventSortButton order={sortOrder} onToggle={toggleSortOrder} />
            <div className="events-tabs">
              <button className={tab === "all" ? "active" : ""} onClick={() => setTab("all")}>All</button>
              <button className={tab === "selected" ? "active" : ""} onClick={() => setTab("selected")}>Selected</button>
            </div>
          </div>
        </div>
      )}
      {measurementAnchors.length > 0 && <EventMeasurement anchors={sortedMeasurementAnchors} onClear={() => setMeasurementAnchors([])} />}
      <div className={`events-content ${detailPresentation === "panel" && selectedEvent ? "has-context" : ""}`}>
        <div ref={listFrameRef} className="events-list-frame" style={columnStyle}>
          <div
            ref={listRef}
            className="events-list"
            onScroll={(event) => {
              const element = event.currentTarget;
              const atLatest = sortOrder === "desc" ? element.scrollTop <= 8 : element.scrollTop + element.clientHeight >= element.scrollHeight - 8;
              followLatestRef.current = atLatest;
              setShowLatestJump(!atLatest);
              scrollSnapshotRef.current = { top: element.scrollTop, height: element.scrollHeight };
            }}
          >
            {renderedEvents.length === 0 ? (
              <div className="events-empty">No events</div>
            ) : (
              <>
                {visibleEvents.length > MAX_RENDERED_EVENTS && <div className="events-empty">Showing latest {MAX_RENDERED_EVENTS} / {visibleEvents.length} events</div>}
                {renderedEvents.map((event) => {
                  const isRelatedEvent = activeRelatedEvent?.id === event.id;
                  const isOutsideRange = pinnedOutsideRangeEvent?.id === event.id;
                  const relationMarker = relationMarkers.get(event.id);
                  return <Fragment key={event.id}>
                    {isOutsideRange && <div className="event-related-boundary">Related event outside current range</div>}
                    <EventRow
                      event={event}
                      primarySelected={primarySelectedEventId === event.id}
                      related={isRelatedEvent}
                      relationMarker={relationMarker}
                      measurementAnchorNumber={measurementAnchors.find((anchor) => anchor.event.id === event.id)?.number}
                      timeNeighbor={selectedTimeSec !== null && Math.abs(event.time - selectedTimeSec) < 0.5 && primarySelectedEventId !== event.id}
                      syncTimeOnSelect={syncTimeOnRowClick && onSelectTime !== undefined}
                      onSelect={(pointerEvent) => {
                        if (pointerEvent.shiftKey) {
                          pointerEvent.preventDefault();
                          toggleMeasurementAnchor(event);
                          return;
                        }
                        selectEventFromPointer(event);
                      }}
                      onMoveSelection={(direction) => moveEventSelection(event, direction)}
                      eventRef={(element) => {
                        if (element) eventRowRefs.current.set(event.id, element);
                        else eventRowRefs.current.delete(event.id);
                      }}
                    />
                    {detailPresentation === "inline" && selectedEvent?.id === event.id && <EventContext
                      event={selectedEvent}
                      inline
                      relatedEvent={activeRelatedEvent}
                      relatedOutsideRange={relatedEventOutsideRange}
                      onSelectRelated={activeRelatedEvent ? () => selectRelatedEvent(activeRelatedEvent, relatedEventOutsideRange) : undefined}
                      onSyncTime={onSyncTime ? () => syncEventTime(selectedEvent, onSyncTime) : undefined}
                      onInspect={onInspectTarget && (selectedEvent.streamKey || selectedEvent.interfaceId !== undefined) ? () => onInspectTarget(selectedEvent) : undefined}
                      onClose={closeSelectedEvent}
                    />}
                  </Fragment>;
                })}
              </>
            )}
          </div>
          <EventRelationConnector geometry={relationConnector} />
          {showLatestJump && <button type="button" className="events-jump-latest" onClick={jumpToLatest} data-tooltip-key="tooltip.jumpLatestEvent">Latest</button>}
          <EventColumnResizers widths={effectiveColumnWidths} onResizeStart={resizeColumn} onAutoFit={autoFitColumn} />
        </div>
        {detailPresentation === "panel" && selectedEvent && <EventContext
          event={selectedEvent}
          relatedEvent={activeRelatedEvent}
          relatedOutsideRange={relatedEventOutsideRange}
          onSelectRelated={activeRelatedEvent ? () => selectRelatedEvent(activeRelatedEvent, relatedEventOutsideRange) : undefined}
          onSyncTime={onSyncTime ? () => syncEventTime(selectedEvent, onSyncTime) : undefined}
          onInspect={onInspectTarget && (selectedEvent.streamKey || selectedEvent.interfaceId !== undefined) ? () => onInspectTarget(selectedEvent) : undefined}
          onClose={closeSelectedEvent}
        />}
      </div>
    </section>
  );
}

function EventSortButton({ order, onToggle }: { order: EventSortOrder; onToggle: () => void }) {
  const newestFirst = order === "desc";
  const label = newestFirst ? "Newest first" : "Oldest first";
  return <button type="button" className="events-sort-button" onClick={onToggle} data-tooltip-key={newestFirst ? "tooltip.sortEventsNewestFirst" : "tooltip.sortEventsOldestFirst"} aria-label={`Sort events: ${label}`} aria-pressed={newestFirst}>
    <span className="events-sort-clock"><Icon name="clock" size={14} /><Icon name={newestFirst ? "sortNewest" : "sortOldest"} size={9} /></span>
  </button>;
}

function EventColumnResizers({
  widths,
  onResizeStart,
  onAutoFit
}: {
  widths: EventColumnWidths;
  onResizeStart: (column: EventColumn, event: ReactPointerEvent<HTMLDivElement>) => void;
  onAutoFit: (column: EventColumn, event: ReactMouseEvent<HTMLDivElement>) => void;
}) {
  const left = EVENT_ROW_SIDE_PADDING_PX + EVENT_MARKER_COLUMN_PX + EVENT_COLUMN_GAP_PX + widths.time + EVENT_COLUMN_GAP_PX / 2;
  const boundaries: Array<{ column: EventColumn; left: number; label: string; tooltipKey: string }> = [
    { column: "time", left, label: "Resize time column", tooltipKey: "tooltip.fitTimeColumn" },
    { column: "level", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX / 2, label: "Resize level column", tooltipKey: "tooltip.fitLevelColumn" },
    { column: "target", left: left + EVENT_COLUMN_GAP_PX / 2 + widths.level + EVENT_COLUMN_GAP_PX + widths.target + EVENT_COLUMN_GAP_PX / 2, label: "Resize target column", tooltipKey: "tooltip.fitTargetColumn" }
  ];
  return <div className="event-column-resizers">{boundaries.map(({ column, left: offset, label, tooltipKey }) => (
    <div
      key={column}
      className="event-column-resizer"
      style={{ left: offset }}
      role="separator"
      aria-orientation="vertical"
      aria-label={`${label}; double-click to fit content`}
      data-tooltip-key={tooltipKey}
      onPointerDown={(event) => onResizeStart(column, event)}
      onDoubleClick={(event) => onAutoFit(column, event)}
    />
  ))}</div>;
}

function EventRelationConnector({ geometry }: { geometry: EventRelationConnectorGeometry | null }) {
  if (!geometry) return null;
  const path = `M ${geometry.markerX} ${geometry.startY} V ${geometry.endY}`;
  return <>
    <svg className="event-relation-connector" width={geometry.width} height={geometry.height} viewBox={`0 0 ${geometry.width} ${geometry.height}`} aria-hidden="true">
      <path className="event-relation-connector-line" d={path} />
    </svg>
    {geometry.continuation && geometry.continuationTooltip && <span
      className={`event-relation-continuation ${geometry.continuation}`}
      style={{ left: geometry.markerX, top: geometry.endY }}
      role="img"
      aria-label={geometry.continuationTooltip}
      data-tooltip={geometry.continuationTooltip}
    >{geometry.continuation === "top" ? "▲" : "▼"}</span>}
  </>;
}

function EventRow({ event, primarySelected, related, relationMarker, measurementAnchorNumber, timeNeighbor, onSelect, onMoveSelection, eventRef, syncTimeOnSelect }: { event: EventLogItem; primarySelected: boolean; related: boolean; relationMarker?: EventRelationMarker; measurementAnchorNumber?: number; timeNeighbor: boolean; onSelect: (event: ReactMouseEvent<HTMLButtonElement>) => void; onMoveSelection: (direction: -1 | 1) => void; eventRef: (element: HTMLButtonElement | null) => void; syncTimeOnSelect: boolean }) {
  const timeLabel = formatEventTime(event.time);
  const targetLabel = event.targetLabel ?? event.proto ?? event.scope;
  const onKeyDown = (keyEvent: ReactKeyboardEvent<HTMLButtonElement>) => {
    const direction = keyEvent.key === "ArrowUp" ? -1 : keyEvent.key === "ArrowDown" ? 1 : null;
    if (direction === null) return;
    keyEvent.preventDefault();
    onMoveSelection(direction);
  };
  const endpointLabel = relationMarker?.endpoint === "occurred" ? "Occurred" : "Recovered";
  return (
    <button ref={eventRef} type="button" className={`event-row ${event.level}${primarySelected ? " event-primary-selected" : ""}${related ? " event-related" : ""}${relationMarker ? ` event-relation-${relationMarker.endpoint}` : ""}${measurementAnchorNumber !== undefined ? " event-measurement-anchor" : ""}${timeNeighbor ? " time-neighbor" : ""}`} onClick={onSelect} onKeyDown={onKeyDown} data-tooltip-key={syncTimeOnSelect ? "tooltip.inspectAndSyncEvent" : "tooltip.inspectEvent"} aria-current={primarySelected ? "true" : undefined} aria-keyshortcuts="ArrowUp ArrowDown">
      <span className="event-marker" aria-label={measurementAnchorNumber === undefined ? undefined : `Measurement anchor ${measurementAnchorNumber}`}>
        {relationMarker && <span className={`event-relation-endpoint ${relationMarker.endpoint}`} role="img" aria-label={`${endpointLabel}. ${relationMarker.tooltip}`} data-tooltip={relationMarker.tooltip}>{relationMarker.endpoint === "occurred" ? "●" : "✓"}</span>}
        {measurementAnchorNumber === undefined ? "" : `#${measurementAnchorNumber}`}
      </span>
      <time className="event-time" dateTime={new Date(event.time * 1000).toISOString()} data-tooltip={timeLabel}>{timeLabel}</time>
      <span className="event-level" data-tooltip={event.level}>{event.level}</span>
      <span className="event-target" data-tooltip={targetLabel}>{targetLabel}</span>
      <span className="event-message" data-tooltip={event.message}>{event.message}</span>
    </button>
  );
}

function EventMeasurement({ anchors, onClear }: { anchors: MeasurementAnchor[]; onClear: () => void }) {
  const total = anchors.length > 1 ? anchors[anchors.length - 1].event.time - anchors[0].event.time : null;
  return <section className="event-measurement" aria-label="Event time measurement">
    <div className="event-measurement-summary">
      <strong>Measure</strong>
      {total === null ? <span>#{anchors[0].number} · Shift+click another event</span> : <span>#{anchors[0].number} → #{anchors[anchors.length - 1].number} · Δ {formatDuration(total)}</span>}
      <button type="button" onClick={onClear}>Clear</button>
    </div>
    {anchors.length > 1 && <div className="event-measurement-table-wrap">
      <table className="event-measurement-table">
        <caption>Measured intervals between event anchors</caption>
        <thead>
          <tr>
            <th scope="col" rowSpan={2}>From</th>
            <th scope="colgroup" colSpan={6}>From target</th>
            <th scope="col" rowSpan={2}>To</th>
            <th scope="colgroup" colSpan={6}>To target</th>
            <th scope="col" rowSpan={2}>Elapsed</th>
          </tr>
          <tr>
            <MeasurementTargetColumns />
            <MeasurementTargetColumns />
          </tr>
        </thead>
        <tbody>
          {anchors.slice(1).map((anchor, index) => {
            const previous = anchors[index];
            const fromTarget = measurementTargetParts(previous.event);
            const toTarget = measurementTargetParts(anchor.event);
            return <tr key={anchor.event.id} data-tooltip={measurementRowTitle(previous, anchor, fromTarget, toTarget)}>
              <MeasurementAnchorCell anchor={previous} />
              <MeasurementTargetCells target={fromTarget} />
              <MeasurementAnchorCell anchor={anchor} />
              <MeasurementTargetCells target={toTarget} />
              <td className="event-measurement-duration">Δ {formatDuration(anchor.event.time - previous.event.time)}</td>
            </tr>;
          })}
        </tbody>
      </table>
    </div>}
  </section>;
}

function MeasurementTargetColumns() {
  return <>
    <th scope="col" className="event-measurement-target-meta">NIC</th>
    <th scope="col" className="event-measurement-target-meta">VLAN</th>
    <th scope="col" className="event-measurement-target-meta">Proto</th>
    <th scope="col">Src</th>
    <th scope="col" className="event-measurement-target-arrow" aria-label="to">→</th>
    <th scope="col">Dst</th>
  </>;
}

function MeasurementAnchorCell({ anchor }: { anchor: MeasurementAnchor }) {
  const time = formatEventTime(anchor.event.time);
  return <th scope="row" className="event-measurement-anchor-cell">
    <span>#{anchor.number}</span>
    <time dateTime={new Date(anchor.event.time * 1000).toISOString()}>{time.slice(11)}</time>
  </th>;
}

function MeasurementTargetCells({ target }: { target: EventTargetParts }) {
  return <>
    <td className="event-measurement-target-meta">{target.nic}</td>
    <td className="event-measurement-target-meta">{target.vlan}</td>
    <td className="event-measurement-target-meta">{target.proto}</td>
    <td>{target.src}</td>
    <td className="event-measurement-target-arrow" aria-label="to">→</td>
    <td>{target.dst}</td>
  </>;
}

type EventTargetParts = {
  nic: string;
  vlan: string;
  proto: string;
  src: string;
  dst: string;
  full: string;
};

function measurementTargetParts(event: EventLogItem): EventTargetParts {
  const full = event.targetLabel ?? event.proto ?? event.scope;
  const parts = full.split(/\s*·\s*/).map((part) => part.trim()).filter(Boolean);
  const protoIndex = event.proto
    ? parts.findIndex((part) => part.toLowerCase() === event.proto?.toLowerCase())
    : parts.findIndex((part) => /^(?:RTP|RTCP|SRT|HLS|HTTP|HTTPS|UDP|TCP)$/i.test(part));
  const vlanIndex = parts.findIndex((part) => /^(?:VLAN\s+.+|Untagged|VLAN unknown)$/i.test(part));
  const endpoint = protoIndex >= 0 ? parts.slice(protoIndex + 1).join(" · ") : "";
  const [src, dst] = splitMeasurementEndpoint(endpoint || (protoIndex < 0 ? full : ""));
  return {
    nic: vlanIndex > 0 ? parts[vlanIndex - 1] : protoIndex > 0 ? parts[protoIndex - 1] : event.interfaceId === undefined ? "—" : `if:${event.interfaceId}`,
    vlan: vlanIndex >= 0 ? parts[vlanIndex] : "—",
    proto: event.proto ?? (protoIndex >= 0 ? parts[protoIndex] : "—"),
    src,
    dst,
    full
  };
}

function splitMeasurementEndpoint(endpoint: string): [string, string] {
  const match = endpoint.match(/^(.*?)\s*(?:→|->|↔|<->)\s*(.*?)$/);
  if (match) return [match[1] || "—", match[2] || "—"];
  return [endpoint || "—", "—"];
}

function measurementRowTitle(from: MeasurementAnchor, to: MeasurementAnchor, fromTarget: EventTargetParts, toTarget: EventTargetParts) {
  return `#${from.number} ${formatEventTime(from.event.time)}\n${fromTarget.full}\n\n#${to.number} ${formatEventTime(to.event.time)}\n${toTarget.full}`;
}

function eventDetailRecord(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

function alertDetailRows(event: EventLogItem): Array<[string, string]> {
  if (!["alert_detected", "alert_recovered", "alert_data_unavailable", "alert_data_available"].includes(event.type)) return [];
  const detail = eventDetailRecord(event.detail);
  if (!detail) return [];
  const text = (key: string) => detail[key] === undefined || detail[key] === null ? undefined : String(detail[key]);
  const number = (key: string) => typeof detail[key] === "number" ? String(detail[key]) : text(key);
  const duration = (key: string) => {
    const value = detail[key];
    return typeof value === "number" ? `${value} s` : text(key);
  };
  const rows: Array<[string, string | undefined]> = [
    ["Alert rule", text("alert_id")],
    ["Metric", text("metric")],
    ["Current value", number("value")],
    ["Operator", text("comparison_operator") ?? text("operator")],
    ["Trigger threshold", number("error_threshold") ?? number("threshold")],
    ["Recovery threshold", number("recover_threshold")],
    ["Trigger after", duration("trigger_after_sec")],
    ["Recover after", duration("recover_after_sec")],
    ["Missing after", duration("missing_after_sec")],
    ["Severity", text("severity")]
  ];
  return rows.filter((row): row is [string, string] => row[1] !== undefined);
}

function EventContext({ event, onClose, onSyncTime, onInspect, relatedEvent, relatedOutsideRange = false, onSelectRelated, inline = false }: { event: EventLogItem; onClose: () => void; onSyncTime?: () => void; onInspect?: () => void; relatedEvent?: EventLogItem | null; relatedOutsideRange?: boolean; onSelectRelated?: () => void; inline?: boolean }) {
  const alertRows = alertDetailRows(event);
  return (
    <aside className={`event-context${inline ? " event-context-inline" : ""}`} aria-label="Selected event detail">
      <div className="event-context-header">
        <strong>Event detail</strong>
        <div className="event-context-actions">
          {onSyncTime && <button type="button" className="event-context-sync" onClick={onSyncTime} data-tooltip-key="tooltip.setDashboardTime">Sync time</button>}
          {onInspect && <button type="button" className="event-context-sync" onClick={onInspect}>Inspect</button>}
          <button type="button" onClick={onClose} aria-label="Close event detail" data-tooltip-key="tooltip.closeEventDetail"><Icon name="close" size={16} /></button>
        </div>
      </div>
      <dl>
        <dt>Time</dt><dd>{formatEventTime(event.time)}</dd>
        <dt>Level</dt><dd>{event.level}</dd>
        <dt>Type</dt><dd>{event.type}</dd>
        <dt>Target</dt><dd>{event.targetLabel ?? event.proto ?? event.scope}</dd>
      </dl>
      {alertRows.length > 0 && <dl className="event-context-alert" aria-label="Alert detail">{alertRows.map(([label, value]) => <Fragment key={label}><dt>{label}</dt><dd>{value}</dd></Fragment>)}</dl>}
      {relatedEvent && onSelectRelated && <div className="event-context-related">
        <span>Go to related event</span>
        <button type="button" onClick={onSelectRelated} data-tooltip-key="tooltip.relatedEvent" aria-label={`Go to related event: ${relatedEvent.message} · ${formatEventTime(relatedEvent.time)}`}><span className="event-context-related-message">{relatedEvent.message}</span><time className="event-context-related-time" dateTime={new Date(relatedEvent.time * 1000).toISOString()}>{formatEventTime(relatedEvent.time)}</time></button>
        {relatedOutsideRange && <small>Outside current range</small>}
      </div>}
      <p>{event.message}</p>
      {event.detail !== undefined && <details className="event-context-raw"><summary>Raw event data</summary><pre>{JSON.stringify(event.detail, null, 2)}</pre></details>}
    </aside>
  );
}

function formatDuration(seconds: number) {
  if (seconds < 1) return `${(seconds * 1000).toFixed(1)} ms`;
  if (seconds < 60) return `${seconds.toFixed(3)} s`;
  const minutes = Math.floor(seconds / 60);
  const remaining = seconds - minutes * 60;
  if (minutes < 60) return `${minutes}m ${remaining.toFixed(3)}s`;
  const hours = Math.floor(minutes / 60);
  return `${hours}h ${minutes % 60}m ${remaining.toFixed(3)}s`;
}

function eventRelationEndpoint(event: EventLogItem): EventRelationEndpoint | null {
  if (event.type === "alert_detected" || event.type === "alert_data_unavailable" || event.type.endsWith("_occurred")) return "occurred";
  if (event.type === "alert_recovered" || event.type === "alert_data_available" || event.type.endsWith("_recovered")) return "recovered";
  return null;
}

function eventRelationPairFor(source: EventLogItem | null, related: EventLogItem | null): EventRelationPair | null {
  if (!source || !related) return null;
  const sourceEndpoint = eventRelationEndpoint(source);
  const relatedEndpoint = eventRelationEndpoint(related);
  if (!sourceEndpoint || !relatedEndpoint || sourceEndpoint === relatedEndpoint) return null;
  const occurred = sourceEndpoint === "occurred" ? source : related;
  const recovered = sourceEndpoint === "recovered" ? source : related;
  if (recovered.time < occurred.time) return null;
  return { occurred, recovered, duration: recovered.time - occurred.time };
}

function relationPairMarkers(pair: EventRelationPair | null) {
  const markers = new Map<string, EventRelationMarker>();
  if (!pair) return markers;
  const tooltip = `Occurred → Recovered · ${formatDuration(pair.duration)}`;
  markers.set(pair.occurred.id, { endpoint: "occurred", tooltip });
  markers.set(pair.recovered.id, { endpoint: "recovered", tooltip });
  return markers;
}

function relationContinuationDirection(visible: EventLogItem, other: EventLogItem, sortOrder: EventSortOrder): "top" | "bottom" {
  const otherIsAbove = sortOrder === "desc" ? other.time > visible.time : other.time < visible.time;
  return otherIsAbove ? "top" : "bottom";
}

function relationContinuationTooltip(event: EventLogItem, direction: "top" | "bottom", duration: number) {
  const endpoint = eventRelationEndpoint(event) === "occurred" ? "Occurred" : "Recovered";
  return `${endpoint} is ${direction === "top" ? "above" : "below"} · ${formatDuration(duration)}`;
}

function relationConnectorEqual(current: EventRelationConnectorGeometry | null, next: EventRelationConnectorGeometry) {
  return current !== null && current.width === next.width && current.height === next.height &&
    current.markerX === next.markerX && current.startY === next.startY && current.endY === next.endY &&
    current.continuation === next.continuation && current.continuationTooltip === next.continuationTooltip;
}

function eventRelationFor(event: EventLogItem): EventRelation | null {
  if (event.type === "alert_detected") return { counterpartTypes: ["alert_recovered"], direction: "after" };
  if (event.type === "alert_recovered") return { counterpartTypes: ["alert_detected"], direction: "before" };
  if (event.type === "alert_data_unavailable") return { counterpartTypes: ["alert_data_available"], direction: "after" };
  if (event.type === "alert_data_available") return { counterpartTypes: ["alert_data_unavailable"], direction: "before" };
  const lifecycle = event.type.match(/^(stream|flow)_(detected|recovered|lost)$/);
  if (lifecycle) {
    const [, subject, action] = lifecycle;
    if (action === "lost") return { counterpartTypes: [`${subject}_detected`, `${subject}_recovered`], direction: "before" };
    return { counterpartTypes: [`${subject}_lost`], direction: "after" };
  }
  if (event.type.endsWith("_occurred")) return { counterpartTypes: [`${event.type.slice(0, -"occurred".length)}recovered`], direction: "after" };
  if (event.type.endsWith("_recovered")) return { counterpartTypes: [`${event.type.slice(0, -"recovered".length)}occurred`], direction: "before" };
  return null;
}

function alertStateKey(event: EventLogItem) {
  const detail = eventDetailRecord(event.detail);
  return typeof detail?.state_key === "string" && detail.state_key ? detail.state_key : null;
}

function findRelatedEvent(events: EventLogItem[], source: EventLogItem, relation: EventRelation) {
  return events.reduce<EventLogItem | null>((closest, candidate) => {
    if (candidate.id === source.id || !relation.counterpartTypes.includes(candidate.type) || !sameRelationTarget(source, candidate)) return closest;
    if (relation.direction === "before" ? candidate.time >= source.time : candidate.time <= source.time) return closest;
    if (!closest || Math.abs(candidate.time - source.time) < Math.abs(closest.time - source.time)) return candidate;
    return closest;
  }, null);
}

function sameRelationTarget(source: EventLogItem, candidate: EventLogItem) {
  const sourceStateKey = alertStateKey(source);
  const candidateStateKey = alertStateKey(candidate);
  if (sourceStateKey || candidateStateKey) return Boolean(sourceStateKey && sourceStateKey === candidateStateKey);
  if (source.flowKey || candidate.flowKey) return Boolean(source.flowKey && source.flowKey === candidate.flowKey);
  return Boolean(source.streamKey && source.streamKey === candidate.streamKey);
}

function closestEventWithin(events: EventLogItem[], selectedTimeSec: number | null) {
  if (selectedTimeSec === null) return null;
  return events.reduce<EventLogItem | null>((closest, event) => {
    const distance = Math.abs(event.time - selectedTimeSec);
    if (distance >= 0.5) return closest;
    if (!closest || distance < Math.abs(closest.time - selectedTimeSec)) return event;
    return closest;
  }, null);
}
export function parseEventColumnWidths(value: unknown): EventColumnWidths | undefined {
  let parsed = value;
  if (typeof value === "string") {
    try { parsed = JSON.parse(value); } catch { return undefined; }
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return undefined;
  const candidate = parsed as Partial<EventColumnWidths>;
  if (![candidate.time, candidate.level, candidate.target].every((width) => typeof width === "number" && Number.isFinite(width))) return undefined;
  return normalizeColumnWidths(candidate as EventColumnWidths);
}

function loadStoredColumnWidths() {
  try { return parseEventColumnWidths(window.localStorage.getItem(EVENT_LIST_STORAGE_KEY)) ?? DEFAULT_EVENT_COLUMN_WIDTHS; }
  catch { return DEFAULT_EVENT_COLUMN_WIDTHS; }
}

function normalizeColumnWidths(widths: EventColumnWidths) {
  return {
    time: clamp(widths.time, EVENT_COLUMN_LIMITS.time.min, EVENT_COLUMN_LIMITS.time.max),
    level: clamp(widths.level, EVENT_COLUMN_LIMITS.level.min, EVENT_COLUMN_LIMITS.level.max),
    target: clamp(widths.target, EVENT_COLUMN_LIMITS.target.min, EVENT_COLUMN_LIMITS.target.max)
  };
}

function fitColumnWidths(widths: EventColumnWidths, frameWidth: number): EventColumnWidths {
  if (frameWidth <= 0) return widths;
  const messageMinimum = Math.min(MIN_MESSAGE_COLUMN_PX, Math.max(48, Math.floor(frameWidth * 0.25)));
  const available = Math.max(0, frameWidth - EVENT_ROW_SIDE_PADDING_PX * 2 - EVENT_MARKER_COLUMN_PX - EVENT_COLUMN_GAP_PX * 4 - messageMinimum);
  const minimum = Object.fromEntries((Object.keys(EVENT_COLUMN_LIMITS) as EventColumn[]).map((column) => [column, EVENT_COLUMN_LIMITS[column].min])) as EventColumnWidths;
  const next = { ...widths };
  let excess = next.time + next.level + next.target - available;
  for (const column of ["time", "level", "target"] as EventColumn[]) {
    if (excess <= 0) break;
    const reduction = Math.min(excess, Math.max(0, next[column] - minimum[column]));
    next[column] -= reduction;
    excess -= reduction;
  }
  if (excess <= 0) return next;
  const minimumTotal = minimum.time + minimum.level + minimum.target;
  const scale = minimumTotal > 0 ? available / minimumTotal : 0;
  return { time: minimum.time * scale, level: minimum.level * scale, target: minimum.target * scale };
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, Math.round(value)));
}

function eventColumnText(event: EventLogItem, column: EventColumn) {
  if (column === "time") return formatEventTime(event.time);
  if (column === "level") return event.level;

