const sleep = ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function eventually(fn, timeout=15000) { const until=Date.now()+timeout; let last; while(Date.now()<until) {try{const result=await fn();if(result)return result;}catch(e){last=e;}await sleep(100);}throw last||new Error('condition timed out'); }
async function main() {
  const health = start('/tmp/stm-storage-build/stm_healthd',['--config',config]);
  health.stderr.on('data',b=>process.stderr.write(b));
  const live=path.join(data,'capture-health/live.ndjson');
