  assert.equal(first.storage.filesystems.length,1);
  assert.equal(first.storage.datasets.find(d=>d.id==='capture').file_bytes,2048);
  const df=execFileSync('df',['-B1','--output=size,used,avail,pcent',path.join(data,'capture')],{encoding:'utf8'}).trim().split('\n')[1].trim().split(/\s+/);
  const volume=first.storage.filesystems[0];
  assert.equal(volume.total_bytes,Number(df[0]));
  assert.ok(Math.abs(volume.used_bytes-Number(df[1]))<1024*1024*4);
  assert.ok(Math.abs(volume.available_bytes-Number(df[2]))<1024*1024*4);
  assert.ok(Math.abs(volume.used_percent-Number(df[3].replace('%','')))<1.1);
  console.log('Live collector matches df and groups four datasets; fixture:',root);
  const server=start('node',[path.join(repo,'fe/server/dist/index.js'),'--host=127.0.0.1','--port=32193',`--log-dir=${data}`,`--state-dir=${root}/state`,`--stm-config-file=${config}`,`--locales-dir=${repo}/fe/locales`],{cwd:path.join(repo,'fe')});
  let serverLog=''; server.stderr.on('data',b=>{serverLog+=b;}); server.stdout.on('data',b=>{serverLog+=b;});
  const origin='http://127.0.0.1:32193';
  await eventually(async()=>{const r=await fetch(origin+'/api/capture-health');return r.ok&&(await r.json()).storage?.filesystems.length;});
  const ws=new WebSocket('ws://127.0.0.1:32193/ws');
  const wsSnapshot=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('websocket snapshot timeout')),10000);ws.on('message',b=>{const m=JSON.parse(b);if(m.type==='snapshot'&&m.captureHealth?.storage){clearTimeout(timer);resolve(m);}});ws.on('error',reject);});
  assert.equal(wsSnapshot.captureHealth.storage.datasets.length,4);ws.close();
  console.log('HTTP and WebSocket snapshot include storage');
  const chrome=start('/root/.cache/puppeteer/chrome/linux-138.0.7204.157/chrome-linux64/chrome',['--headless','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--remote-debugging-port=0',`--user-data-dir=${root}/chrome`,'about:blank']);
  let chromeLog=''; chrome.stderr.on('data',b=>{chromeLog+=b;});
  const debug=await eventually(()=>chromeLog.match(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)/)?.[1]);
  const tab=await(await fetch(`http://127.0.0.1:${debug}/json/new?${encodeURIComponent(origin)}`,{method:'PUT'})).json();
  const cdp=new WebSocket(tab.webSocketDebuggerUrl);await once(cdp,'open');
  let sequence=0;const pending=new Map();const errors=[];
  cdp.on('message',b=>{const m=JSON.parse(b);if(m.id){const task=pending.get(m.id);pending.delete(m.id);if(m.error)task.reject(new Error(JSON.stringify(m.error)));else task.resolve(m.result);}if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);});
  const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});cdp.send(JSON.stringify({id,method,params}));});
  const evaluate=async expression=>{const result=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(result.exceptionDetails)throw new Error(JSON.stringify(result.exceptionDetails));return result.result.value;};
  await call('Runtime.enable');await call('Page.enable');
  for(const locale of ['en','ja']) {
    await eventually(()=>evaluate('Boolean(document.querySelector(".menu-rail-nav"))'));
    await evaluate(`localStorage.setItem('stm-locale',${JSON.stringify(locale)})`);
    await call('Page.reload');
    const label=locale==='en'?'Capture Health':'キャプチャ健全性';
    await eventually(()=>evaluate(`Boolean(document.querySelector('.menu-item[data-tooltip=${JSON.stringify(label)}]'))`));
    await evaluate(`document.querySelector('.menu-item[data-tooltip=${JSON.stringify(label)}]').click()`);
    await eventually(()=>evaluate('Boolean(document.querySelector(".capture-health-storage progress"))'));
    for(const [width,height] of [[1440,1000],[390,844]]) {
      await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});await sleep(200);
      const layout=await evaluate(`(()=>{const e=document.querySelector('.capture-health-storage');return {overflow:e.scrollWidth-e.clientWidth,clipped:e.scrollHeight-e.clientHeight,bars:e.querySelectorAll('progress').length,rows:e.querySelectorAll('.capture-health-storage-dataset').length,text:e.innerText};})()`);
      assert.ok(layout.overflow<=1,`storage overflow at ${width}: ${layout.overflow}`);assert.ok(layout.clipped<=1,`storage vertically clipped at ${width}: ${layout.clipped}`);assert.equal(layout.bars,1);assert.equal(layout.rows,4);assert.ok(!layout.text.includes('[captureHealth.'));assert.ok(layout.text.includes('2.0 KiB'));
      await evaluate('document.querySelector(".capture-health-storage").scrollIntoView({block:"start"})');
      const screenshot=await call('Page.captureScreenshot',{format:'png'});fs.writeFileSync(path.join(root,`storage-${locale}-${width}.png`),Buffer.from(screenshot.data,'base64'));
      console.log(`Browser ${locale} ${width}px: one volume, four datasets, no overflow`);
    }
  }
  let newer = first;
  if (!process.env.STORAGE_UI_ONLY) {
  // Stress the dataset scan while checking that live health updates keep arriving.
  for(let i=0;i<20000;i++)fs.writeFileSync(path.join(data,'capture',`stress-${i}.pcap`),'x');
  const refreshed=await eventually(()=>{const s=JSON.parse(fs.readFileSync(live));return s.storage.datasets.find(d=>d.id==='capture').file_bytes===22048?s:null;},75000);
  assert.ok(refreshed.storage.filesystems[0].observed_at>first.storage.filesystems[0].observed_at);
  newer=await eventually(()=>{const s=JSON.parse(fs.readFileSync(live));return s.observed_at>refreshed.observed_at?s:null;},4000);
  assert.ok(newer.observed_at-refreshed.observed_at<3);
  console.log('60-second dataset refresh counted 20,000 files; filesystem refreshed and 1-second health updates continued');
  }
  health.kill('SIGTERM');await once(health,'exit');await sleep(6500);
  await eventually(()=>evaluate('document.querySelector(".capture-health-storage").innerText.includes("計測結果が古くなっています")'));
  console.log('Browser marks storage stale after collector stops');
  assert.deepEqual(errors,[]);
  const old={...newer,observed_at:Date.now()/1000};delete old.storage;
  fs.writeFileSync(live+'.new',JSON.stringify(old)+'\n');fs.renameSync(live+'.new',live);
  await eventually(()=>evaluate('document.querySelector(".capture-health-storage").innerText.includes("ストレージ情報が提供されていません")'));
  console.log('Browser handles legacy snapshot without storage');
  cdp.close();
  fs.writeFileSync(path.join(root,'result.json'),JSON.stringify({root,screenshots:['storage-en-1440.png','storage-en-390.png','storage-ja-1440.png','storage-ja-390.png'],checks:'df, HTTP, WebSocket, browser languages and widths, periodic refresh, stress, stopped collector, legacy snapshot'},null,2));
}
