  padding: 0 7px;
  font-size: var(--font-size-xs);
}

.event-measurement {
  max-height: 164px;
  padding: var(--space-1) var(--space-2);
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--warning-soft) 34%, var(--surface));
  overflow: auto;
  font-size: var(--font-size-xs);
}

.event-measurement-summary {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
}

.event-measurement-summary strong {
  color: var(--text-strong);
}

.event-measurement-summary span {
  min-width: 0;
  overflow: hidden;
  color: var(--muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.event-measurement-summary button {
  margin-left: auto;
  min-height: 22px;
  padding: 0 var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  font-size: var(--font-size-xs);
}
