// Browser regression checks for the guide, including the 8,000-row scroll path.
// node --test fe/tests/events-guide.test.cjs
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { spawn } = require('node:child_process');
const { once } = require('node:events');
const esbuild = require('../server/node_modules/esbuild');
const WebSocket = require('../node_modules/ws');
const repo = path.resolve(__dirname, '../..');
const chromePath = process.env.CHROME_PATH || '/root/.cache/puppeteer/chrome/linux-138.0.7204.157/chrome-linux64/chrome';
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

test('Events guide retains offscreen pairs and navigates without selecting or time synchronization', { timeout: 60000 }, async t => {
  if (!fs.existsSync(chromePath)) return t.skip('Set CHROME_PATH to a Chromium executable');
  const fixture = `
    import React, { useState } from 'react';
    import { createRoot } from 'react-dom/client';
    import { EventLog } from './client/src/components/EventLog';
    const time = 1700000000;
    window.syncCalls = 0; window.selectionCalls = 0; window.rowRenders = 0; window.logRenders = 0;
    function Fixture() {
      const [config, setConfig] = useState({occurred:200,recovered:100,count:8000,sort:'desc',inline:false});
      window.configure = patch => setConfig(current => ({...current,...patch}));
      const events = React.useMemo(() => Array.from({length:config.count}, (_,i) => ({
        id:'event-'+i,time:time+config.count-i,type:i===config.occurred?'packet_loss_occurred':i===config.recovered?'packet_loss_recovered':'test',
        streamKey:'stream',scope:'stream',level:'info',message:'Event '+i,targetLabel:'NIC · VLAN · RTP · src → dst'
      })),[config.occurred,config.recovered,config.count]);
      return <EventLog events={events} eventsRange='all' onChangeEventsRange={()=>{}}
        selectedStreamKey={null} selectedFlowKey={null} selectedInterfaceId={null}
        selectedEvent={events[config.occurred]} onSelectEvent={()=>window.selectionCalls++}
        onSelectTime={()=>window.syncCalls++} sortOrder={config.sort} query={config.query||''}
        detailPresentation={config.inline?'inline':'panel'} />;
    }
    createRoot(document.getElementById('root')).render(<Fixture/>);
  `;
  const bundle = await esbuild.build({ stdin: { contents: fixture, resolveDir: path.join(repo,'fe'), loader:'tsx' },
    bundle:true, write:false, platform:'browser', jsx:'automatic', plugins:[{name:'count-renders',setup(build){
      build.onLoad({filter:/EventLog\.tsx$/},args=>({loader:'tsx',contents:fs.readFileSync(args.path,'utf8')
        .replace('  const [internalTab,', '  window.logRenders++;\n  const [internalTab,')
        .replace('  const timeLabel = formatEventTime(event.time);','  window.rowRenders++;\n  const timeLabel = formatEventTime(event.time);')}));
    }}] });
  const css = fs.readFileSync(path.join(repo,'fe/client/src/styles/events.css'),'utf8');
  const server = http.createServer((req,res) => {
    if (req.url === '/fixture.js') {res.setHeader('Content-Type','application/javascript');res.end(bundle.outputFiles[0].text);return;}
    res.setHeader('Content-Type','text/html');res.end(`<html><head><style>
      :root { --pane-header-height:32px; --space-1:4px; --space-2:8px; --accent:#5599ee; --accent-border:#5599ee; --surface:#101820; --surface-muted:#1c2834; --text:#eee; --muted:#aaa; --warning:#ffbb44; --success:#44ddaa; --line:#444; }
      * {box-sizing:border-box} body {margin:0;background:#101820;color:#eee} #root {height:600px}
      .events-card {height:100%;min-height:0} .event-row {display:grid;width:100%;align-items:center;text-align:left} ${css}
    </style></head><body><div id='root'></div><script src='/fixture.js'></script></body></html>`);
  });
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const chrome = spawn(chromePath,['--headless','--no-sandbox','--disable-dev-shm-usage','--remote-debugging-port=0','about:blank'],{stdio:['ignore','ignore','pipe']});
  let log='';chrome.stderr.on('data',b=>log+=b);
  let socket;
  try {
    for(let i=0;i<100 && !log.includes('DevTools listening');i++) await sleep(50);
    const port=log.match(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)/)?.[1];
    assert.ok(port,'Chromium must start');
    const tab=await(await fetch(`http://127.0.0.1:${port}/json/new?http://127.0.0.1:${server.address().port}`,{method:'PUT'})).json();
    socket=new WebSocket(tab.webSocketDebuggerUrl);await once(socket,'open');
    let seq=0;const pending=new Map();const errors=[];
    socket.on('message',b=>{const m=JSON.parse(b);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}if(m.method==='Runtime.exceptionThrown')errors.push(m.params);});
    const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;pending.set(id,{resolve,reject});socket.send(JSON.stringify({id,method,params}));});
    const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});assert.ok(!r.exceptionDetails,JSON.stringify(r.exceptionDetails));return r.result.value;};
    await call('Runtime.enable');
    const wait=async expression=>{for(let i=0;i<100;i++){if(await evaluate(expression))return;await sleep(50);}assert.fail(expression);};
    await wait('document.querySelectorAll(".event-row").length===8000 && !!document.querySelector(".event-relation-endpoint")');
    const scroll=async index=>{await evaluate(`(()=>{const list=document.querySelector('.events-list');const row=document.querySelectorAll('.event-row')[${index}];list.scrollTop+=row.getBoundingClientRect().top-list.getBoundingClientRect().top-list.clientHeight/2;})()`);await sleep(100);};
    const guide=()=>evaluate(`({path:document.querySelector('.event-relation-connector-line')?.getAttribute('d')||'',top:document.querySelector('.event-relation-edge-group.top')?.innerText||'',bottom:document.querySelector('.event-relation-edge-group.bottom')?.innerText||''})`);
    await scroll(150);
    let g=await guide();assert.ok(g.path);assert.match(g.top,/Recovered/);assert.match(g.bottom,/Occurred/);
    const artifacts=fs.mkdtempSync('/tmp/stm-events-guide-');
    fs.writeFileSync(path.join(artifacts,'guide-wide.png'),Buffer.from((await call('Page.captureScreenshot',{format:'png'})).data,'base64'));
    t.diagnostic(`Screenshots: ${artifacts}`);
    const before=await evaluate('({row:rowRenders,log:logRenders,selection:selectionCalls,sync:syncCalls})');
    for(const index of [145,155,149,151]) await scroll(index);
    const after=await evaluate('({row:rowRenders,log:logRenders,selection:selectionCalls,sync:syncCalls})');
    assert.deepEqual(after,before,'Guide scrolling must not render the list or synchronize time');
    await scroll(250);g=await guide();assert.equal(g.path,'');assert.match(g.top,/Pair/);assert.match(g.top,/Occurred/);assert.match(g.top,/Recovered/);
    await scroll(50);g=await guide();assert.equal(g.path,'');assert.match(g.bottom,/Pair/);
    await evaluate("document.querySelector('.event-relation-edge-group.bottom button.occurred').click()");await sleep(100);
    assert.deepEqual(await evaluate('({selection:selectionCalls,sync:syncCalls})'),{selection:0,sync:0});
    assert.ok(await evaluate(`(()=>{const row=document.activeElement;const list=document.querySelector('.events-list');return row.classList.contains('event-row')&&row.getBoundingClientRect().top>=list.getBoundingClientRect().top&&row.getBoundingClientRect().bottom<=list.getBoundingClientRect().bottom})()`));
    g=await guide();assert.ok(g.path);assert.match(g.top,/Recovered/);assert.equal(g.bottom,'');
    await evaluate("configure({occurred:102,recovered:100})");
    await wait("document.querySelector('.event-primary-selected .event-message')?.textContent==='Event 102' && document.querySelectorAll('.event-relation-endpoint').length===2");
    await scroll(101);
    g=await guide();assert.ok(g.path, JSON.stringify({g,layout:await evaluate(`(()=>{const l=document.querySelector('.events-list');return {height:l.clientHeight,scroll:l.scrollTop,markers:Array.from(document.querySelectorAll('.event-relation-endpoint')).map(e=>({text:e.parentElement.parentElement.innerText,top:e.getBoundingClientRect().top,listTop:l.getBoundingClientRect().top}))}})()`)}));assert.equal(g.top,'');assert.equal(g.bottom,'');
    assert.ok(await evaluate(`(()=>{const path=document.querySelector('.event-relation-connector-line');const marker=document.querySelector('.event-relation-endpoint');const frame=document.querySelector('.events-list-frame');const b=marker.getBoundingClientRect();return Math.abs(Number(path.getAttribute('d').split(' ')[1])-(b.left+b.width/2-frame.getBoundingClientRect().left))<1})()`),'Line must meet marker center');
    await evaluate("configure({occurred:200,recovered:100,sort:'asc',inline:true})");
    await wait("document.querySelector('.event-primary-selected .event-message')?.textContent==='Event 200' && document.querySelectorAll('.event-relation-endpoint').length===2 && !!document.querySelector('.event-context-inline')");
    await scroll(7850);
    g=await guide();assert.ok(g.path);assert.match(g.top,/Occurred/);assert.match(g.bottom,/Recovered/);
    await call('Emulation.setDeviceMetricsOverride',{width:390,height:700,deviceScaleFactor:1,mobile:false});await sleep(100);
    assert.ok(await evaluate(`Array.from(document.querySelectorAll('.event-relation-edge-group')).every(e=>e.getBoundingClientRect().right<=document.querySelector('.events-list-frame').getBoundingClientRect().right)`));
    fs.writeFileSync(path.join(artifacts,'guide-narrow.png'),Buffer.from((await call('Page.captureScreenshot',{format:'png'})).data,'base64'));
    await evaluate("configure({count:8010,occurred:8005,recovered:100,sort:'desc',inline:false})");
    await wait("document.querySelector('.event-context p')?.textContent==='Event 8005' && !document.querySelector('.event-context-inline') && document.querySelectorAll('.event-relation-endpoint').length===1");
    await scroll(150);
    g=await guide();assert.match(g.bottom,/Occurred/);
    await evaluate("document.querySelector('.event-relation-edge-group.bottom button.occurred').click()");await sleep(150);
    await wait("document.activeElement.querySelector('.event-message')?.textContent==='Event 8005'");
    assert.deepEqual(await evaluate('({selection:selectionCalls,sync:syncCalls})'),{selection:0,sync:0});
    await evaluate("configure({query:'Event 150'})");
    await wait("!!document.querySelector('.event-related-boundary') && document.querySelectorAll('.event-relation-endpoint').length===1");
    await wait("!!document.querySelector('.event-relation-edge-group.bottom button.occurred')");
    await evaluate("document.querySelector('.event-relation-edge-group.bottom button.occurred').click()");
    await wait("document.activeElement.querySelector('.event-message')?.textContent==='Event 8005'");
    assert.deepEqual(await evaluate('({selection:selectionCalls,sync:syncCalls,query:document.querySelector(".event-search input")?.value||document.querySelector("input")?.value})'),{selection:0,sync:0,query:'Event 150'});
    assert.deepEqual(errors,[]);
  } finally {
    socket?.close();chrome.kill('SIGTERM');await new Promise(resolve=>server.close(resolve));
  }
});

