const esbuild = require('../server/node_modules/esbuild');
const WebSocket = require('../node_modules/ws');
const repo = path.resolve(__dirname, '../..');
const chromePath = process.env.CHROME_PATH || '/root/.cache/puppeteer/chrome/linux-138.0.7204.157/chrome-linux64/chrome';
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

test('Events deselection preserves shared time, anchors, scroll and keyboard navigation', { timeout: 120000 }, async t => {
  if (!fs.existsSync(chromePath)) return t.skip('Set CHROME_PATH to a Chromium executable');
  const fixture = `
    import React, {useEffect,useMemo,useState} from 'react';
    import {createRoot} from 'react-dom/client';
    import {EventLog} from './client/src/components/EventLog';
    window.syncCalls=0; window.selectionCalls=[]; window.globalEscapes=0; window.inspectorEscapes=0; window.historyRequests=0;
    function Fixture(){
      const [config,setConfig]=useState({count:500,sort:'desc',inline:false,omitRecovered:false});
      const [selected,setSelected]=useState(null);
      const [time,setTime]=useState(null);
      const [sync,setSync]=useState(false);
      const [queries,setQueries]=useState(['','']);
      const events=useMemo(()=>Array.from({length:config.count},(_,i)=>({id:'event-'+i,time:1700000000+config.count-i/10,
        type:i===200?'packet_loss_occurred':i===100?'packet_loss_recovered':'test',streamKey:'stream',scope:'stream',
        level:'info',message:'Event '+i,targetLabel:'NIC · VLAN · RTP · src → dst'})),[config.count]);
      window.configure=patch=>setConfig(current=>({...current,...patch}));
      window.enableSync=setSync;
      window.setQuery=(index,query)=>setQueries(current=>current.map((value,i)=>i===index?query:value));
      window.externalSelect=id=>setSelected(events.find(event=>event.id===id)||null);
      window.externalTime=value=>{setSelected(null);setTime(value)};
      window.state={selected:selected?.id||null,time,sync,queries,config};
      window.fetch=()=>{window.historyRequests++;const result=events[100];return new Promise(resolve=>setTimeout(()=>resolve({ok:true,json:async()=>[result]}),400));};
      useEffect(()=>{
        const global=e=>{if(e.key==='Escape'){window.globalEscapes++;setSync(false)}};
        const inspector=e=>{if(e.key==='Escape')window.inspectorEscapes++};
        window.addEventListener('keydown',global);document.addEventListener('keydown',inspector);
        return ()=>{window.removeEventListener('keydown',global);document.removeEventListener('keydown',inspector)};
      },[]);
      return <main>{[0,1].map(index=><div className='cell' data-cell={index} key={index}>
        <EventLog events={config.omitRecovered?events.filter(event=>event.id!=='event-100'):events}
          eventsRange='all' onChangeEventsRange={()=>{}} selectedStreamKey={null} selectedFlowKey={null} selectedInterfaceId={null}
          selectedEvent={selected} onSelectEvent={event=>{window.selectionCalls.push(event?.id||null);setSelected(event)}}
          selectedTimeSec={time} onSelectTime={value=>{window.syncCalls++;setSelected(null);setTime(value)}} syncTimeOnRowClick={sync}
          sortOrder={config.sort} query={queries[index]} onChangeQuery={value=>window.setQuery(index,value)}
          detailPresentation={config.inline?'inline':'panel'}/>
      </div>)}</main>;
    }
    createRoot(document.getElementById('root')).render(<Fixture/>);
  `;
  const bundle = await esbuild.build({ stdin:{contents:fixture,resolveDir:path.join(repo,'fe'),loader:'tsx'},
    bundle:true,write:false,platform:'browser',jsx:'automatic' });
  const css = fs.readFileSync(path.join(repo,'fe/client/src/styles/events.css'),'utf8');
  const server = http.createServer((req,res)=>{
    if(req.url==='/fixture.js'){res.setHeader('Content-Type','application/javascript');res.end(bundle.outputFiles[0].text);return;}
    res.setHeader('Content-Type','text/html');res.end(`<html><head><style>
      :root{--pane-header-height:32px;--space-1:4px;--space-2:8px;--accent:#5599ee;--accent-soft:#193c62;--accent-border:#5599ee;--surface:#101820;--surface-muted:#1c2834;--text:#eee;--text-strong:#fff;--muted:#aaa;--warning:#ffbb44;--warning-soft:#403218;--success:#44ddaa;--line:#444}
      *{box-sizing:border-box}body{margin:0;background:#101820;color:#eee}main{display:flex;gap:8px}.cell{width:calc(50vw - 4px);height:600px;min-width:0}
      .events-card{height:100%;min-height:0}.event-row{display:grid;width:100%;align-items:center;text-align:left}${css}
    </style></head><body><div id='root'></div><script src='/fixture.js'></script></body></html>`);
  });
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const chrome=spawn(chromePath,['--headless','--no-sandbox','--disable-dev-shm-usage','--remote-debugging-port=0','about:blank'],{stdio:['ignore','ignore','pipe']});
  let log='';chrome.stderr.on('data',buffer=>log+=buffer);
  let socket;
  try{
    for(let i=0;i<100&&!log.includes('DevTools listening');i++)await sleep(50);
    const port=log.match(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)/)?.[1];assert.ok(port,'Chromium must start');
    const tab=await(await fetch(`http://127.0.0.1:${port}/json/new?http://127.0.0.1:${server.address().port}`,{method:'PUT'})).json();
    socket=new WebSocket(tab.webSocketDebuggerUrl);await once(socket,'open');
    let seq=0;const pending=new Map();const errors=[];
    socket.on('message',buffer=>{const message=JSON.parse(buffer);if(message.id){const p=pending.get(message.id);pending.delete(message.id);message.error?p.reject(message.error):p.resolve(message.result);}if(message.method==='Runtime.exceptionThrown')errors.push(message.params);});
    const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;pending.set(id,{resolve,reject});socket.send(JSON.stringify({id,method,params}));});
    const evaluate=async expression=>{const result=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});assert.ok(!result.exceptionDetails,JSON.stringify(result.exceptionDetails));return result.result.value;};
    const wait=async expression=>{for(let i=0;i<100;i++){if(await evaluate(expression))return;await sleep(50);}assert.fail(expression);};
    const cell=index=>`document.querySelector('[data-cell="${index}"]')`;
    const row=(index,id)=>`${cell(index)}.querySelector('[data-event-id="event-${id}"]')`;
    const click=async(index,id)=>{await evaluate(`${row(index,id)}.focus({preventScroll:true});${row(index,id)}.click()`);await sleep(80);};
    const key=async(key,code=key,virtualKey=27)=>{await call('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:virtualKey});await call('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:virtualKey});await sleep(80);};
    const scroll=async(index,id)=>{await evaluate(`(()=>{const list=${cell(index)}.querySelector('.events-list');const row=${row(index,id)};list.scrollTop+=row.getBoundingClientRect().top-list.getBoundingClientRect().top-list.clientHeight/2})()`);await sleep(80);};
    const position=(index,id)=>evaluate(`${row(index,id)}.getBoundingClientRect().top-${cell(index)}.querySelector('.events-list').getBoundingClientRect().top`);
    const cleared=()=>wait(`state.selected===null&&!document.querySelector('.event-context')&&!document.querySelector('.event-primary-selected')&&!document.querySelector('.event-related')&&!document.querySelector('.event-relation-endpoint')&&!document.querySelector('.event-relation-connector')&&!document.querySelector('.event-relation-edge-group')&&!document.querySelector('.event-related-boundary')`);
    await call('Runtime.enable');await call('Emulation.setDeviceMetricsOverride',{width:1400,height:700,deviceScaleFactor:1,mobile:false});
    await wait("document.querySelectorAll('.event-row').length===1000");

    // Shared selection + local measurement anchors + a preserved synchronized timestamp.
    await evaluate('enableSync(true)');await click(0,200);
    await wait("document.querySelectorAll('.event-context').length===2&&document.querySelectorAll('.event-relation-endpoint').length===4");
    await evaluate(`${row(0,200)}.dispatchEvent(new MouseEvent('click',{bubbles:true,shiftKey:true}));${row(0,210)}.dispatchEvent(new MouseEvent('click',{bubbles:true,shiftKey:true}))`);
    await wait("document.querySelectorAll('.event-measurement-anchor').length===2");
    const saved=await evaluate('({time:state.time,syncCalls,selectionCalls:selectionCalls.length})');
    await scroll(0,200);await scroll(1,220);
    const before=[await position(0,200),await position(1,220)];
    await click(0,200);await cleared();
    assert.deepEqual(await evaluate('({time:state.time,sync:state.sync,syncCalls,selectionCalls:selectionCalls.length})'),{time:saved.time,sync:true,syncCalls:saved.syncCalls,selectionCalls:saved.selectionCalls+1});
    assert.equal(await evaluate("document.querySelectorAll('.event-measurement-anchor').length"),2);
    assert.equal(await evaluate("document.querySelectorAll('.event-measurement-table tbody tr').length"),1);
    assert.ok(await evaluate(`${row(0,200)}.classList.contains('time-neighbor')`));
    for(const [index,id] of [[0,200],[1,220]])assert.ok(Math.abs(await position(index,id)-before[index])<1,'Shared deselection preserves each cell position');
    assert.equal(await evaluate("document.activeElement.dataset.eventId"),'event-200');
    await key('ArrowDown','ArrowDown',40);await wait("state.selected==='event-201'");
    assert.equal(await evaluate('syncCalls'),saved.syncCalls+1);

    // Esc is consumed before document/window handlers, but the next Esc keeps legacy behavior.
    await key('Escape');await cleared();
    assert.deepEqual(await evaluate('({sync:state.sync,global:globalEscapes,inspector:inspectorEscapes})'),{sync:true,global:0,inspector:0});
    await key('Escape');assert.deepEqual(await evaluate('({sync:state.sync,global:globalEscapes,inspector:inspectorEscapes})'),{sync:false,global:1,inspector:1});

    // Search/editing and dialogs do not use the row-selection Escape shortcut.
    await click(0,200);await evaluate(`${cell(0)}.querySelector('input').focus()`);await key('Escape');
    assert.equal(await evaluate('state.selected'),'event-200');
    await evaluate(`(()=>{const detail=${cell(0)}.querySelector('.event-context');detail.setAttribute('role','dialog');detail.querySelector('button').focus()})()`);await key('Escape');
    assert.equal(await evaluate('state.selected'),'event-200');
    await evaluate(`${cell(0)}.querySelector('.event-context').removeAttribute('role')`);

    // X restores row focus; ArrowUp resumes from it with time synchronization disabled.
    const noSyncCalls=await evaluate('syncCalls');
    await scroll(0,200);
    await evaluate(`(()=>{const button=${cell(0)}.querySelector('[data-tooltip-key="tooltip.closeEventDetail"]');button.focus();button.click()})()`);await cleared();
    assert.equal(await evaluate('document.activeElement.dataset.eventId'),'event-200');
    await key('ArrowUp','ArrowUp',38);await wait("state.selected==='event-199'");assert.equal(await evaluate('syncCalls'),noSyncCalls);
    await evaluate('externalSelect(null)');await cleared();

    // Inline details above the viewport: closing must not move visible normal rows.
    await evaluate('configure({inline:true})');await click(0,200);
    await wait("document.querySelectorAll('.event-context-inline').length===2");
    for(const sort of ['desc','asc']){
      await evaluate(`configure({sort:'${sort}'})`);await sleep(100);
      await scroll(0,220);await scroll(1,240);
      const positions=[await position(0,220),await position(1,240)];
      await evaluate('externalSelect(null)');await cleared();
      for(const [index,id]of[[0,220],[1,240]])assert.ok(Math.abs(await position(index,id)-positions[index])<1,`Inline ${sort} position: cell ${index}`);
      await click(0,200);await wait("document.querySelectorAll('.event-context-inline').length===2");
    }

    // Narrow dashboard cells with search filtering and temporary related boundary rows.
    await call('Emulation.setDeviceMetricsOverride',{width:790,height:700,deviceScaleFactor:1,mobile:false});
    await evaluate("configure({sort:'desc'});setQuery(0,'Event 200');setQuery(1,'Event 220')");
    await wait("document.querySelectorAll('.event-related-boundary').length===2");
    await evaluate(`(()=>{const button=${cell(0)}.querySelector('.event-context-related button');button.focus();button.click()})()`);
    await wait("state.selected==='event-100'&&!!document.querySelector('.event-context-inline')");
    await evaluate(`(()=>{const button=${cell(0)}.querySelector('[data-tooltip-key="tooltip.closeEventDetail"]');button.focus();button.click()})()`);await cleared();
    assert.deepEqual(await evaluate('state.queries'),['Event 200','Event 220']);
    assert.equal(await evaluate(`${cell(0)}.querySelectorAll('.event-row').length`),1);
    assert.equal(await evaluate('document.activeElement.dataset.eventId'),'event-200');
    assert.equal(await evaluate("document.querySelectorAll('.event-measurement-anchor').length"),1,'Filtered anchors remain stored');
    await evaluate("setQuery(0,'');setQuery(1,'')");await wait("document.querySelectorAll('.event-measurement-anchor').length===2");

    // An external time change still scrolls; deselection must not suppress Timeline navigation.
    await scroll(0,20);await evaluate('externalSelect("event-200")');await sleep(80);
    await evaluate('externalTime(1700000000+500-40)');await cleared();await sleep(100);
    assert.ok(await evaluate(`(()=>{const b=${row(0,400)}.getBoundingClientRect();const l=${cell(0)}.querySelector('.events-list').getBoundingClientRect();return b.top>=l.top&&b.bottom<=l.bottom})()`));
    assert.ok(await evaluate(`${row(0,400)}.classList.contains('time-neighbor')`));

    // A delayed related-event response cannot resurrect the deselected pair.
    await evaluate('configure({omitRecovered:true})');await click(0,200);
    await wait('historyRequests>=2');await key('Escape');await cleared();await sleep(650);await cleared();

    // Live data updates after release do not jump back to the retained synchronized timestamp.
    await evaluate('configure({omitRecovered:false,inline:false})');await sleep(80);
    await evaluate('enableSync(true)');await click(0,200);await scroll(0,300);await scroll(1,320);
    await evaluate('externalSelect(null)');await cleared();
    await evaluate('configure({count:501})');await sleep(150);
    assert.ok(await position(0,300)>0&&await position(0,300)<600,'Data update must not scroll back to time focus');

    const artifacts=fs.mkdtempSync('/tmp/stm-events-selection-');
    fs.writeFileSync(path.join(artifacts,'deselected-narrow.png'),Buffer.from((await call('Page.captureScreenshot',{format:'png'})).data,'base64'));
    t.diagnostic(`Screenshot: ${artifacts}`);
    assert.deepEqual(errors,[]);
  }finally{
    socket?.close();chrome.kill('SIGTERM');await new Promise(resolve=>server.close(resolve));
  }
});

