  const normalizedQuery = query.trim();
  if (!normalizedQuery) return true;

  const haystack = parts
    .filter((part): part is string | number => part !== undefined && part !== null)
    .join(" ");

  const regex = parseRegexQuery(normalizedQuery);
  if (regex) return regex.test(haystack);

  if (isRegexLike(normalizedQuery)) return false;

  const terms = normalizedQuery
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean);

  const lowerHaystack = haystack.toLowerCase();
  return terms.every((term) => lowerHaystack.includes(term));
}

function parseRegexQuery(query: string) {
  const match = query.match(/^\/(.+)\/([imu]*)$/);
  if (!match) return undefined;

  try {
    return new RegExp(match[1], match[2]);
  } catch {
    return undefined;
  }
}

function isRegexLike(query: string) {
  return query.startsWith("/") && query.lastIndexOf("/") > 0;
}
