// node --test fe/tests/events-detail.test.cjs
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { spawn } = require('node:child_process');
const { once } = require('node:events');
const esbuild = require('../server/node_modules/esbuild');
const WebSocket = require('../node_modules/ws');
const repo = path.resolve(__dirname, '../..');
const chromePath = process.env.CHROME_PATH || '/root/.cache/puppeteer/chrome/linux-138.0.7204.157/chrome-linux64/chrome';
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

test('Event detail preserves raw toggles, compact actions and sticky controls', { timeout: 60000 }, async t => {
  if (!fs.existsSync(chromePath)) return t.skip('Set CHROME_PATH to a Chromium executable');
  const fixture = `
    import React, {useState} from 'react';
    import {createRoot} from 'react-dom/client';
    import {EventLog} from './client/src/components/EventLog';
    import {I18nProvider, useI18n} from './client/src/i18n';
    import {TooltipProvider} from './client/src/components/ui/TooltipProvider';
    window.syncCalls=[]; window.inspectCalls=[];
    const initial=Array.from({length:30},(_,i)=>({id:'event-'+i,time:1700000000+i,
      type:i===10?'flow_detected':i===20?'flow_lost':'test',streamKey:'stream',flowKey:'flow',
      scope:'flow',level:'info',message:'Event '+i,targetLabel:'NIC · VLAN · RTP · source → destination',
      detail:{version:0,payload:Array.from({length:40},(_,j)=>'Raw data line '+j)}}));
    function Fixture(){
      const [events,setEvents]=useState(initial);
      const [selected,setSelected]=useState(initial[10]);
      const [config,setConfig]=useState({inline:false,sync:false,actions:true,hideRelated:false});
      const {setLocale}=useI18n();
      window.configure=patch=>setConfig(current=>({...current,...patch}));
      window.select=id=>setSelected(events.find(event=>event.id===id)||null);
      window.updateRaw=()=>{const next=events.map(event=>event.id===selected?.id?{...event,detail:{...event.detail,version:1}}:event);setEvents(next);setSelected(next.find(event=>event.id===selected?.id)||null)};
      window.changeLocale=setLocale;
      window.state={selected:selected?.id,timeCalls:window.syncCalls.length,config};
      return <div className={'fixture '+(config.inline?'':'standalone-events')}>
        <EventLog events={config.hideRelated?events.filter(event=>event.id!=='event-20'):events}
          selectedEvent={selected} onSelectEvent={setSelected} eventsRange='all' onChangeEventsRange={()=>{}}
          selectedStreamKey={null} selectedFlowKey={null} selectedInterfaceId={null}
          detailPresentation={config.inline?'inline':'panel'} syncTimeOnRowClick={config.sync}
          onSelectTime={time=>window.syncCalls.push(time)}
          onSyncTime={config.actions?time=>window.syncCalls.push(time):undefined}
          onInspectTarget={config.actions?event=>window.inspectCalls.push(event.id):undefined}/>
      </div>;
    }
    createRoot(document.getElementById('root')).render(<I18nProvider><TooltipProvider delayMs={0}><Fixture/></TooltipProvider></I18nProvider>);
  `;
  const bundle = await esbuild.build({stdin:{contents:fixture,resolveDir:path.join(repo,'fe'),loader:'tsx'},bundle:true,write:false,platform:'browser',jsx:'automatic'});
  const css = fs.readFileSync(path.join(repo,'fe/client/src/styles/events.css'),'utf8');
  const tooltipCss = fs.readFileSync(path.join(repo,'fe/client/src/styles/tooltip.css'),'utf8');
  const strings = fs.readFileSync(path.join(repo,'fe/locales/strings.json'),'utf8');
  const server = http.createServer((req,res)=>{
    if(req.url==='/fixture.js'){res.setHeader('Content-Type','application/javascript');res.end(bundle.outputFiles[0].text);return;}
    if(req.url==='/locales/strings.json'){res.setHeader('Content-Type','application/json');res.end(strings);return;}
    if(req.url.startsWith('/api/events')){res.setHeader('Content-Type','application/json');res.end('[]');return;}
    res.setHeader('Content-Type','text/html');res.end(`<html><head><style>
      :root{--pane-header-height:32px;--space-1:4px;--space-2:8px;--space-3:12px;--font-size-xs:11px;--font-size-sm:12px;--radius-sm:3px;--accent:#5599ee;--accent-soft:#193c62;--accent-border:#5599ee;--surface:#101820;--surface-muted:#1c2834;--text:#eee;--text-strong:#fff;--muted:#aaa;--warning:#ffbb44;--success:#44ddaa;--line:#444}
      *{box-sizing:border-box}body{margin:0;background:#101820;color:#eee}.fixture{height:600px;min-width:0}.events-card{height:100%;min-height:0}.event-row{display:grid;width:100%;align-items:center;text-align:left}
      ${css}${tooltipCss}
    </style></head><body><div id='root'></div><script src='/fixture.js'></script></body></html>`);
  });
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const chrome=spawn(chromePath,['--headless','--no-sandbox','--disable-dev-shm-usage','--remote-debugging-port=0','about:blank'],{stdio:['ignore','ignore','pipe']});
  let log='';chrome.stderr.on('data',buffer=>log+=buffer);
  let socket;
  try{
    for(let i=0;i<100&&!log.includes('DevTools listening');i++)await sleep(50);
    const port=log.match(/DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)/)?.[1];assert.ok(port,'Chromium must start');
    const tab=await(await fetch(`http://127.0.0.1:${port}/json/new?http://127.0.0.1:${server.address().port}`,{method:'PUT'})).json();
    socket=new WebSocket(tab.webSocketDebuggerUrl);await once(socket,'open');
    let seq=0;const pending=new Map();const errors=[];
    socket.on('message',buffer=>{const message=JSON.parse(buffer);if(message.id){const p=pending.get(message.id);pending.delete(message.id);message.error?p.reject(message.error):p.resolve(message.result);}if(message.method==='Runtime.exceptionThrown')errors.push(message.params);});
    const call=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;pending.set(id,{resolve,reject});socket.send(JSON.stringify({id,method,params}));});
    const evaluate=async expression=>{const result=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});assert.ok(!result.exceptionDetails,JSON.stringify(result.exceptionDetails));return result.result.value;};
    const wait=async expression=>{for(let i=0;i<100;i++){if(await evaluate(expression))return;await sleep(50);}assert.fail(expression);};
    const button=key=>`document.querySelector('[data-tooltip-key="tooltip.${key}"]')`;
    const key=async(key,virtualKey)=>{await call('Input.dispatchKeyEvent',{type:'keyDown',key,code:key,windowsVirtualKeyCode:virtualKey});await call('Input.dispatchKeyEvent',{type:'keyUp',key,code:key,windowsVirtualKeyCode:virtualKey});await sleep(60);};
    await call('Runtime.enable');await call('Emulation.setDeviceMetricsOverride',{width:1400,height:700,deviceScaleFactor:1,mobile:false});
    await wait("!!document.querySelector('.event-context-raw[open]')&&!!document.querySelector('.event-context-related-action')");
    assert.deepEqual(await evaluate("Array.from(document.querySelectorAll('.event-context-actions button'),button=>button.dataset.tooltipKey)"),['tooltip.setDashboardTime','tooltip.relatedEvent','tooltip.inspect','tooltip.closeEventDetail']);
    assert.ok(await evaluate(`${button('inspect')}.querySelector('svg').classList.contains('lucide-chart-line')`));
    assert.ok(await evaluate(`${button('relatedEvent')}.querySelector('svg').classList.contains('lucide-arrow-right-left')`));
    assert.equal(await evaluate(`${button('inspect')}.textContent`),'');
    assert.equal(await evaluate(`${button('relatedEvent')}.textContent`),'');
    assert.ok(await evaluate("document.querySelector('.event-context-related-info').textContent.includes('Event 20')"));

    // The browser owns toggling; same-ID updates retain it, a new ID opens again.
    await evaluate("document.querySelector('.event-context-raw summary').click()");await wait("!document.querySelector('.event-context-raw').open");
    await evaluate('updateRaw()');await sleep(80);
    assert.equal(await evaluate("document.querySelector('.event-context-raw').open"),false);
    assert.match(await evaluate("document.querySelector('.event-context-raw pre').textContent"),/"version": 1/);
    await evaluate("select('event-11')");await wait("document.querySelector('.event-context-raw').open&&!document.querySelector('.event-context-related-action')");
    await evaluate("select('event-10')");await wait("!!document.querySelector('.event-context-related-action')");

    // Inspector is an explicit action, never a row selection or time change.
    await evaluate(`${button('inspect')}.focus()`);await wait("document.querySelector('[role=tooltip]')?.textContent==='Inspect'");
    await key('Enter',13);assert.deepEqual(await evaluate('inspectCalls'),['event-10']);
    assert.deepEqual(await evaluate('({selected:state.selected,sync:syncCalls.length})'),{selected:'event-10',sync:0});
    await evaluate(`${button('relatedEvent')}.focus()`);await wait("document.querySelector('[role=tooltip]')?.textContent.includes('Go to related event')");
    const relatedTooltip=await evaluate("document.querySelector('[role=tooltip]').textContent");
    assert.match(relatedTooltip,/Event 20/);assert.ok(relatedTooltip.includes(await evaluate(`${button('relatedEvent')}.dataset.tooltipTime`)));
    await evaluate("changeLocale('ja')");await sleep(80);
    await evaluate(`${button('inspect')}.focus();${button('relatedEvent')}.focus()`);await wait("document.querySelector('[role=tooltip]')?.textContent.includes('関連イベントへ移動')");
    await key('Enter',13);await wait("state.selected==='event-20'");assert.equal(await evaluate('syncCalls.length'),0);
    assert.ok(await evaluate("document.activeElement.dataset.eventId==='event-20'"));
    await evaluate('configure({sync:true})');await sleep(80);await evaluate(`${button('relatedEvent')}.click()`);
    await wait("state.selected==='event-10'&&syncCalls.length===1");assert.equal(await evaluate('syncCalls[0]'),1700000010);
    await evaluate(`${button('setDashboardTime')}.click()`);assert.equal(await evaluate('syncCalls.length'),2);

    const artifacts=fs.mkdtempSync('/tmp/stm-events-detail-');
    // Sticky controls must stay in the detail scroller, not cover log rows.
    for(const [width,inline,label] of [[1400,false,'wide'],[360,false,'narrow'],[280,true,'inline']]){
      await call('Emulation.setDeviceMetricsOverride',{width,height:700,deviceScaleFactor:1,mobile:false});
      await evaluate(`configure({inline:${inline},sync:false})`);await sleep(100);
      if(inline)await evaluate("document.querySelector('.event-context').scrollIntoView({block:'nearest'})");
      await evaluate("document.querySelector('.event-context').scrollTop=10000");await sleep(60);
      const geometry=await evaluate(`(()=>{const context=document.querySelector('.event-context');const header=context.querySelector('.event-context-header');const c=context.getBoundingClientRect();const h=header.getBoundingClientRect();return {top:h.top-c.top,bottom:h.bottom-c.bottom,overflow:context.scrollWidth-context.clientWidth,position:getComputedStyle(header).position,height:context.clientHeight,scroll:context.scrollTop,contained:Array.from(header.querySelectorAll('button')).every(button=>{const b=button.getBoundingClientRect();return b.left>=c.left&&b.right<=c.right&&b.top>=c.top&&b.bottom<=c.bottom})}})()`);
      assert.equal(geometry.position,'sticky');assert.ok(geometry.scroll>0);
      assert.ok(geometry.top>=0&&geometry.top<2&&geometry.bottom<0,`${label}: ${JSON.stringify(geometry)}`);
      assert.equal(geometry.overflow,0,`${label}: no horizontal overflow`);assert.ok(geometry.contained,`${label}: actions remain visible`);
      if(inline)assert.ok(geometry.height>=138&&geometry.height<=200);
      fs.writeFileSync(path.join(artifacts,label+'.png'),Buffer.from((await call('Page.captureScreenshot',{format:'png'})).data,'base64'));
      await evaluate(`${button('inspect')}.click()`);assert.equal(await evaluate('state.selected'),'event-10');
    }
    await evaluate('configure({actions:false,hideRelated:true})');await sleep(150);
    assert.equal(await evaluate(`${button('inspect')}===null&&${button('setDashboardTime')}===null&&${button('relatedEvent')}===null`),true);
    await evaluate(`${button('closeEventDetail')}.focus()`);await key('Escape',27);
    await wait("state.selected===null&&!document.querySelector('.event-context')");
    assert.equal(await evaluate('document.activeElement.dataset.eventId'),'event-10');
    t.diagnostic(`Screenshots: ${artifacts}`);assert.deepEqual(errors,[]);
  }finally{
    socket?.close();chrome.kill('SIGTERM');await new Promise(resolve=>server.close(resolve));
  }
});

