  inset: 0;
  z-index: 3;
  pointer-events: none;
}

.event-column-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 10px;
  transform: translateX(-50%);
  cursor: col-resize;
  pointer-events: auto;
  touch-action: none;
}

.events-jump-latest {
  position: absolute;
  right: var(--space-2);
  bottom: var(--space-2);
  z-index: 4;
  min-height: 24px;
  padding: 0 var(--space-2);
  border: 1px solid var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--accent);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.events-jump-latest:hover {
  background: var(--accent-soft);
}

.event-column-resizer::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 4px;
  width: 1px;
  background: transparent;

