      if (cancelled || results === null) return;
      if (relation.boundaryTypes) relationHistoryRef.current = { sourceId: source.id, events: results };
      const related = findRelatedEvent([...relationEventsRef.current, ...results], source, relation);
      if (related || relation.boundaryTypes) setRelatedEvent(related ? { sourceId: source.id, event: related } : null);
